(window.HADITH_BABS = window.HADITH_BABS || {})["muslim"] = {"1":[[1,"Chapter: Explaining Al-Iman (Faith), Al-Islam, and Al-Ihsan, and The Obligations of Al-Iman With Affirmation of The Qadar of Allah, Glorious And Most High is He. And Explaining The Evidence For Declaring One's Innocence Of One Who Does Not Believe In Al-Qadar, And Having A Harsh View Of His Case","باب بيان الإيمان والإسلام والإحسان ووجوب الإيمان بإثبات قدر الله سبحانه وتعالى وبيان الدليل على التبري ممن لا يؤمن بالقدر وإغلاظ القول في حقه","1"],[5,"Chapter: What is Al-Iman (Faith)? Explaining Its Characteristics","باب الإِيمَانُ مَا هُوَ وَبَيَانُ خِصَالِهِ","1"],[7,"Chapter: What is Islam? Explaining its characteristics.","باب الإِسْلاَمُ مَا هُوَ وَبَيَانُ خِصَالِهِ","1"],[8,"Chapter: Explaining the prayers which are one of the pillars of Islam","باب بَيَانِ الصَّلَوَاتِ الَّتِي هِيَ أَحَدُ أَرْكَانِ الإِسْلاَمِ","2"],[10,"Chapter: Asking about the pillars of Islam","باب السُّؤَالِ عَنْ أَرْكَانِ الْإِسْلَامِ","3"],[12,"Chapter: Explaining the faith by means of which a person is admitted into paradise, and that the one who adheres to what is enjoined upon him will enter paradise","باب بَيَانِ الإِيمَانِ الَّذِي يُدْخَلُ بِهِ الْجَنَّةُ وَأَنَّ مَنْ تَمَسَّكَ بِمَا أُمِرَ بِهِ دَخَلَ الجَنَّةَ","4"],[19,"Chapter: Clarifying the pillars of Islam and its grand supports","باب بَيَانِ أَرْكَانِ الْإِسْلَامِ وَدَعَائِمِهِ الْعِظَامِ","5"],[23,"Chapter: The command to believe in Allah and His Messenger (saws) and the laws of Islam, calling people to it, asking about it, memorizing it and conveying it to those who have not heard the message","باب الْأَمْرِ بِالْإِيمَانِ بِاللَّهِ تَعَالَى وَرَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَشَرَائِعِ الدِّينِ","6"],[29,"Chapter: Calling people to the twin declaration of faith and the laws of Islam","باب الدُّعَاءِ إِلَى الشَّهَادَتَيْنِ وَشَرَائِعِ الإِسْلاَمِ","7"],[32,"Chapter: The command to fight the people until they say \"La ilaha illallah Muhammad Rasul-Allah\", and establish Salat, and pay the Zakat, and believe in everything that the prophet (saws) brought. Whoever does that, his life and his wealth are protected except by its right, and his secrets are entrusted to Allah, the most high. Fighting those who withhold Zakat or other than that is one of the duties of Islam and the Imam should be concerned with the Laws of Islam","باب الأَمْرِ بِقِتَالِ النَّاسِ حَتَّى يَقُولُوا لاَ إِلَهَ إِلاَّ اللَّهُ مُحَمَّدٌ رَسُولُ اللَّهِ ويقيموا الصلاة ويؤتوا الزكاة ويؤمنوا بجميع ما جاء به النبي صلى الله عليه وسلم وأن من فعل ذلك عصم نفسه وماله إلا بحقها ووكلت سريرته إلى الله تعالى وقتال من منع الزكاة أو غيرها من حقوق الإسلام واهتمام الإمام بشعائر الإسلام","8"],[39,"Chapter: Evidence that the islam of one who becomes muslim on his deathbed is valid, so long as the death thoes have not begun; Abrogation of permission to supplicate for forgiveness for the idolators; Evidence that one who dies an idolator is one of the people of hell and no intervention can save him from that","باب الدليل على صحة إسلام من حضره الموت ما لم يشرع في النزع وهو الغرغرة ونسخ جواز الاستغفار للمشركين والدليل على أن من مات على الشرك فهو في أصحاب الجحيم ولا ينقذه من ذلك شيء من الوسائل","9"],[43,"Chapter: The evidence that one who dies believing in tawhid will definitely enter paradise","باب مَنْ لَقِيَ اللَّهَ بِالإِيمَانِ وَهُوَ غَيْرُ شَاكٍّ فِيهِ دَخَلَ الْجَنَّةَ وَحَرُمَ عَلَى النَّارِ","10"],[58,"Chapter: Evidence that the one who is content with Allah as his Lord, Islam as his religion and Muhammad (saws) as his prophet, then he is a believer, even if he commits major sins","بَاب الدَّلِيلِ عَلَى أَنَّ مَنْ رَضِيَ بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا وَبِمُحَمَّدٍ رَسُولًا فَهُوَ مُؤْمِنٌ وَإِنْ ارْتَكَبَ الْمَعَاصِيَ الْكَبَائِرَ","11"],[59,"Chapter: Clarifying the number of branches of faith, the best and the least of them, the virtue of modesty (Al-Haya') and the fact that it is part of faith","باب بَيَانِ عَدَدِ شُعَبِ الْإِيمَانِ وَأَفْضَلِهَا وَأَدْنَاهَا وَفَضِيلَةِ الْحَيَاءِ وَكَوْنِهِ مِنْ الْإِيمَانِ","12"],[66,"Chapter: A phrase that sums up Islam","باب جَامِعِ أَوْصَافِ الإِسْلاَمِ","13"],[67,"Chapter: Clarifying the superiority of Islam, and what part of it is best","باب بَيَانِ تَفَاضُلِ الإِسْلاَمِ وَأَىِّ أُمُورِهِ أَفْضَلُ","14"],[72,"Chapter: Clarification of those characteristics which, if a person attains them, he will find the sweetness of faith","باب بَيَانِ خِصَالٍ مَنِ اتَّصَفَ بِهِنَّ وَجَدَ حَلاَوَةَ الإِيمَانِ","15"],[75,"Chapter: The obligation to love the messenger of Allah (saws) more than one's family, son, father, and all other people; And mentions of an absolute absence of faith regarding one who does not love him with such love","باب وُجُوبِ مَحَبَّةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَكْثَرَ مِنَ الأَهْلِ وَالْوَلَدِ وَالْوَالِدِ وَالنَّاسِ أَجْمَعِينَ وَإِطْلاَقِ عَدَمِ الإِيمَانِ عَلَى مَنْ لَمْ يُحِبَّهُ هَذِهِ الْمَحَبَّةَ","16"],[77,"Chapter: The evidence that one of the attributes of faith is to love for one's brother muslim that one loves for oneself of goodness","باب الدَّلِيلِ عَلَى أَنَّ مِنْ خِصَالِ الإِيمَانِ أَنْ يُحِبَّ لأَخِيهِ الْمُسْلِمِ مَا يُحِبُّ لِنَفْسِه مِنَ الْخَيْرِ","17"],[79,"Chapter: Clarifying the prohibition of annoying one's neighbor","باب بَيَانِ تَحْرِيمِ إِيذَاءِ الْجَارِ","18"],[80,"Chapter: Encouragement to honor one's neighbor and guest, and the obligation to remain silent unless one has something good to say, and the fact that all of that is part of faith","باب الْحَثِّ عَلَى إِكْرَامِ الْجَارِ وَالضَّيْفِ وَلُزُومِ الصَّمْتِ إِلاَّ مِنَ الْخَيْرِ وَكَوْنِ ذَلِكَ كُلِّهِ مِنَ الإِيمَانِ","19"],[84,"Chapter: Clarifying that forbidding evil is part of faith, faith increases and decreases; Enjoying what is good and forbidding what is evil are obligatory","باب بَيَانِ كَوْنِ النَّهْىِ عَنِ الْمُنْكَرِ، مِنَ الإِيمَانِ وَأَنَّ الإِيمَانَ يَزِيدُ وَيَنْقُصُ وَأَنَّ الأَمْرَ بِالْمَعْرُوفِ وَالنَّهْيَ عَنِ الْمُنْكَرِ وَاجِبَانِ","20"],[88,"Chapter: People excel over one another in faith, and the superiority of the people of Yemen in faith","باب تَفَاضُلِ أَهْلِ الإِيمَانِ فِيهِ وَرُجْحَانِ أَهْلِ الْيَمَنِ فِيهِ","21"],[101,"Chapter: Clarifying that no one will enter paradise but the believers; loving the believers is part of faith and spreading Salam is a means of attaining that","باب بَيَانِ أَنَّهُ لاَ يَدْخُلُ الْجَنَّةَ إِلاَّ الْمُؤْمِنُونَ وَأَنَّ مَحَبَّةَ الْمُؤْمِنِينَ مِنَ الإِيمَانِ وَأَنَّ إِفْشَاءَ السَّلاَمِ سَبَبٌ لِحُصُولِهَا","22"],[103,"Chapter: Clarifying that the religion is sincerity","باب بَيَانِ أَنَّ الدِّينَ النَّصِيحَةُ","23"],[109,"Chapter: Clarifying that faith decreases because of disobedience and negating it from the one committing the act of disobedience, with the meaning of negating its completion","باب بَيَانِ نُقْصَانِ الإِيمَانِ بِالْمَعَاصِي وَنَفْيِهِ عَنِ الْمُتَلَبِّسِ بِالْمَعْصِيَةِ عَلَى إِرَادَةِ نَفْيِ كَمَالِهِ","24"],[116,"Chapter: The characteristics of the hypocrite","باب بَيَانِ خِصَالِ الْمُنَافِقِ","25"],[121,"Chapter: Clarifying the condition of faith for one who says to his muslim brother: \"O Kafir (Disbeliever).\"","باب بَيَانِ حَالِ إِيمَانِ مَنْ قَالَ لأَخِيهِ الْمُسْلِمِ يَا كَافِرُ","26"],[123,"Chapter: Clarifying the condition of the fath of one who knowingly denies his father","باب بَيَانِ حَالِ إِيمَانِ مَنْ رَغِبَ عَنْ أَبِيهِ وَهُوَ يَعْلَمُ","27"],[127,"Chapter: Clarifying the words of the prophet (saws): \"Insulting A Muslim is an evil action and fighting him is disbelief (Kufr)\"","باب بَيَانِ قَوْلِ النَّبِيِّ صلى الله عليه وسلم \" سِبَابُ الْمُسْلِمِ فُسُوقٌ وَقِتَالُهُ كُفْرٌ \"","28"],[129,"Chapter: Clarifying the meaning of the Statement of the Prophet (saws): \"Do not revert to disbelief (Kuffar) after I am Gone, striking one another's necks\"","باب \" لاَ تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكمْ رِقَابَ بَعْضٍ \"","29"],[133,"Chapter: Use of the word Kufr with regard to slandering people's lineage and wailing","باب إِطْلاَقِ اسْمِ الْكُفْرِ عَلَى الطَّعْنِ فِي النَّسَبِ وَالنِّيَاحَةِ عَلَى الْمَيِّتِ","30"],[134,"Chapter: Calling a runaway slave a kafirg","باب تَسْمِيَةِ الْعَبْدِ الآبِقِ كَافِرًا","31"],[137,"Chapter: Clarifying the Kufr of one who says: \"We got rain because of the stars.\"","باب بَيَانِ كُفْرِ مَنْ قَالَ مُطِرْنَا بِالنَّوْءِ","32"],[141,"Chapter: Evidence that love of the Ansar and Ali (r.a.) is a part of faith and a sign thereof; Hating them is a sign of hypocrisy","باب الدَّلِيلِ عَلَى أَنَّ حُبَّ الأَنْصَارِ وَعَلِيٍّ رَضِيَ اللَّهُ عَنْهُمْ مِنَ الإِيمَانِ وَعَلاَمَاتِهِ وَبُغْضَهُمْ مِنْ عَلاَمَاتِ النِّفَاقِ","33"],[147,"Chapter: Clarifying that faith decreases with shortcoming in obedience, and the word Kufr may be used with regard to matters other than dsbelief in Allah, such as ingratitude for blessings and not fulfilling one's duties","باب بَيَانِ نُقْصَانِ الإِيمَانِ بِنَقْصِ الطَّاعَاتِ وَبَيَانِ إِطْلاَقِ لَفْظِ الْكُفْرِ عَلَى غَيْرِ الْكُفْرِ بِاللَّهِ كَكُفْرِ النِّعْمَةِ وَالْحُقُوقِ","34"],[151,"Chapter: Clarifying the usage of the word Kafir for one who abandons Salat","باب بَيَانِ إِطْلاَقِ اسْمِ الْكُفْرِ عَلَى مَنْ تَرَكَ الصَّلاَةَ","35"],[155,"Chapter: Clarifying that faith in Allah most high is the best of deeds","باب بَيَانِ كَوْنِ الإِيمَانِ بِاللَّهِ تَعَالَى أَفْضَلَ الأَعْمَالِ","36"],[163,"Chapter: Clarifying that Shirk is the worst of sins, and the worst sins after Shirk","باب كَوْنِ الشِّرْكِ أَقْبَحَ الذُّنُوبِ وَبَيَانِ أَعْظَمِهَا بَعْدَهُ","37"],[165,"Chapter: The major sins and the most serious of them","باب بَيَانِ الْكَبَائِرِ وَأَكْبَرِهَا","38"],[171,"Chapter: The prohibition of pride and definition of it","باب تَحْرِيمِ الْكِبْرِ وَبَيَانِهِ","39"],[174,"Chapter: The evidence that the one who dies not associating anything with Allah will enter paradise, and the one who dies as idolator will enter the fire","باب مَنْ مَاتَ لاَ يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الْجَنَّةَ وَمَنْ مَاتَ مُشْرِكًا دَخَلَ النَّارَ","40"],[180,"Chapter: The prohibition of killing a disbeliever after he says La ilaha illallah","باب تَحْرِيمِ قَتْلِ الْكَافِرِ بَعْدَ أَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ","41"],[186,"Chapter: The Saying of the prophet (saws): \"Whoever bears weapons against us is not one of us.\"","باب قَوْلِ النَّبِيِّ - صلى الله تعالى عليه وسلم - \" مَنْ حَمَل عَلَيْنَا السِّلاَحَ فَلَيْسَ مِنَّا \"","42"],[189,"Chapter: The Saying of the prophet (saws): \"Whoever deceives us is not one of us.\"","باب قَوْلِ النَّبِيِّ - صلى الله تعالى عليه وسلم - \" مَنْ غَشَّنَا فَلَيْسَ مِنَّا \"","43"],[191,"Chapter: The prohibition of striking one's checks, tearing one's garment and calling with the calls of Jahilliyyah","باب تَحْرِيمِ ضَرْبِ الْخُدُودِ وَشَقِّ الْجُيُوبِ وَالدُّعَاءِ بِدَعْوَى الْجَاهِلِيَّةِ","44"],[196,"Chapter: Clarifying the emphatic prohibition of An-Namimah (Malicious Gossip)","باب بَيَانِ غِلَظِ تَحْرِيمِ النَّمِيمَةِ","45"],[199,"Chapter: Clarifying the emphatic prohibition of letting one's garment hang below the ankles (isbal), reminding others of one's gift and selling goods by means of a false oath; Mention of the three to whom Allah, Most High, will not speak on the day of resurrection, nor look at them, nor sanctify them, and theirs will be a painful torment","باب بَيَانِ غِلَظِ تَحْرِيمِ إِسْبَالِ الإِزَارِ وَالْمَنِّ بِالْعَطِيَّةِ وَتَنْفِيقِ السِّلْعَةِ بِالْحَلِفِ وَبَيَانِ الثَّلاَثَةِ الَّذِينَ لاَ يُكَلِّمُهُمُ اللَّهُ يَوْمَ الْقِيَامَةِ وَلاَ يَنْظُرُ إِلَيْهِمْ وَلاَ يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ","46"],[206,"Chapter: Clarifying the emphatic prohibition against killing oneself; The one who kills himself with something will be punished with it in the fire; And that no one will enter Paradise but a muslim","باب غِلَظِ تَحْرِيمِ قَتْلِ الإِنْسَانِ نَفْسَهُ وَإِنَّ مَنْ قَتَلَ نَفْسَهُ بِشَيْءٍ عُذِّبَ بِهِ فِي النَّارِ وَأَنَّهُ لاَ يَدْخُلُ الْجَنَّةَ إِلاَّ نَفْسٌ مُسْلِمَةٌ","47"],[216,"Chapter: Emphatic prohibition against stealing from the spoils of war; and that no one will enter paradise except the believers","باب غِلَظِ تَحْرِيمِ الْغُلُولِ وَأَنَّهُ لاَ يَدْخُلُ الْجَنَّةَ إِلاَّ الْمُؤْمِنُونَ","48"],[218,"Chapter: The evidence that the one who kills himself is not considered a disbeliever","باب الدَّلِيلِ عَلَى أَنَّ قَاتِلَ نَفْسِهِ لاَ يَكْفُرُ","49"],[219,"Chapter: Regarding the wind which will come just before the resurrection and take the soul of anyone who has any fath in his heart","باب فِي الرِّيحِ الَّتِي تَكُونُ قُرْبَ الْقِيَامَةِ تَقْبِضُ مَنْ فِي قَلْبِهِ شَىْءٌ مِنَ الإِيمَانِ","50"],[220,"Chapter: Encouragement to hasten to do good deeds before the emergence of the Fitnah","باب الْحَثِّ عَلَى الْمُبَادَرَةِ بِالأَعْمَالِ قَبْلَ تَظَاهُرِ الْفِتَنِ","51"],[221,"Chapter: The believer's fear that his good deeds may be lost","باب مَخَافَةِ الْمُؤْمِنِ أَنْ يَحْبَطَ عَمَلُهُ","52"],[225,"Chapter: Will a person be punished for his actions during the Jahlilliyyah?","باب هَلْ يُؤَاخَذُ بِأَعْمَالِ الْجَاهِلِيَّةِ","53"],[228,"Chapter: Islam destroys that which came before it, as do Hijrah (Emigration) and Hajj","باب كَوْنِ الإِسْلاَمِ يَهْدِمُ مَا قَبْلَهُ وَكَذَا الْهِجْرَةُ وَالْحَجُّ","54"],[230,"Chapter: Clarifying the ruling of the action of an unbeliever if he accepts Islam after it","باب بَيَانِ حُكْمِ عَمَلِ الْكَافِرِ إِذَا أَسْلَمَ بَعْدَهُ","55"],[234,"Chapter: Sincerity of Faith and its Purity","باب صِدْقِ الإِيمَانِ وَإِخْلاَصِهِ","56"],[236,"Chapter: Clarification that Allah, most high allows a person's thoughts and whatever occurs in his heart, so long as they do not become established, and the clarification that he, glorious is he and most high, does not burden anyone with more than he can bear, and clarifying the ruling on thinking of doing good and bad deeds","باب بَيَانِ أَنَّهُ سُبْحَانَهُ وَتَعَالَى لَمْ يُكَلِّفْ إِلَّا مَا يُطَاقُ","57"],[238,"Chapter: Allah allows a person's thoughts and whatever occurs in his heart so long as they do not become established","باب تَجَاوُزِ اللَّهِ عَنْ حَدِيثِ النَّفْسِ، وَالْخَوَاطِرِ، بِالْقَلْبِ إِذَا لَمْ تَسْتَقِرَّ","58"],[241,"Chapter: If a person thinks of doing a good deed it will be recorded for him, and if he thinks of doing a bad deed it will not be recorded for him","باب إِذَا هَمَّ الْعَبْدُ بِحَسَنَةٍ كُتِبَتْ وَإِذَا هَمَّ بِسَيِّئَةٍ لَمْ تُكْتَبْ","59"],[247,"Chapter: Clarifying the Waswasah (Whispers, Bad Thoughts) with regard to faith, and what the one who experiences that should say","باب بَيَانِ الْوَسْوَسَةِ فِي الإِيمَانِ وَمَا يَقُولُهُ مَنْ وَجَدَهَا","60"],[260,"Chapter: Warning of the Fire for the one who swears a false oath in order to unlawfully take the right of another muslim","باب وَعِيدِ مَنِ اقْتَطَعَ حَقَّ مُسْلِمٍ بِيَمِينٍ فَاجِرَةٍ بِالنَّارِ","61"],[267,"Chapter: The evidence that the blood of one who aims to seize other people's wealth without right may be shed, if he is killed he will be in the fire, and the one who is killed defending his property is a martyr","باب الدَّلِيلِ عَلَى أَنَّ مَنْ قَصَدَ أَخْذَ مَالِ غَيْرِهِ بِغَيْرِ حَقٍّ كَانَ الْقَاصِدُ مُهْدَرَ الدَّمِ فِي حَقِّهِ وَإِنْ قُتِلَ كَانَ فِي النَّارِ وَأَنَّ مَنْ قُتِلَ دُونَ مَالِهِ فَهُوَ شَهِيدٌ","62"],[270,"Chapter: One in charge of a matter, who cheats his subjects, deserves the fire","باب اسْتِحْقَاقِ الْوَالِي الْغَاشِّ لِرَعِيَّتِهِ النَّارَ","63"],[274,"Chapter: The disappearance of honesty and faith from some hearts and the appearance of fitnah in some hearts","باب رَفْعِ الأَمَانَةِ وَالإِيمَانِ مِنْ بَعْضِ الْقُلُوبِ وَعَرْضِ الْفِتَنِ عَلَى الْقُلُوبِ","64"],[276,"Chapter: Clarifying that Islam started as something strange, and will revert to being something strange, and it will retreat between the two Masajid","باب بَيَانِ أَنَّ الْإِسْلَامَ بَدَأَ غَرِيبًا وَسَيَعُودُ غَرِيبًا وَأَنَّهُ يَأْرِزُ بَيْنَ الْمَسْجِدَيْنِ","65"],[282,"Chapter: The Disappearance of Faith at the End of Time","باب ذَهَابِ الإِيمَانِ آخِرَ الزَّمَانِ","66"],[284,"Chapter: Permissibility of concealing one's faith in the case of fear","باب جَوَازِ الاِسْتِسْرَارِ لِلْخَائِفِ","67"],[285,"Chapter: Being kind to one for whose faith there is concern because it is weak; Prohibition of attributing Faith to someone without definitive evidence","باب تَأَلُّفِ قَلْبِ مَنْ يَخَافُ عَلَى إِيمَانِهِ لِضَعْفِهِ وَالنَّهْيِ عَنِ الْقَطْعِ بِالإِيمَانِ مِنْ غَيْرِ دَلِيلٍ قَاطِعٍ","68"],[289,"Chapter: Increasing the heart's tranquility with the appearance evidence","باب زِيَادَةِ طُمَأْنِينَةِ الْقَلْبِ بِتَظَاهُرِ الأَدِلَّةِ","69"],[291,"Chapter: Obligation of believing that the message of our Prophet Muhammad (saws) is for all people, and the abrogation of all other religions","باب وُجُوبِ الإِيمَانِ بِرِسَالَةِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى جَمِيعِ النَّاسِ وَنَسْخِ الْمِلَلِ بِمِلَّتِهِ","70"],[294,"Chapter: The descent of 'Eisa bin Mariam to judge according to the Shari'ah of our Prophet Muhammad (saws); And how Allah has honored this Ummah; And clarifying the evidence that this religion will not be abrogated; and that a group from it will continue to adhere to the truth and prevail until the day of resurrection","باب نُزُولِ عِيسَى ابْنِ مَرْيَمَ حَاكِمًا بِشَرِيعَةِ نَبِيِّنَا مُحَمَّدٍ صلى الله عليه وسلم","71"],[301,"Chapter: Clarifying the time when faith will no longer be accepted","باب بَيَانِ الزَّمَنِ الَّذِي لاَ يُقْبَلُ فِيهِ الإِيمَانُ","72"],[308,"Chapter: The beginning of the revelation to the messenger of Allah (saws)","باب بَدْءِ الْوَحْىِ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم","73"],[316,"Chapter: The night journey on which the messenger of Allah (saws) was taken up into the heavens and the prayers were enjoined","باب الإِسْرَاءِ بِرَسُولِ اللَّهِ صلى الله عليه وسلم إِلَى السَّمَوَاتِ وَفَرْضِ الصَّلَوَاتِ","74"],[330,"Chapter: Mentioning Al-Masih Son of Mariam and Al-Masih ad-Dajjal","باب فِي ذِكْرِ الْمَسِيحِ ابْنِ مَرْيَمَ وَالْمَسِيحِ الدَّجَّالِ","75"],[336,"Chapter: About (The Lote-Tree of the Utmost Boundary)","باب فِي ذِكْرِ سِدْرَةِ الْمُنْتَهَى","76"],[340,"Chapter: The Meaning of the Saying of Allah, The Mighty and Sublime: And indeed he saw him at a second descent (another time)\"; And did the prophet (saws) see his lord on the night of the Isra?","باب مَعْنَى قَوْلِ اللَّهِ عَزَّ وَجَلَّ: {وَلَقَدْ رَآهُ نَزْلَةً أُخْرَى} وَهَلْ رَأَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَبَّهُ لَيْلَةَ الإِسْرَاءِ","77"],[348,"Chapter: The saying of the Prophet (saws): \"Light, How could I see Him?\" and: \"I saw Light\"","باب فِي قَوْلِهِ عَلَيْهِ السَّلاَمُ \" نُورٌ أَنَّى أَرَاهُ \" . وَفِي قَوْلِهِ \" رَأَيْتُ نُورًا","78"],[350,"Chapter: The saying of the Prophet (saws): \"Allah does not sleep\" and \"His veil is light, and if he were to remove it, the splendour of his face would burn all of his creation, as far as hs sght reaches\".","باب فِي قَوْلِهِ عَلَيْهِ السَّلاَمُ: «إِنَّ اللَّهَ لاَ يَنَامُ». وَفِي قَوْلِهِ: «حِجَابُهُ النُّورُ لَوْ كَشَفَهُ لأَحْرَقَ سُبُحَاتُ وَجْهِهِ مَا انْتَهَى إِلَيْهِ بَصَرُهُ مِنْ خَلْقِهِ»","79"],[353,"Chapter: Affirming that the believers will see their Lord, Glorious is he and most high, in the hereafter","باب إِثْبَاتِ رُؤْيَةِ الْمُؤْمِنِينَ فِي الآخِرَةِ رَبَّهُمْ سُبْحَانَهُ وَتَعَالَى","80"],[356,"Chapter: Knowing about the seeing","باب مَعْرِفَةِ طَرِيقِ الرُّؤْيَةِ","81"],[362,"Chapter: Intercession and bringing those who believed in tawhid out of the Fire","باب إِثْبَاتِ الشَّفَاعَةِ وَإِخْرَاجِ الْمُوَحِّدِينَ مِنَ النَّارِ","82"],[366,"Chapter: The Last of the people of the Fire to be brought out of it","باب آخِرِ أَهْلِ النَّارِ خُرُوجًا","83"],[369,"Chapter: The Status of the Lowest people in paradise","باب أَدْنَى أَهْلِ الْجَنَّةِ مَنْزِلَةً فِيهَا","84"],[389,"Chapter: Regarding the saying of the Prophet (saws): \"I will be the first of the people to intercede concerning Paradise, and I will be the Prophet with the Greatest Number of Followers.\"","باب فِي قَوْلِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «أَنَا أَوَّلُ النَّاسِ يَشْفَعُ فِي الْجَنَّةِ وَأَنَا أَكْثَرُ الأَنْبِيَاءِ تَبَعًا»","85"],[393,"Chapter: The Prophet (saws) will defer his supplication in order to intercede for his ummah","باب اخْتِبَاءِ النَّبِيِّ صلى الله عليه وسلم دَعْوَةَ الشَّفَاعَةِ لأُمَّتِهِ","86"],[405,"Chapter: The supplication of the Prophet (saws) for his ummah and his weeping out of compassion for them","باب دُعَاءِ النَّبِيِّ صلى الله عليه وسلم لأُمَّتِهِ وَبُكَائِهِ شَفَقَةً عَلَيْهِمْ","87"],[406,"Chapter: Clarifying that whoever died upon disbelief then he is in the Fire, and no intercession or relationship with those who are close to Allah will be of any avail for him","باب بَيَانِ أَنَّ مَنْ مَاتَ عَلَى الْكُفْرِ فَهُوَ فِي النَّارِ وَلاَ تَنَالُهُ شَفَاعَةٌ وَلاَ تَنْفَعُهُ قَرَابَةُ الْمُقَرَّبِينَ","88"],[407,"Chapter: Regarding the saying of Allah, the most High: \"And warn your tribe of near kindred.\"","باب فِي قَوْلِهِ تَعَالَى: {وَأَنْذِرْ عَشِيرَتَكَ الأَقْرَبِينَ}","89"],[416,"Chapter: The Intercession of the Prophet (saws) for Abu Talib and the reduction of his punishment as a result","باب شَفَاعَةِ النَّبِيِّ صلى الله عليه وسلم لأَبِي طَالِبٍ وَالتَّخْفِيفِ عَنْهُ بِسَبَبِهِ","90"],[420,"Chapter: The least severely punished of the people of the Fire","باب أَهْوَنِ أَهْلِ النَّارِ عَذَابًا","91"],[424,"Chapter: The evidence that whoever dies upon disbelief, no good deed will benefit him","باب الدَّلِيلِ علَى أَنَّ مَنْ مَاتَ عَلَى الْكُفْرِ لاَ يَنْفَعُهُ عَمَلٌ","92"],[425,"Chapter: Allegiance to the believers, and forsaking others and disavowing them","باب مُوَالاَةِ الْمُؤْمِنِينَ وَمُقَاطَعَةِ غَيْرِهِمْ وَالْبَرَاءَةِ مِنْهُمْ","93"],[426,"Chapter: The Evidence that groups of Muslims will enter Paradise without being called to account, and without being punished","باب الدَّلِيلِ عَلَى دُخُولِ طَوَائِفَ مِنَ الْمُسْلِمِينَ الْجَنَّةَ بِغَيْرِ حِسَابٍ وَلاَ عَذَابٍ","94"],[435,"Chapter: Clarifying that this ummah will form half of the People of Paradise","باب كَوْنِ هَذِهِ الأُمَّةِ نِصْفَ أَهْلِ الْجَنَّةِ","95"],[438,"Chapter: Allah will say to Adam: \"Bring out the Portion of the Fire; Nine Hundred and Ninety-Nine Out of Every Thousand.\"","باب قَوْلِهِ يَقُولُ اللَّهُ لِآدَمَ أَخْرِجْ بَعْثَ النَّارِ مِنْ كُلِّ أَلْفٍ تِسْعَ مِائَةٍ وَتِسْعَةً وَتِسْعِينَ","96"]],"2":[[1,"Chapter: The virtue of wudu’","باب فَضْلِ الْوُضُوءِ","1"],[2,"Chapter: The obligation of purifying oneself for the salat","باب وُجُوبِ الطَّهَارَةِ لِلصَّلاَةِ","2"],[5,"Chapter: The description of wudu’ and its perfection","باب صِفَةِ الْوُضُوءِ وَكَمَالِهِ","3"],[7,"Chapter: The virtue of performing wudu’ and salat","باب فَضْلِ الْوُضُوءِ وَالصَّلاَةِ عَقِبَهُ","4"],[17,"Chapter: The five daily prayers, from one Jumu`ah to the next, and from one Ramadan to the next, are an expiation for whatever (sins) come in between, so long as one avoids major sins","باب الصَّلَوَاتُ الْخَمْسُ وَالْجُمُعَةُ إِلَى الْجُمُعَةِ وَرَمَضَانُ إِلَى رَمَضَانَ مُكَفِّرَاتٌ لِمَا بَيْنَهُنَّ مَا اجْتُنِبَتِ الْكَبَائِرُ.","5"],[20,"Chapter: Adh-Dhikr (the remembrance) which is recommended following wudu’","باب الذِّكْرِ الْمُسْتَحَبِّ عَقِبَ الْوُضُوءِ","6"],[22,"Chapter: Another description of wudu’","باب فِي وُضُوءِ النَّبِيِّ صلى الله عليه وسلم","7"],[27,"Chapter: Odd numbers when rinsing the nose and cleaning oneself with pebbles (istijmar)","باب الإِيتَارِ فِي الاِسْتِنْثَارِ وَالاِسْتِجْمَارِ","8"],[33,"Chapter: The obligation of washing the feet completely","باب وُجُوبِ غَسْلِ الرِّجْلَيْنِ بِكَمَالِهِمَا","9"],[43,"Chapter: The obligation of completely washing all the parts to be washed when purifying oneself","باب وُجُوبِ اسْتِيعَابِ جَمِيعِ أَجْزَاءِ مَحَلِّ الطَّهَارَةِ","10"],[44,"Chapter: Sins exit with the water of wudu’","باب خُرُوجِ الْخَطَايَا مَعَ مَاءِ الْوُضُوءِ","11"],[46,"Chapter: The recommendation to increase the area washed for the forehead, arms, and legs well when performing wudu’","باب اسْتِحْبَابِ إِطَالَةِ الْغُرَّةِ وَالتَّحْجِيلِ فِي الْوُضُوءِ","12"],[53,"Chapter: Adornment (in the hereafter) will reach as far as the wudu’ reached","باب تَبْلُغُ الْحِلْيَةُ حَيْث يَبْلُغُ الْوَضُوءُ","13"],[54,"Chapter: The virtue of isbaghil-wudu’ (performing wudu’ properly) during times when it is difficult to do so","باب فَضْلِ إِسْبَاغِ الْوُضُوءِ عَلَى الْمَكَارِهِ","14"],[56,"Chapter: Siwak (tooth-stick)","باب السِّوَاكِ","15"],[64,"Chapter: The characteristics of the fitrah","باب خِصَالِ الْفِطْرَةِ","16"],[73,"Chapter: Cleaning oneself after relieving oneself","باب الاِسْتِطَابَةِ","17"],[80,"Chapter: The prohibition of cleaning oneself with the right hand","باب النَّهْىِ عَنْ الاِسْتِنْجَاءِ، بِالْيَمِينِ","18"],[83,"Chapter: Starting on the right when purifying oneself and in other matters","باب التَّيَمُّنِ فِي الطُّهُورِ وَغَيْرِهِ","19"],[85,"Chapter: The prohibition of relieving oneself in the street or in the shade","باب النَّهْىِ عَنِ التَّخَلِّي، فِي الطُّرُقِ وَالظِّلاَلِ","20"],[86,"Chapter: Cleaning oneself with water after defecating","باب الاِسْتِنْجَاءِ بِالْمَاءِ مِنَ التَّبَرُّزِ","21"],[89,"Chapter: Wiping over the khuff (leather socks)","باب الْمَسْحِ عَلَى الْخُفَّيْنِ","22"],[100,"Chapter: Wiping over the forehead and the imamah","باب الْمَسْحِ عَلَى النَّاصِيَةِ وَالْعِمَامَةِ","23"],[105,"Chapter: Time-limit for wiping over the khuff","باب التَّوْقِيتِ فِي الْمَسْحِ عَلَى الْخُفَّيْنِ","24"],[108,"Chapter: The permissibility of performing all the prayers with one wudu’","باب جَوَازِ الصَّلَوَاتِ كُلِّهَا بِوُضُوءٍ وَاحِدٍ","25"],[109,"Chapter: It is disliked for the person who wants to perform wudu’, and others, to put his hand in the vessel (containing water) before washing it three times, if he is not sure whether something impure is on his hands or not","باب كَرَاهَةِ غَمْسِ الْمُتَوَضِّئِ وَغَيْرِهِ يَدَهُ الْمَشْكُوكَ فِي نَجَاسَتِهَا فِي الإِنَاءِ قَبْلَ غَسْلِهَا ثَلاَثًا","26"],[114,"Chapter: Rulings on what was licked by a dog","باب حُكْمِ وُلُوغِ الْكَلْبِ","27"],[121,"Chapter: The prohibition of urinating into standing water","باب النَّهْىِ عَنِ الْبَوْلِ، فِي الْمَاءِ الرَّاكِدِ","28"],[124,"Chapter: Prohibition of performing ghusl in standing water","باب النَّهْىِ عَنْ الاِغْتِسَالِ، فِي الْمَاءِ الرَّاكِدِ","29"],[125,"Chapter: The obligation to wash away urine and other impurities if they result in the Masjid, and the ground may be purified with water with no need to scrub it","باب وُجُوبِ غَسْلِ الْبَوْلِ وَغَيْرِهِ مِنَ النَّجَاسَاتِ إِذَا حَصُلَتْ فِي الْمَسْجِدِ وَأَنَّ الأَرْضَ تَطْهُرُ بِالْمَاءِ مِنْ غَيْرِ حَاجَةٍ إِلَى حَفْرِهَا","30"],[128,"Chapter: The ruling on the urine of a nursing infant and how to wash it","باب حُكْمِ بَوْلِ الطِّفْلِ الرَّضِيعِ وَكَيْفِيَّةِ غَسْلِهِ","31"],[134,"Chapter: The ruling on semen","باب حكْمِ الْمَنِيِّ","32"],[141,"Chapter: The impurity of blood and how to wash it","باب نَجَاسَةِ الدَّمِ وَكَيْفِيَّةِ غَسْلِهِ","33"],[143,"Chapter: The evidence that urine is impure and the obligation to take precautions concerning it","باب الدَّلِيلِ عَلَى نَجَاسَةِ الْبَوْلِ وَوُجُوبِ الاِسْتِبْرَاءِ مِنْهُ","34"]],"3":[[1,"Chapter: Touching a menstruating woman above the izar (waist wrapper)","باب مُبَاشَرَةِ الْحَائِضِ فَوْقَ الإِزَارِ","1"],[4,"Chapter: Lying down with a menstruating woman under a single cover","باب الاِضْطِجَاعِ مَعَ الْحَائِضِ فِي لِحَافٍ وَاحِدٍ","2"],[6,"Chapter: It is permissible for a menstruating woman to wash her husband’s head, and comb his hair; her leftovers are pure (tahir); and regarding reclining in her lap and reciting Qur’an","باب جَوَازِ غَسلِ الْحَائِضِ رَأْسَ زَوْجِهَا وَتَرْجِيلِهِ وَطَهَارَةِ سُؤْرِهَا وَالاِتِّكَاءِ فِي حِجْرِهَا وَقِرَاءَةِ الْقُرْآنِ فِيهِ","3"],[17,"Chapter: Madhi (prostatic fluid)","باب الْمَذْىِ","4"],[20,"Chapter: Washing the face and hands when waking from sleep","باب غَسْلِ الْوَجْهِ وَالْيَدَيْنِ إِذَا اسْتَيْقَظَ مِنَ النَّوْمِ","5"],[21,"Chapter: It is permissible for one who is junub to sleep, but it is recommended for him to perform wudu’, and wash his private parts if he wants to eat, drink, sleep, or have intercourse","باب جَوَازِ نَوْمِ الْجُنُبِ وَاسْتِحْبَابِ الْوُضُوءِ لَهُ وَغَسْلِ الْفَرْجِ إِذَا أَرَادَ أَنْ يَأْكُلَ أَوْ يَشْرَبَ أَوْ يَنَامَ أَوْ يُجَامِعَل","6"],[31,"Chapter: Women are obliged to perform ghusl if they emit fluid","باب وُجُوبِ الْغُسْلِ عَلَى الْمَرْأَةِ بِخُرُوجِ الْمَنِيِّ مِنْهَا","7"],[38,"Chapter: Description of the (fluid) of the man and the woman; the child is created from the water of both of them","باب بَيَانِ صِفَةِ مَنِيِّ الرَّجُلِ وَالْمَرْأَةِ وَأَنَّ الْوَلَدَ مَخْلُوقٌ مِنْ مَائِهِمَا","8"],[40,"Chapter: Description of ghusl in the case of janabah (sexual impurity)","باب صِفَةِ غُسْلِ الْجَنَابَةِ","9"],[48,"Chapter: The amount of water with which it is recommended to perform ghusl in the case of janabah; a man and woman washing from a single vessel; one of them washing with the left-over water of the other","باب الْقَدْرِ الْمُسْتَحَبِّ مِنَ الْمَاءِ فِي غُسْلِ الْجَنَابَةِ وَغُسْلِ الرَّجُلِ وَالْمَرْأَةِ فِي إِنَاءٍ وَاحِدٍ فِي حَالَةٍ وَاحِدَةٍ وَغُسْلِ أَحَدِهِمَا بِفَضْلِ الآخَرِ","10"],[62,"Chapter: It is recommended to pour water over the head, and elsewhere, three times","باب اسْتِحْبَابِ إِفَاضَةِ الْمَاءِ عَلَى الرَّأْسِ وَغَيْرِهِ ثَلاَثًا","11"],[66,"Chapter: Ruling on the braids of a woman who is doing ghusl","باب حُكْمِ ضَفَائِرِ الْمُغْتَسِلَةِ","12"],[70,"Chapter: It is recommended for the woman who is performing ghusl following menses to apply a piece of cloth scented with musk to the site of the bleeding","باب اسْتِحْبَابِ اسْتِعْمَالِ الْمُغْتَسِلَةِ مِنَ الْحَيْضِ فِرْصَةً مِنْ مِسْكٍ فِي مَوْضِعِ الدَّمِ","13"],[75,"Chapter: The ghusl and the prayer of a woman who is suffering prolonged vaginal bleeding (istihadah)","باب الْمُسْتَحَاضَةِ وَغُسْلِهَا وَصَلاَتِهَا","14"],[83,"Chapter: A menstruating woman is obliged to make up missed fasts but not prayers","باب وُجُوبِ قَضَاءِ الصَّوْمِ عَلَى الْحَائِضِ دُونَ الصَّلاَةِ","15"],[86,"Chapter: Covering oneself with a garment and the like while performing ghusl","باب تَسَتُّرِ الْمُغْتَسِلِ بِثَوْبٍ وَنَحْوِهِ","16"],[90,"Chapter: The prohibition of looking at `awrah","باب تَحْرِيمِ النَّظَرِ إِلَى الْعَوْرَاتِ","17"],[92,"Chapter: It is permissible to bathe naked when one is alone","باب جَوَازِ الاِغْتِسَالِ عُرْيَانًا فِي الْخَلْوَةِ","18"],[93,"Chapter: Taking care to conceal one’s `awrah","باب الاِعْتِنَاءِ بِحِفْظِ الْعَوْرَةِ","19"],[96,"Chapter: Screening oneself when urinating","باب مَا يُسْتَتَرُ بِهِ لِقَضَاءِ الْحَاجَةِ","20"],[97,"Chapter: At the beginning of Islam, intercourse did not necessitate ghusl unless semen was emitted, then that was abrogated and ghusl becomes obligatory for intercourse","باب إِنَّمَا الْمَاءُ مِنَ الْمَاءِ","21"],[105,"Chapter: Abrogation of “water is for water”, and that it is obligatory to perform ghusl when the two circumcised parts meet","باب نَسْخِ \" الْمَاءُ مِنَ الْمَاءِ \" وَوُجُوبِ الْغُسْلِ بِالْتِقَاءِ الْخِتَانَيْنِ","22"],[109,"Chapter: Performing wudu’ after eating something that has been touched by fire","باب الْوُضُوءِ مِمَّا مَسَّتِ النَّارُ","23"],[112,"Chapter: Abrogation of wudu’ for that which has been touched by fire","باب نَسْخِ \" الْوُضُوءِ مِمَّا مَسَّتِ النَّارُ \"","24"],[123,"Chapter: (Performing) wudu’ after eating camel meat","باب الْوُضُوءِ مِنْ لُحُومِ الإِبِلِ","25"],[125,"Chapter: Evidence that if a person is certain that he is in a state of purity, then he doubts whether he has committed hadith (broken his wudu’), then he prays with his purity like that","باب الدَّلِيلِ عَلَى أَنَّ مَنْ تَيَقَّنَ الطَّهَارَةَ ثُمَّ شَكَّ فِي الْحَدَثِ فَلَهُ أَنْ يُصَلِّيَ بِطَهَارَتِهِ تِلْكَ","26"],[127,"Chapter: Hides of dead animals are purified by tanning","باب طَهَارَةِ جُلُودِ الْمَيْتَةِ بِالدِّبَاغِ","27"],[137,"Chapter: Tayammum","باب التَّيَمُّمِ","28"],[145,"Chapter: Evidence that the Muslim does not become impure","باب الدَّلِيلِ عَلَى أَنَّ الْمُسْلِمَ لاَ يَنْجُسُ","29"],[147,"Chapter: Remembering Allah, the Most High, when one is sexually impure, and at other times","باب ذِكْرِ اللَّهِ تَعَالَى فِي حَالِ الْجَنَابَةِ وَغَيْرِهَا","30"],[148,"Chapter: It is permissible for one who has broken his wudu’ to eat, and there is nothing disliked about doing so, and wudu’ need not be done immediately","باب جَوَازِ أَكْلِ الْمُحْدِثِ الطَّعَامَ وَأَنَّهُ لاَ كَرَاهَةَ فِي ذَلِكَ وَأَنَّ الْوُضُوءَ لَيْسَ عَلَى الْفَوْرِ","31"],[152,"Chapter: What should be said when entering the area in which one relieves himself","باب مَا يَقُولُ إِذَا أَرَادَ دُخُولَ الْخَلاَءِ","32"],[154,"Chapter: Evidence that sleeping while sitting does not invalidate wudu’","باب الدَّلِيلِ عَلَى أَنَّ نَوْمَ الْجَالِسِ لاَ يَنْقُضُ الْوُضُوءَ","33"]],"4":[[1,"Chapter: The Beginning Of The Adhan","باب بَدْءِ الأَذَانِ","1"],[2,"Chapter: The Command to say the phrases of the Adhan twice and the phrases of the iqamah once, except the phrase, \"Prayer is about to begin,\" which is to be said twice","باب الأَمْرِ بِشَفْعِ الأَذَانِ وَإِيتَارِ الإِقَامَةِ","2"],[6,"Chapter: Description Of The Adhan","باب صِفَةِ الأَذَانِ","3"],[7,"Chapter: It Is Recommended To Have Two Mu'adhdhin In A Single Masjid","باب اسْتِحْبَابِ اتِّخَاذِ مُؤَذِّنَيْنِ لِلْمَسْجِدِ الْوَاحِدِ","4"],[9,"Chapter: It Is Permissible For A Blind Man To Call The Adhan So long As There Is A Man With Him Who Sees","باب جَوَازِ أَذَانِ الأَعْمَى إِذَا كَانَ مَعَهُ بَصِيرٌ","5"],[11,"Chapter: Refraining From Attacking People In Dar Al-Kufr (Non-Muslim Lands) If The Adhan Is Heard Among Them","باب الإِمْسَاكِ عَنِ الإِغَارَةِ، عَلَى قَوْمٍ فِي دَارِ الْكُفْرِ إِذَا سُمِعَ فِيهِمُ الأَذَانُ","6"],[12,"Chapter: It Is Recommended For The One Who Hears The Mu'adhdhin To Repeat His Words, Then To Send Salat Upon The Prophet (saws) And Ask Allah To Grant Him Al-Wasilah","باب اسْتِحْبَابِ الْقَوْلِ مِثْلَ قَوْلِ الْمُؤَذِّنِ لِمَنْ سَمِعَهُ ثُمَّ يُصَلِّي عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ يَسْأَلُ اللَّهَ لَهُ الْوَسِيلَةَ","7"],[16,"Chapter: The Virtue Of the Adhan, And The Shaitan Flees When He Hears It","باب فَضْلِ الأَذَانِ وَهَرَبِ الشَّيْطَانِ عِنْدَ سَمَاعِهِ","8"],[24,"Chapter: It Is Recommended To Raise The Hands Level With The Shoulders When Saying The Opening Takbir, When Bowing And When Rising From Bowing. But That Is Not To Be Done When Rising From The Prostration","باب اسْتِحْبَابِ رَفْعِ الْيَدَيْنِ حَذْوَ الْمَنْكِبَيْنِ مَعَ تَكْبِيرَةِ الإِحْرَامِ وَالرُّكُوعِ وَفِي الرَّفْعِ مِنَ الرُّكُوعِ وَأَنَّهُ لاَ يَفْعَلُهُ إِذَا رَفَعَ مِنَ السُّجُودِ","9"],[30,"Chapter: Affirming The Takbir For Every Movement Up Or Down In The Prayer, Except When Rising From Ruku' When One Should Say: Sami'aAllahu Liman Hamidah (Allah Hears Those Who Praise Him)","باب إِثْبَاتِ التَّكْبِيرِ فِي كُلِّ خَفْضٍ وَرَفْعٍ فِي الصَّلاَةِ إِلاَّ رَفْعَهُ مِنَ الرُّكُوعِ فَيَقُولُ فِيهِ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ","10"],[37,"Chapter: It Is Obligatory To Recite Al-Fatihah In Every Rak'ah; If A Person Cannot Recite Al-Fatihah Or Cannot Learn It, Then He Should Recite Whatever Else He Can Manage","باب وُجُوبِ قِرَاءَةِ الْفَاتِحَةِ فِي كُلِّ رَكْعَةٍ وَإِنَّهُ إِذَا لَمْ يُحْسِنِ الْفَاتِحَةَ وَلاَ أَمْكَنَهُ تَعَلُّمُهَا قَرَأَ مَا تَيَسَّرَ لَهُ مِنْ غَيْرِهَا","11"],[49,"Chapter: Prohibiting The Follower From Reciting Aloud Behind An Imam","باب نَهْىِ الْمَأْمُومِ عَنْ جَهْرِهِ، بِالْقِرَاءَةِ خَلْفَ إِمَامِهِ","12"],[52,"Chapter: The Proof Of Those Who Say That The Basmalah Should Not Be Recited Aloud","باب حُجَّةِ مَنْ قَالَ لاَ يَجْهَرُ بِالْبَسْمَلَةِ","13"],[56,"Chapter: The Proof Of Those Who Say That The Bismillah Is A Verse At The Beginning Of Every Surah, Except Bara'ah (At-Tawbah)","باب حُجَّةِ مَنْ قَالَ الْبَسْمَلَةُ آيَةٌ مِنْ أَوَّلِ كُلِّ سُورَةٍ سِوَى بَرَاءَةَ","14"],[58,"Chapter: The Placing Of The Right Hand Over The Left Hand After The First Takbir In Prayer (takbir-i-tahrima) Below The Chest And Above The Navel And Then Placing Them Apposite The Shoulders In Prostration","باب وَضْعِ يَدِهِ الْيُمْنَى عَلَى الْيُسْرَى بَعْدَ تَكْبِيرَةِ الإِحْرَامِ تَحْتَ صَدْرِهِ فَوْقَ سُرَّتِهِ وَوَضْعِهِمَا فِي السُّجُودِ عَلَى الأَرْضِ حَذْوَ مَنْكِبَيْهِ","13"],[59,"Chapter: The Tashah-hud In The Prayer","باب التَّشَهُّدِ فِي الصَّلاَةِ","16"],[69,"Chapter: Sending Salat Upon The Prophet (saws) After The Tashah-hud","باب الصَّلاَةِ عَلَى النَّبِيِّ صلى الله عليه وسلم بَعْدَ التَّشَهُّدِ","17"],[75,"Chapter: Saying \"Sami'a Allahu liman Hamidah,\" Rabbana wa lakal-hamd,\" and \"Amin\"","باب التَّسْمِيعِ وَالتَّحْمِيدِ وَالتَّأْمِينِ","18"],[83,"Chapter: Following The Imam","باب ائْتِمَامِ الْمَأْمُومِ بِالإِمَامِ","19"],[94,"Chapter: The Prohibition Of Preceding The Imam In Saying The Takbir Or Anything Else","باب النَّهْىِ عَنْ مُبَادَرَةِ الإِمَامِ، بِالتَّكْبِيرِ وَغَيْرِهِ","20"],[98,"Chapter: If The Imam Experiences An Excuse, From Illness, Or Travelling, Etc. He May Appoint Someone Else To Lead The People In Prayer; The One Who Offers Prayer Behind The Imam Sitting Because He Is Unable To Stand Must Stand If He Is Able To Do So; And The Abrogation Of Sitting Behind A Sitting Imam For Those Who Are Able To Stand","باب اسْتِخْلاَفِ الإِمَامِ إِذَا عَرَضَ لَهُ عُذْرٌ مِنْ مَرَضٍ وَسَفَرٍ وَغَيْرِهِمَا مَنْ يُصَلِّي بِالنَّاسِ وَأَنَّ مَنْ صَلَّى خَلْفَ إِمَامٍ جَالِسٍ لِعَجْزِهِ عَنِ الْقِيَامِ لَزِمَهُ الْقِيَامُ إِذَا قَدَرَ عَلَيْهِ وَنَسْخِ الْقُعُودِ خَلْفَ الْقَاعِدِ فِي حَقِّ مَنْ قَدَرَ عَلَى الْقِيَامِ","21"],[111,"Chapter: The Congregation Appointing Someone To Lead Them If The Imam Is Delayed And If There Is No Fear Of Negative Repercussions","باب تَقْدِيمِ الْجَمَاعَةِ مَنْ يُصَلِّي بِهِمْ إِذَا تَأَخَّرَ الإِمَامُ وَلَمْ يَخَافُوا مَفْسَدَةً بِالتَّقْدِيمِ","22"],[116,"Chapter: Men Saying The Tasbih And Women Clapping If They Notice Anything During The Prayer","باب تَسْبِيحِ الرَّجُلِ وَتَصْفِيقِ الْمَرْأَةِ إِذَا نَابَهُمَا شَىْءٌ فِي الصَّلاَةِ","23"],[119,"Chapter: The Command To Perform The Prayer Properly, To Complete It, And To Have Khushu' In It","باب الأَمْرِ بِتَحْسِينِ الصَّلاَةِ وَإِتْمَامِهَا وَالْخُشُوعِ فِيهَا","24"],[123,"Chapter: The Prohibition Of Preceding The Imam While Bowing, Prostrating And So On","باب النَّهْىِ عَنْ سَبْقِ الإِمَامِ، بِرُكُوعٍ أَوْ سُجُودٍ وَنَحْوِهِمَا","25"],[128,"Chapter: The Prohibition On Lifting Ones Gaze To The Heavens When in Salat","باب النَّهْىِ عَنْ رَفْعِ الْبَصَرِ، إِلَى السَّمَاءِ فِي الصَّلاَةِ","26"],[130,"Chapter: The Command To Be Calm During The Prayer And The Prohibition Of Gesturing With One's Hand And Raising It When Saying The Salam; And Completing The First Rows, Aligning In Them, And The Command To Come Together","باب الأَمْرِ بَالسُّكُونِ فِي الصَّلاَةِ وَالنَّهْيِ عَنِ الإِشَارَةِ بِالْيَدِ وَرَفْعِهَا عِنْدَ السَّلاَمِ وَإِتْمَامِ الصُّفُوفِ الأُوَلِ وَالتَّرَاصِّ فِيهَا وَالأَمْرِ بِالاِجْتِمَاعِ","27"],[134,"Chapter: Straightening The Rows; The Virtue Of The Front Row And Then The Next; Competing With One Another For The Front Row; The People Of Virtue Should Take Precedence And Be Closest To The Imam","باب تَسْوِيَةِ الصُّفُوفِ وَإِقَامَتِهَا وَفَضْلِ الأَوَّلِ فَالأَوَّلِ مِنْهَا وَالاِزْدِحَامِ عَلَى الصَّفِّ الأَوَّلِ وَالْمُسَابَقَةِ إِلَيْهَا وَتَقْدِيمِ أُولِي الْفَضْلِ وَتَقْرِيبِهِمْ مِنَ الإِمَامِ","28"],[149,"Chapter: The Command To Women Who Are Praying Behind Men Not To Raise Their Heads From Prostration Before The Men Have Done So","باب أَمْرِ النِّسَاءِ الْمُصَلِّيَاتِ وَرَاءَ الرِّجَالِ أَنْ لاَ يَرْفَعْنَ رُءُوسَهُنَّ مِنَ السُّجُودِ حَتَّى يَرْفَعَ الرِّجَالُ","29"],[150,"Chapter: Women Going Out To The Masjid So Long As No Fitnah Results From That; and They Should Not Go Out Wearing Perfume","باب خُرُوجِ النِّسَاءِ إِلَى الْمَسَاجِدِ إِذَا لَمْ يَتَرَتَّبْ عَلَيْهِ فِتْنَةٌ وَأَنَّهَا لاَ تَخْرُجُ مُطَيَّبَةً","30"],[163,"Chapter: Moderation When Reciting Qur'an In A Prayer When It Is To Be Recited Out Loud, And Making it Neither Too Loud Nor Too Soft, And When There Is The Fear Of Negative Consequences If It Is Recited Out Loud","باب التَّوَسُّطِ فِي الْقِرَاءَةِ فِي الصَّلاَةِ الْجَهْرِيَّةِ بَيْنَ الْجَهْرِ وَالإِسْرَارِ إِذَا خَافَ مِنَ الْجَهْرِ مَفْسَدَةً","31"],[166,"Chapter: Listening to the Recitation","باب الاِسْتِمَاعِ لِلْقِرَاءَةِ","32"],[168,"Chapter: Reciting Out Aloud In As-Subh And Reciting To The Jinn","باب الْجَهْرِ بِالْقِرَاءَةِ فِي الصُّبْحِ وَالْقِرَاءَةِ عَلَى الْجِنِّ","33"],[174,"Chapter: The Recitation For Zuhr And 'Asr","باب الْقِرَاءَةِ فِي الظُّهْرِ وَالْعَصْرِ","34"],[184,"Chapter: Recitation in As-Subh","باب الْقِرَاءَةِ فِي الصُّبْحِ","35"],[199,"Chapter: Recitation During 'Isha","باب الْقِرَاءَةِ فِي الْعِشَاءِ","36"],[206,"Chapter: The Command To The Imam To Make The Prayer Brief But Complete","باب أَمْرِ الأَئِمَّةِ بِتَخْفِيفِ الصَّلاَةِ فِي تَمَامٍ","37"],[219,"Chapter: Moderation In All Pillars Of The Prayer, And Making It Brief Yet Complete","باب اعْتِدَالِ أَرْكَانِ الصَّلاَةِ وَتَخْفِيفِهَا فِي تَمَامٍ","38"],[224,"Chapter: Following The Imam And Acting After Him","باب مُتَابَعَةِ الإِمَامِ وَالْعَمَلِ بَعْدَهُ","39"],[229,"Chapter: What Is To Be Said When Raising One's Head From Bowing","باب مَا يَقُولُ إِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ","40"],[236,"Chapter: The Prohibition Of Reciting The Quran While Bowing And Prostrating","باب النَّهْىِ عَنْ قِرَاءَةِ الْقُرْآنِ، فِي الرُّكُوعِ وَالسُّجُودِ","41"],[245,"Chapter: What Is To Be Said While Bowing And Prostrating","باب مَا يُقَالُ فِي الرُّكُوعِ وَالسُّجُودِ","42"],[255,"Chapter: The Virtue Of Prostration And Encouragement To Do So","باب فَضْلِ السُّجُودِ وَالْحَثِّ عَلَيْهِ","43"],[257,"Chapter: The Limbs Of Prostration And The Prohibition Of Tucking Up One's Hair And Garment Or Having Ones Hair In A Braid When Praying","باب أَعْضَاءِ السُّجُودِ وَالنَّهْىِ عَنْ كَفِّ الشَّعْرِ، وَالثَّوْبِ، وَعَقْصِ الرَّأْسِ، فِي الصَّلاَة","44"],[264,"Chapter: Moderation In Prostration; Placing The Hands On The Ground, Keeping The Elbows Up, Away From The Sides, And Lifting The Belly Up Off The Thighs When Prostrating","باب الاِعْتِدَالِ فِي السُّجُودِ وَوَضْعِ الْكَفَّيْنِ عَلَى الأَرْضِ وَرَفْعِ الْمِرْفَقَيْنِ عَنِ الْجَنْبَيْنِ وَرَفْعِ الْبَطْنِ عَنِ الْفَخِذَيْنِ فِي السُّجُودِ","45"],[267,"Chapter: The Description Of The Prayer, With What It Begins And Ends. The Description Of Bowing And Moderation Therein, And Of Prostration And Moderation Therein. Tashah-hud After Each Two Rak'ah Of Four Rak'ah Prayers. Description Ol Sitting Between The Two Prostrations, And In The First Tashah-hud","باب مَا يَجْمَعُ صِفَةَ الصَّلاَةِ وَمَا يُفْتَتَحُ بِهِ وَيُخْتَمُ بِهِ وَصِفَةَ الرُّكُوعِ وَالاِعْتِدَالِ مِنْهُ وَالسُّجُودِ وَالاِعْتِدَالِ مِنْهُ وَالتَّشَهُّدِ بَعْدَ كُلِّ رَكْعَتَيْنِ مِنَ الرُّبَاعِيَّةِ وَصِفَةَ الْجُلُوسِ بَيْنَ السَّجْدَتَيْنِ وَفِي التَّشَهُّدِ الأَوَّلِ","46"],[273,"Chapter: The Sutrah (Screen) For One Who Is Praying, And The Recommendation To Pray Facing A Sutrah. The Ruling On Passing In Front Of One Who Is Praying, And Preventing One Who Wants To Pass In Front. It Is Permissible To Lie Down In Front Of One Who Is Praying, Praying Towards One's Mount. The Command To Stand Close To The Sutrah. The Height Of The Suirah, And Related Matters","باب سُتْرَةِ الْمُصَلِّي","47"],[290,"Chapter: Preventing One Who Wants To Pass In Front Of A Praying Person","باب مَنْعِ الْمَارِّ بَيْنَ يَدَىِ الْمُصَلِّي","48"],[296,"Chapter: The Praying Person Standing Close To The Sutrah","باب دُنُوِّ الْمُصَلِّي مِنَ السُّتْرَةِ","49"],[299,"Chapter: The Height Of That Which Serves As A Sutrah For The One Who Is Praying","باب قَدْرِ مَا يَسْتُرُ الْمُصَلِّيَ","50"],[302,"Chapter: Lying In Front Of One Who Is Praying","باب الاِعْتِرَاضِ بَيْنَ يَدَىِ الْمُصَلِّي","51"],[310,"Chapter: Praying In A Single Garment, And How It Should Be Worn","باب الصَّلاَةِ فِي ثَوْبٍ وَاحِدٍ وَصِفَةِ لُبْسِهِ","52"]],"5":[[13,"Chapter: The construction of the Masjid of the Prophet (saws)","باب ابْتِنَاءِ مَسْجِدِ النَّبِيِّ صلى الله عليه وسلم","1"],[16,"Chapter: Changing the qiblah from Al-Quds (Jerusalem) to the Ka`bah","باب تَحْوِيلِ الْقِبْلَةِ مِنَ الْقُدْسِ إِلَى الْكَعْبَةِ","2"],[21,"Chapter: The prohibition of building masajid over graves and placing images therein; and the prohibition of taking graves as masajid","باب النَّهْيِ عَنْ بِنَاءِ الْمَسَاجِدِ عَلَى الْقُبُورِ وَاتِّخَاذِ الصُّوَرِ فِيهَا وَالنَّهْيِ عَنِ اتِّخَاذِ الْقُبُورِ مَسَاجِدَ","3"],[29,"Chapter: The virtue of building masajid and encouragement to do so","باب فَضْلِ بِنَاءِ الْمَسَاجِدِ وَالْحَثِّ عَلَيْهَا","4"],[31,"Chapter: The recommendation to place the hands on the knees when bowing, and the abrogation of tatbiq","باب النَّدْبِ إِلَى وَضْعِ الأَيْدِي عَلَى الرُّكَبِ فِي الرُّكُوعِ وَنَسْخِ التَّطْبِيقِ","5"],[38,"Chapter: The permissibility of squatting on the heels","باب جَوَازِ الإِقْعَاءِ عَلَى الْعَقِبَيْنِ","6"],[39,"Chapter: The prohibition of speaking during the prayer, and the abrogation of its former permissibility","باب تَحْرِيمِ الْكَلاَمِ فِي الصَّلاَةِ وَنَسْخِ مَا كَانَ مِنْ إِبَاحَتِهِ","7"],[49,"Chapter: The permissibility of cursing the Shaitan during prayer, and seeking refuge with Allah from him; and the permissibility of doing a few actions while in salat","باب جَوَازِ لَعْنِ الشَّيْطَانِ فِي أَثْنَاءِ الصَّلاَةِ وَالتَّعَوُّذِ مِنْهُ وَجَوَازِ الْعَمَلِ الْقَلِيلِ فِي الصَّلاَةِ","8"],[52,"Chapter: The permissibility of carrying children during prayer, and their garments are regarded as being pure until it is realized that they are impure. Few actions will not invalidate the prayer, and the same applies if several such actions are done but are done separately","باب جَوَازِ حَمْلِ الصِّبْيَانِ فِي الصَّلاَةِ","9"],[56,"Chapter: The permissibility of taking one or two steps while praying, and that is not disliked if done for a reason. The permissibility of the Imam praying in a place that is higher than the people praying behind him, if that is done for a reason, such as teaching them how to offer prayers, and other than that.","باب جَوَازِ الْخُطْوَةِ وَالْخُطْوَتَيْنِ فِي الصَّلاَةِ","10"],[58,"Chapter: It is disliked to put the hands on the waist during the prayer","باب كَرَاهَةِ الاِخْتِصَارِ فِي الصَّلاَةِ","11"],[59,"Chapter: It is disliked to smooth the pebbles or make the dirt level during salat","باب كَرَاهَةِ مَسْحِ الْحَصَى وَتَسْوِيَةِ التُّرَابِ فِي الصَّلاَةِ","12"],[61,"Chapter: The prohibition of spitting in the masjid, during prayer and at other times. The prohibition of a praying person spitting in front of him or to his right","باب النَّهْىِ عَنِ الْبُصَاقِ، فِي الْمَسْجِدِ فِي الصَّلاَةِ وَغَيْرِهَا","13"],[74,"Chapter: The permissibility of offering salat while wearing shoes","باب جَوَازِ الصَّلاَةِ فِي النَّعْلَيْنِ","14"],[76,"Chapter: It is disliked to offer salat in a garment with markings","باب كَرَاهَةِ الصَّلاَةِ فِي ثَوْبٍ لَهُ أَعْلاَمٌ","15"],[79,"Chapter: It is disliked to offer salat in the presence of food that one wants to eat. It is disliked to offer salat while restraining the urge to relieve oneself, and so on","باب كَرَاهَةِ الصَّلاَةِ بِحَضْرَةِ الطَّعَامِ الَّذِي يُرِيدُ أَكْلَهُ فِي الْحَالِ وَكَرَاهَةِ الصَّلاَةِ مَعَ مُدَافَعَةِ الأَخْبَثَيْنِ","16"],[86,"Chapter: Prohibiting one who has eaten garlic, onions, or leeks, and other things that have an offensive odor from coming to the masjid, until that smell has gone away, and such a person should be expelled from the masjid","باب نَهْىِ مَنْ أَكَلَ ثُومًا أَوْ بَصَلاً أَوْ كُرَّاثًا أَوْ نَحْوَهَا عَنْ حُضُورِ الْمَسْجِدِ","17"],[98,"Chapter: The prohibition of making lost property announcements in the masjid, and what should be said by one who hears a person making such an announcement","باب النَّهْىِ عَنْ نَشْدِ الضَّالَّةِ، فِي الْمَسْجدِ وَمَا يَقُولُهُ مَنْ سَمِعَ النَّاشِدَ","18"],[103,"Chapter: As-Sahw (forgetfulness) in prayer and prostrating to compensate for it","باب السَّهْوِ فِي الصَّلاَةِ وَالسُّجُودِ لَهُ","19"],[133,"Chapter: The prostration of recitation","باب سُجُودِ التِّلاَوَةِ","20"],[145,"Chapter: The description of the sitting during the prayer, and how the hands are to be placed on the thighs","باب صِفَةِ الْجُلُوسِ فِي الصَّلاَةِ وَكَيْفِيَّةِ وَضْعِ الْيَدَيْنِ عَلَى الْفَخِذَيْنِ","21"],[151,"Chapter: The salam to exit the prayer when one has finished and how it is done","باب السَّلاَمِ لِلتَّحْلِيلِ مِنَ الصَّلاَةِ عِنْدَ فَرَاغِهَا وَكَيْفِيَّتِهِ","22"],[154,"Chapter: The remembrance after the prayer","باب الذِّكْرِ بَعْدَ الصَّلاَةِ","23"],[157,"Chapter: It is recommended to seek refuge with Allah from the punishment of the grave, the punishment of hell, the trials of life and death, the tribulation of the Dajjal and from sin and debt between the tashah-hud and the taslim","باب اسْتِحْبَابِ التَّعَوُّذِ مِنْ عَذَابِ الْقَبْرِ","24"],[161,"Chapter: From what refuge is to be sought when in salat","باب مَا يُسْتَعَاذُ مِنْهُ فِي الصَّلاَةِ","25"],[171,"Chapter: It is recommended to recite statements of remembrance after the prayer, and how that is to be done","باب اسْتِحْبَابِ الذِّكْرِ بَعْدَ الصَّلاَةِ وَبَيَان صِفَتِهِ","26"],[190,"Chapter: What is to be said between the opening takbir and the recitation of the Qur’an","باب مَا يُقَالُ بَيْنَ تَكْبِيرَةِ الإِحْرَامِ وَالْقِرَاءَةِ","27"],[194,"Chapter: It is recommended to come to prayers in a tranquil and dignified manner, and it is forbidden to come in a hasty manner","باب اسْتِحْبَابِ إِتْيَانِ الصَّلاَةِ بِوَقَارٍ وَسَكِينَةٍ وَالنَّهْىِ عَنْ إِتْيَانِهَا سَعْيًا","28"],[200,"Chapter: When should the people stand up to pray?","باب مَتَى يَقُومُ النَّاسُ لِلصَّلاَةِ","29"],[205,"Chapter: The one who catches up with a rak`ah of the prayer, he has caught up with that prayer","باب مَنْ أَدْرَكَ رَكْعَةً مِنَ الصَّلاَةِ فَقَدْ أَدْرَكَ تِلْكَ الصَّلاَةَ","30"],[213,"Chapter: The times of the five prayers","باب أَوْقَاتِ الصَّلَوَاتِ الْخَمْسِ","31"],[229,"Chapter: The recommendation to delay Zuhr (until it has cooled down) in severe heat for one who finds it too hot in route to join the congregation","باب اسْتِحْبَابِ الإِبْرَادِ بِالظُّهْرِ فِي شِدَّةِ الْحَرِّ لِمَنْ يَمْضِي إِلَى جَمَاعَةٍ وَيَنَالُهُ الْحَرُّ فِي طَرِيقِهِ","32"],[238,"Chapter: It is recommended to pray Zuhr at the beginning of its time when there is no intense heat","باب اسْتِحْبَابِ تَقْدِيمِ الظُّهْرِ فِي أَوَّلِ الْوَقْتِ فِي غَيْرِ شِدَّةِ الْحَرِّ","33"],[242,"Chapter: It is recommended to pray `Asr early","باب اسْتِحْبَابِ التَّبْكِيرِ بِالْعَصْرِ","34"],[251,"Chapter: Stern warning against missing the `Asr prayer","باب التَّغْلِيظِ فِي تَفْوِيتِ صَلاَةِ الْعَصْرِ","35"],[256,"Chapter: The evidence for those who say that “the middle prayer” is the `Asr prayer","باب الدَّلِيلِ لِمَنْ قَالَ الصَّلاَةُ الْوُسْطَى هِيَ صَلاَةُ الْعَصْرِ","36"],[265,"Chapter: The virtue of the Subh and the `Asr prayers, and of maintaining them","باب فَضْلِ صَلاَتَىِ الصُّبْحِ وَالْعَصْرِ وَالْمُحَافَظَةِ عَلَيْهِمَا","37"],[273,"Chapter: The beginning of the time for Maghrib when the sun sets","باب بَيَانِ أَنَّ أَوَّلَ وَقْتِ الْمَغْرِبِ عِنْدَ غُرُوبِ الشَّمْسِ","38"],[276,"Chapter: The time of `Isha and delaying it","باب وَقْتِ الْعِشَاءِ وَتَأْخِيرِهَا","39"],[290,"Chapter: It is recommended to pray Subh early, at the beginning of its time, when it is still dark; and the length of recitation therein","باب اسْتِحْبَابِ التَّبْكِيرِ بِالصُّبْحِ فِي أَوَّلِ وَقْتِهَا وَهُوَ التَّغْلِيسُ وَبَيَانِ قَدْرِ الْقِرَاءَةِ فِيهَا","40"],[298,"Chapter: It is disliked to delay the prayers beyond their proper times, and what a person should do if the Imam delays the prayer","باب كَرَاهِيَةِ تَأْخِيرِ الصَّلاَةِ عَنْ وَقْتِهَا الْمُخْتَارِ وَمَا يَفْعَلُهُ الْمَأْمُومُ إِذَا أَخَّرَهَا الإِمَامُ","41"],[305,"Chapter: The virtue of prayer in congregation, and clarifying the stern warning against staying away from it, and that it is fard kifayah","باب فَضْلِ صَلاَةِ الجَمَاعَةِ وَبَيَانِ التَّشْدِيدِ فِي التَّخَلُّفِ عَنْهَا","42"],[319,"Chapter: It is obligatory for the one who hears the call to prayer to come to the masjid","باب يَجِبُ إِتْيَانُ الْمَسْجِدِ عَلَى مَنْ سَمِعَ النِّدَاءَ","43"],[320,"Chapter: Prayer in congregation is one of the sunnah of guidance","باب صَلاَةُ الْجَمَاعَةِ مِنْ سُنَنِ الْهُدَى","44"],[322,"Chapter: The prohibition of leaving the masjid once the Mu’adhdhin has called the Adhan","باب النَّهْىِ عَنِ الْخُرُوجِ، مِنَ الْمَسْجِدِ إِذَا أَذَّنَ الْمُؤَذِّنُ","45"],[324,"Chapter: The virtue of praying `Isha and Subh in congregation","باب فَضْلِ صَلاَةِ الْعِشَاءِ وَالصُّبْحِ فِي جَمَاعَةٍ","46"],[329,"Chapter: Concession allowing one to not attend the congregation if there is an excuse","باب الرُّخْصَةِ فِي التَّخَلُّفِ عَنِ الْجَمَاعَةِ، بِعُذْرٍ","47"],[332,"Chapter: It is permissible to offer voluntary prayers in congregation, and to pray on hasir (palm-fiber mats), khumrah (small mats), cloth, and other pure things","باب جَوَازِ الْجَمَاعَةِ فِي النَّافِلَةِ وَالصَّلاَةِ عَلَى حَصِيرٍ وَخُمْرَةٍ وَثَوْبٍ وَغَيْرِهَا مِنَ الطَّاهِرَاتِ","48"],[339,"Chapter: The virtue of offering the obligatory prayers in congregation, the virtue of waiting for prayer and taking many steps towards the masjid, the virtue of walking to the masjid","باب فَضْلِ صَلاَةِ الْجَمَاعَةِ وَانْتِظَارِ الصَّلاَةِ","49"],[346,"Chapter: The virtue of taking many steps to the masjid","باب فَضْلِ كَثْرَةِ الْخُطَا إِلَى الْمَسَاجِدِ","50"],[354,"Chapter: Walking to prayer erases sins and raises one in status","باب الْمَشْىُ إِلَى الصَّلاَةِ تُمْحَى بِهِ الْخَطَايَا وَتُرْفَعُ بِهِ الدَّرَجَاتُ","51"],[358,"Chapter: The virtue of sitting in one’s prayer place after Subh, and the virtue of the masajid","باب فَضْلِ الْجُلُوسِ فِي مُصَلاَّهُ بَعْدَ الصُّبْحِ وَفَضْلِ الْمَسَاجِدِ","52"],[362,"Chapter: Who is more entitled to lead the prayer","باب مَنْ أَحَقُّ بِالإِمَامَةِ","53"],[373,"Chapter: It is recommended to say qunut in all prayers if a calamity befalls the Muslims – and refuge is sought from Allah (regarding that). It is recommended to say qunut in Subh at all times. And the clarification that it is to be said after raising the head from bowing in the final rak`ah, and it is recommended to say it out loud","باب اسْتِحْبَابِ الْقُنُوتِ فِي جَمِيعِ الصَّلاَةِ إِذَا نزَلَتْ بِالْمُسْلِمِينَ نَازِلَةٌ","54"],[393,"Chapter: Making up a missed prayer. And it is recommended to hasten to make it up","باب قَضَاءِ الصَّلاَةِ الْفَائِتَةِ وَاسْتِحْبَابِ تَعْجِيلِ قَضَائِهَا","55"]],"6":[[1,"Chapter: The travelers’ prayer and shortening it","باب صَلاَةِ الْمُسَافِرِينَ وَقَصْرِهَا","1"],[21,"Chapter: Shortening the prayer in Mina","باب قَصْرِ الصَّلاَةِ بِمِنًى","2"],[31,"Chapter: Praying in dwellings when it is raining","باب الصَّلاَةِ فِي الرحَالِ فِي الْمَطَرِ","3"],[41,"Chapter: It is permissible to offer voluntary prayers atop one’s mount when travelling, no matter what direction it is facing","باب جَوَازِ صَلاَةِ النَّافِلَةِ عَلَى الدَّابَّةِ فِي السَّفَرِ حَيْثُ تَوَجَّهَتْ","4"],[52,"Chapter: It is permissible to combine two prayers when traveling","باب جَوَازِ الْجَمْعِ بَيْنَ الصَّلاَتَيْنِ فِي السَّفَرِ","5"],[59,"Chapter: Joining two prayers when not traveling","باب الْجَمْعِ بَيْنَ الصَّلاَتَيْنِ فِي الْحَضَرِ","6"],[69,"Chapter: It is permissible to leave to the right or left after finishing the prayer","باب جَوَاز الاِنْصِرَافِ مِنَ الصَّلاَةِ عَنِ الْيَمِينِ، وَالشِّمَالِ","7"],[73,"Chapter: It is recommended to stand to the right of the Imam","باب اسْتِحْبَابِ يَمِينِ الإِمَامِ","8"],[75,"Chapter: It is disliked to start a voluntary prayer after the Mu’adhdhin has started to say Iqamah for prayer, whether that is a regular sunnah, such as the sunnah of Subh or Zuhr, or anything else, and regardless of whether he knows that he will catch up with the rak`ah with the Imam or not","باب كَرَاهَةِ الشُّرُوعِ فِي نَافِلَةٍ بَعْدَ شُرُوعِ الْمُؤَذِّنِ","9"],[82,"Chapter: What to say when entering the masjid","باب مَا يَقُولُ إِذَا دَخَلَ الْمَسْجِدَ","10"],[84,"Chapter: It is recommended to greet the masjid by praying two rak`ah, and it is disliked to sit before praying these two rak`ah, and this is prescribed at all times","باب اسْتِحْبَابِ تَحِيَّةِ الْمَسْجِدِ بِرَكْعَتَيْنِ وَكَرَاهَةِ الْجُلُوسِ قَبْلَ صَلاَتِهِمَا وَأَنَّهَا مَشْرُوعَةٌ فِي جَمِيعِ الأَوْقَاتِ","11"],[87,"Chapter: It is recommended to pray two rak`ah in the masjid for one who has come from a journey, when he first arrives","باب اسْتِحْبَابِ الرَّكْعَتَيْنِ فِي الْمَسْجِدِ لِمَنْ قَدِمَ مِنْ سَفَرٍ أَوَّلَ قُدُومِهِ","12"],[90,"Chapter: It is recommended to pray Duha, the least of which is two rak`ah, the best of which is eight, and the average of which is four or six, and encouragement to do so regularly","باب اسْتِحْبَابِ صَلاَةِ الضُّحَى وَأَنَّ أَقَلَّهَا رَكْعَتَانِ وَأَكْمَلَهَا ثَمَانِ رَكَعَاتٍ وَأَوْسَطَهَا أَرْبَعُ رَكَعَاتٍ أَوْ سِتٌّ وَالْحَثِّ عَلَى الْمُحَافَظَةِ عَلَيْهَا","13"],[106,"Chapter: It is recommended to pray two rak`ah for the sunnah of Fajr. And encouragement to pray them regularly, and to make them brief, and to persist in offering them, and clarifying what is recommended to recite therein","باب اسْتِحْبَابِ رَكْعَتَيْ سُنَّةِ الْفَجْرِ وَالْحَثِّ عَلَيْهِمَا وَتَخْفِيفِهِمَا وَالْمُحَافَظَةِ عَلَيْهِمَا وَبَيَانِ مَا يُسْتَحَبُّ أَنْ يُقْرَأَ فِيهِمَا","14"],[124,"Chapter: The virtue of the regular sunnah prayers before and after the obligatory prayers, and their numbers","باب فَضْلِ السُّنَنِ الرَّاتِبَةِ قَبْلَ الْفَرَائِضِ وَبَعْدَهُنَّ وَبَيَانِ عَدَدِهِنَّ","15"],[129,"Chapter: It is permissible to offer voluntary prayers standing or sitting, and to stand and sit in the same rak`ah","باب جَوَازِ النَّافِلَةِ قَائِمًا وَقَاعِدًا وَفِعْلِ بَعْضِ الرَّكْعَةِ قَائِمًا وَبَعْضِهَا قَاعِدًا","16"],[147,"Chapter: Night prayers and the number of rak`ah offered by the Prophet (saws) at night, and that Witr is one rak`ah, and a one-rak`ah prayer is correct","باب صَلاَةِ اللَّيْلِ وَعَدَدِ رَكَعَاتِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي اللَّيْلِ وَأَنَّ الْوِتْرَ رَكْعَةٌ وَأَنَّ الرَّكْعَةَ صَلاَةٌ صَحِيحَةٌ","17"],[168,"Chapter: Night prayer, and the one who sleeps and misses it or is sick","باب جَامِعِ صَلاَةِ اللَّيْلِ وَمَنْ نَامَ عَنْهُ أَوْ مَرِضَ","18"],[175,"Chapter: Salat al-Awwabin (the prayer of the penitent) is when the young camels feel the heat of the hot sand","باب صَلاَةُ الأَوَّابِينَ حِينَ تَرْمَضُ الْفِصَالُ","19"],[177,"Chapter: The night prayers are two by two, and Witr is one rakah at the end of the night","باب صَلاَةُ اللَّيْلِ مَثْنَى مَثْنَى وَالْوِتْرُ رَكْعَةٌ مِنْ آخِرِ اللَّيْلِ","20"],[195,"Chapter: One who fears that he will not get up at the end of the night, then he should pray Witr at the beginning of the night","باب مَنْ خَافَ أَنْ لاَ يَقُومَ مِنْ آخِرِ اللَّيْلِ فَلْيُوتِرْ أَوَّلَهُ","21"],[197,"Chapter: The best prayer is that in which one stands for a long time (tuwlul-qunut)","باب أَفْضَلُ الصَّلاَةِ طُولُ الْقُنُوتِ","22"],[199,"Chapter: In the night there is an hour when supplications are answered","باب فِي اللَّيْلِ سَاعَةٌ مُسْتَجَابٌ فِيهَا الدُّعَاءُ","23"],[201,"Chapter: Encouragement to supplicate and recite statements of remembrance at the end of the night, and the response to that","باب التَّرْغِيبِ فِي الدُّعَاءِ وَالذِّكْرِ فِي آخِرِ اللَّيْلِ وَالإِجَابَةِ فِيهِ","24"],[207,"Chapter: Encouragement to pray qiyam during Ramadan, which is Tarawih","باب التَّرْغِيبِ فِي قِيَامِ رَمَضَانَ وَهُوَ التَّرَاوِيحُ","25"],[216,"Chapter: The prayer and the supplication of the Prophet (saws) at night","باب الدُّعَاءِ فِي صَلاَةِ اللَّيْلِ وَقِيَامِهِ","26"],[242,"Chapter: It is recommended to recite for a long time in the night prayers","باب اسْتِحْبَابِ تَطْوِيلِ الْقِرَاءَةِ فِي صَلاَةِ اللَّيْلِ","27"],[245,"Chapter: Encouragement to pray at night even if it is little","باب مَا رُوِيَ فِيمَنْ، نَامَ اللَّيْلَ أَجْمَعَ حَتَّى أَصْبَحَ","28"],[248,"Chapter: It is recommended to offer voluntary prayers in one’s house although it is permissible to offer them in the masjid","باب اسْتِحْبَابِ صَلاَةِ النَّافِلَةِ فِي بَيْتِهِ وَجَوَازِهَا فِي الْمَسْجِدِ","29"],[255,"Chapter: The virtue of a deed that is done persistently, whether it be Qiyam al-Lail or anything else. The command to be moderate in worship, which means adopting what one can persist in. The command to the one who gets tired or weary when praying to stop until that feeling passes","باب فَضِيلَةِ الْعَمَلِ الدَّائِمِ مِنْ قِيَامِ اللَّيْلِ وَغَيْرِهِ","30"],[259,"Chapter: The command to one who becomes sleepy while praying, or who starts to falter in his recitation of the Qur’an or statements of remembrance, to lie down or sit down until that goes away","باب أَمْرِ مَنْ نَعَسَ فِي صَلاَتِهِ أَوِ اسْتَعْجَمَ عَلَيْهِ الْقُرْآنُ أَوِ الذِّكْرُ بِأَنْ يَرْقُدَ أَوْ يَقْعُدَ حَتَّى يَذْهَبَ عَنْهُ ذَلِكَ","31"],[265,"Chapter: The book of the virtues of the Qur’an etc","باب فَضَائِلِ الْقُرْآنِ وَمَا يَتَعَلَّقُ بِهِ","32"],[265,"Chapter: The command to keep refreshing one’s knowledge of the Qur’an and that it is disliked to say I have forgotten such-and-such a verse, but it is permissible to say I have been caused to forget","باب الأَمْرِ بِتَعَهُّدِ الْقُرْآنِ وَكَرَاهَةِ قَوْلِ نَسِيتُ آيَةَ كَذَا. وَجَوَازِ قَوْلِ أُنْسِيتُهَا","33"],[273,"Chapter: It is recommended to make one’s voice beautiful when reciting Qur’an","باب اسْتِحْبَابِ تَحْسِينِ الصَّوْتِ بِالْقُرْآنِ","34"],[281,"Chapter: Mentioning the recitation of the Prophet (saws) of Surat al-Fath on the day of the conquest of Makkah","باب ذِكْرِ قِرَاءَةِ النَّبِيِّ صلى الله عليه وسلم سُورَةَ الْفَتْحِ يَوْمَ فَتْحِ مَكَّةَ","35"],[284,"Chapter: The descent of tranquility (sakinah) when the Qur’an is recited","باب نُزُولِ السَّكِينَةِ لِقِرَاءَةِ الْقُرْآنِ","36"],[288,"Chapter: The virtue of the one who memorizes the Qur’an","باب فَضِيلَةِ حَافِظِ الْقُرْآنِ","37"],[290,"Chapter: The virtue of the one who is skilled in reciting Qur’an and the one who falters in reciting","باب فَضْلِ الْمَاهِرِ بِالْقُرْآنِ وَالَّذِي يَتَتَعْتَعُ فِيهِ","38"],[292,"Chapter: It is recommended to recite the Qur’an to people of virtue who are skilled in its recitation, even if the reciter is better than the one to whom it is recited","باب اسْتِحْبَابِ قِرَاءَةِ الْقُرْآنِ عَلَى أَهْلِ الْفَضْلِ وَالْحُذَّاقِ فِيهِ وَإِنْ كَانَ الْقَارِئُ أَفْضَلَ مِنَ الْمَقْرُوءِ عَلَيْهِ","39"],[295,"Chapter: The virtue of listening to the Qur’an, asking one who has memorized it to recite so that one may listen, weeping when reciting, and pondering the meanings","باب فَضْلِ اسْتِمَاعِ الْقُرْآنِ وَطَلَبِ الْقِرَاءَةِ مِنْ حَافِظِهِ لِلاِسْتِمَاعِ وَالْبُكَاءِ عِنْدَ الْقِرَاءَةِ وَالتَّدَبُّرِ","40"],[300,"Chapter: The virtue of reciting the Qur’an in prayer and learning it","باب فَضْلِ قِرَاءَةِ الْقُرْآنِ فِي الصَّلاَةِ وَتَعَلُّمِهِ","41"],[302,"Chapter: The virtue of reciting the Qur’an and Surat al-Baqarah","باب فَضْلِ قِرَاءَةِ الْقُرْآنِ وَسُورَةِ الْبَقَرَةِ","42"],[305,"Chapter: The virtue of al-Fatihah and the closing verse of Surat al-Baqarah; and the encouragement to recite the two verses at the end of Surat al-Baqarah","اب فَضْلِ الْفَاتِحَةِ وَخَوَاتِيمِ سُورَةِ الْبَقَرَةِ وَالْحَثِّ عَلَى قِرَاءَةِ الآيَتَيْنِ مِنْ آخِرِ الْبَقَرَةِ","43"],[311,"Chapter: The virtue of Surat al-Kahf and Ayat al-Kursi","باب فَضْلِ سُورَةِ الْكَهْفِ وَآيَةِ الْكُرْسِيِّ","44"],[314,"Chapter: The virtue of reciting Qul Huwa Allahu Ahad","باب فَضْلِ قِرَاءَةِ { قُلْ هُوَ اللَّهُ أَحَدٌ}","45"],[319,"Chapter: The virtue of reciting al-Mu`awwidhatain (the two surahs seeking refuge with Allah)","باب فَضْلِ قِرَاءَةِ الْمُعَوِّذَتَيْنِ","46"],[322,"Chapter: The virtue of one who acts in accordance with the Qur’an and teaches it. And the virtue of one who learns wisdom from Fiqh or other types of knowledge, then acts upon it and teaches it","باب فَضْلِ مَنْ يَقُومُ بِالْقُرْآنِ وَيُعَلِّمُهُ وَفَضْلِ مَنْ تَعَلَّمَ حِكْمَةً مِنْ فِقْهٍ أَوْ غَيْرِهِ فَعَمِلَ بِهَا وَعَلَّمَهَا","47"],[327,"Chapter: The clarification that the Qur’an was revealed in seven ahruf (modes of recitation), and clarifying its meaning","باب بَيَانِ أَنَّ الْقُرْآنَ عَلَى سَبْعَةِ أَحْرُفٍ وَبَيَانِ مَعْنَاهُ","48"],[336,"Chapter: Slow, measured pace of recitation (tartil), and to not rush when reciting, and the permissibility of reciting two or more surahs in one rak`ah","باب تَرْتِيلِ الْقِرَاءَةِ وَاجْتِنَابِ الْهَذِّ وَهُوَ الإِفْرَاطُ فِي السُّرْعَةِ وَإِبَاحَةِ سُورَتَيْنِ فَأَكْثَرَ فِي الرَّكْعَةِ","49"],[342,"Chapter: Concerning various recitations","باب مَا يَتَعَلَّقُ بِالْقِرَاءَاتِ","50"],[348,"Chapter: The times when it is forbidden to offer salat","باب الأَوْقَاتِ الَّتِي نُهِيَ عَنِ الصَّلاَةِ، فِيهَا .","51"],[358,"Chapter: How `Amr bin `Abasah became Muslim","باب إِسْلاَمِ عَمْرِو بْنِ عَبَسَةَ","52"],[359,"Chapter: Do not aim to pray when the sun is rising or setting","باب لاَ تَتَحَرَّوْا بِصَلاَتِكُمْ طُلُوعَ الشَّمْسِ وَلاَ غُرُوبَهَا","53"],[361,"Chapter: Concerning the two rak`ah that the Prophet (saws) used to pray after `Asr","باب مَعْرِفَةِ الرَّكْعَتَيْنِ اللَّتَيْنِ كَانَ يُصَلِّيهِمَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدَ الْعَصْرِ","54"],[366,"Chapter: It is recommended to pray two rak`ah before Maghrib","باب اسْتِحْبَابِ رَكْعَتَيْنِ قَبْلَ صَلاَةِ الْمَغْرِبِ","55"],[368,"Chapter: Between every two calls, there is a prayer","باب بَيْنَ كُلِّ أَذَانَيْنِ صَلاَةٌ","56"],[370,"Chapter: The fear prayer","باب صَلاَةِ الْخَوْفِ","57"]],"7":[[7,"Chapter: Ghusl on Friday is obligatory for all adult men, and clarifying what they were ordered regarding it","باب وُجُوبِ غُسْلِ الْجُمُعَةِ عَلَى كُلِّ بَالِغٍ مِنَ الرِّجَالِ وَبَيَانِ مَا أُمِرُوا بِهِ","1"],[10,"Chapter: Perfume and siwak on Fridays","باب الطِّيبِ وَالسِّوَاكِ يَوْمَ الْجُمُعَةِ","2"],[15,"Chapter: Listening attentively to the Khutbah on Friday","باب فِي الإِنْصَاتِ يَوْمَ الْجُمُعَةِ فِي الْخُطْبَةِ","3"],[19,"Chapter: The (special) time that occurs on Friday","باب فِي السَّاعَةِ الَّتِي فِي يَوْمِ الْجُمُعَةِ","4"],[26,"Chapter: The virtue of Friday","باب فَضْلِ يَوْمِ الْجُمُعَةِ","5"],[28,"Chapter: This Ummah has been guided to Friday","باب هِدَايَةِ هَذِهِ الأُمَّةِ لِيَوْمِ الْجُمُعَةِ","6"],[34,"Chapter: The virtue of going out early on Friday","باب فَضْلِ التَّهْجِيرِ يَوْمَ الْجُمُعَةِ","7"],[37,"Chapter: The virtue of one who remains silent and listens attentively during the khutbah","باب فَضْلِ مَنِ اسْتَمَعَ وَأَنْصَتَ فِي الْخُطْبَةِ","8"],[39,"Chapter: Jumu`ah prayer is when the sun has passed its zenith","باب صَلاَةِ الْجُمُعَةِ حِينَ تَزُولُ الشَّمْسُ","9"],[44,"Chapter: The two khutbah before the prayer, and sitting briefly in between them","باب ذِكْرِ الْخُطْبَتَيْنِ قَبْلَ الصَّلاَةِ وَمَا فِيهِمَا مِنَ الْجَلْسَةِ","10"],[47,"Chapter: The verse: “And when they see some merchandise or some amusement they disperse headlong to it, and leave you standing”","باب فِي قَوْلِهِ تَعَالَى: {وَإِذَا رَأَوْا تِجَارَةً أَوْ لَهْوًا انْفَضُّوا إِلَيْهَا وَتَرَكُوكَ قَائِمًا}","11"],[52,"Chapter: Stern warning against missing Jumu`ah","باب التَّغْلِيظِ فِي تَرْكِ الْجُمُعَةِ","12"],[53,"Chapter: Keeping the prayer and khutbah short","باب تَخْفِيفِ الصَّلاَةِ وَالْخُطْبَةِ","13"],[68,"Chapter: Greeting (prayers upon entering the masjid) while the Imam is preaching","باب التَّحِيَّةِ وَالإِمَامُ يَخْطُبُ","14"],[75,"Chapter: The hadith about teaching during the khutbah","باب حَدِيثِ التَّعْلِيمِ فِي الْخُطْبَةِ","15"],[76,"Chapter: What is to be recited in Jumu`ah prayer","باب مَا يُقْرَأُ فِي صَلاَةِ الْجُمُعَةِ","16"],[81,"Chapter: What is to be recited on Friday","باب مَا يُقْرَأُ فِي يَوْمِ الْجُمُعَةِ","17"],[86,"Chapter: Prayer after Jumu`ah","باب الصَّلاَةِ بَعْدَ الْجُمُعَةِ","18"]],"8":[[10,"Chapter: It Is Permissible For Women To Go Out To The 'Id Prayer And Attend The Khutbah, Separated From The Men","باب ذِكْرِ إِبَاحَةِ خُرُوجِ النِّسَاءِ فِي الْعِيدَيْنِ إِلَى الْمُصَلَّى وَشُهُودِ الْخُطْبَةِ مُفَارِقَاتٌ لِلرِّجَالِ","1"],[13,"Chapter: Not Offering Any Other Prayer, Before Or After The 'Id Prayer At The Musalla (Prayer-Place)","باب تَرْكِ الصَّلاَةِ قَبْلَ الْعِيدِ وَبَعْدَهَا فِي الْمُصَلَّى","2"],[14,"Chapter: What Is To Be Recited In The 'Id Prayer?","باب مَا يُقْرَأُ بِهِ فِي صَلاَةِ الْعِيدَيْنِ","3"],[16,"Chapter: Concession Allowing Play That Involves No Disobedience During The Days Of 'Id","باب الرُّخْصَةِ فِي اللَّعِبِ الَّذِي لاَ مَعْصِيَةَ فِيهِ فِي أَيَّامِ الْعِيدِ","4"]],"9":[[5,"Chapter: Raising The Hands In Supplication When Praying For Rain","باب رَفْعِ الْيَدَيْنِ بِالدُّعَاءِ فِي الاِسْتِسْقَاءِ","1"],[9,"Chapter: The Supplication When Praying For Rain","باب الدُّعَاءِ فِي الاِسْتِسْقَاءِ","2"],[15,"Chapter: Seeking Refuge With Allah When Seeing Wind And Dark Clouds, And Rejoicing At The Rain","باب التَّعَوُّذِ عِنْدَ رُؤْيَةِ الرِّيحِ وَالْغَيْمِ وَالْفَرَحِ بِالْمَطَرِ","3"],[18,"Chapter: The East Wind And The West Wind","باب فِي رِيحِ الصَّبَا وَالدَّبُورِ","4"]],"10":[[1,"Chapter: The Eclipse Prayer","باب صَلاَةِ الْكُسُوفِ","1"],[9,"Chapter: Mentioning The Punishment In The Grave During The Eclipse Prayer","باب ذِكْرِ عَذَابِ الْقَبْرِ فِي صَلاَةِ الْخُسُوفِ","2"],[11,"Chapter: What Was Shown To The Prophet Of Paradise And Hell During The Eclipse Prayer","باب مَا عُرِضَ عَلَى النَّبِيِّ صلى الله عليه وسلم فِي صَلاَةِ الْكُسُوفِ مِنْ أَمْرِ الْجَنَّةِ وَالنَّارِ","3"],[20,"Chapter: Those Who Say That He Prayed With Eight Bowings And Four Prostrations","باب ذِكْرِ مَنْ قَالَ إِنَّهُ رَكَعَ ثَمَانَ رَكَعَاتٍ فِي أَرْبَعِ سَجَدَاتٍ","4"],[22,"Chapter: The Call For The Eclipse Prayer: \"As-Salatu Jami'ah (The Prayer Is Being Assembled)","باب ذِكْرِ النِّدَاءِ بِصَلاَةِ الْكُسُوفِ \" الصَّلاَةَ جَامِعَةً \"","5"]],"11":[[1,"Chapter: Prompt the Dying person to say La Ilaha Ill-Allah","باب تَلْقِينِ الْمَوْتَى لاَ إِلَهَ إِلاَّ اللَّهُ","1"],[4,"Chapter: What should be said at times of calamity?","باب مَا يُقَالُ عِنْدَ الْمُصِيبَةِ","2"],[7,"Chapter: What is to be said in the presence of the sick and the dying","باب مَا يُقَالُ عِنْدَ الْمَرِيضِ وَالْمَيِّتِ","3"],[8,"Chapter: Closing the eyes of the deceased and supplicating for him, when he dies","باب فِي إِغْمَاضِ الْمَيِّتِ وَالدُّعَاءِ لَهُ إِذَا حُضِرَ","4"],[10,"Chapter: The upward gaze of the deceased follows his soul","باب فِي شُخُوصِ بَصَرِ الْمَيِّتِ يَتْبَعُ نَفْسَهُ","5"],[12,"Chapter: Crying for the deceased","باب الْبُكَاءِ عَلَى الْمَيِّتِ","6"],[16,"Chapter: Visiting the sick","باب فِي عِيَادَةِ الْمَرْضَى","7"],[17,"Chapter: Patience in bearing calamity when it first strikes","باب فِي الصَّبْرِ عَلَى الْمُصِيبَةِ عِنْدَ الصَّدْمَةِ الأُولَى","8"],[20,"Chapter: The deceased is tormented because of his family's crying for him","باب الْمَيِّتُ يُعَذَّبُ بِبُكَاءِ أَهْلِهِ عَلَيْهِ","9"],[38,"Chapter: Stern warning against wailing","باب التَّشْدِيدِ فِي النِّيَاحَةِ","10"],[44,"Chapter: Prohibition of women attending funerals","باب نَهْىِ النِّسَاءِ عَنِ اتِّبَاعِ الْجَنَائِزِ،","11"],[46,"Chapter: Washing the deceased","باب فِي غَسْلِ الْمَيِّتِ","12"],[55,"Chapter: Shrouding the deceased","باب فِي كَفَنِ الْمَيِّتِ","13"],[61,"Chapter: Covering the deceased","باب تَسْجِيَةِ الْمَيِّتِ","14"],[63,"Chapter: Shrouding the deceased well","باب فِي تَحْسِينِ كَفَنِ الْمَيِّتِ","15"],[64,"Chapter: Hastening with the funeral","باب الإِسْرَاعِ بِالْجَنَازَةِ","16"],[67,"Chapter: The virtue of offering the funeral prayer and following the bier","باب فَضْلِ الصَّلاَةِ عَلَى الْجَنَازَةِ وَاتِّبَاعِهَا","17"],[76,"Chapter: If one hundred (people) pray for a person, they will intercede for him","باب مَنْ صَلَّى عَلَيْهِ مِائَةٌ شُفِّعُوا فِيهِ","18"],[77,"Chapter: If forty people pray for a person, they will intercede for him","باب مَنْ صَلَّى عَلَيْهِ أَرْبَعُونَ شُفِّعُوا فِيهِ","19"],[78,"Chapter: The deceased who is spoken well of and the one who is spoken badly of","باب فِيمَنْ يُثْنَى عَلَيْهِ خَيْرٌ أَوْ شَرٌّ مِنَ الْمَوْتَى","20"],[80,"Chapter: What was narrated concerning one who finds relief and one from whom relief is found","باب مَا جَاءَ فِي \" مُسْتَرِيحٌ وَمُسْتَرَاحٌ مِنْهُ \"","21"],[82,"Chapter: Saying the takbir over the deceased","باب فِي التَّكْبِيرِ عَلَى الْجَنَازَةِ","22"],[89,"Chapter: Praying over the grave","باب الصَّلاَةِ عَلَى الْقَبْرِ","23"],[95,"Chapter: Standing for funerals","باب الْقِيَامِ لِلْجَنَازَةِ","24"],[104,"Chapter: Abrogation of standing for funerals","باب نَسْخِ الْقِيَامِ لِلْجَنَازَةِ","25"],[109,"Chapter: Supplicating for the deceased during the (funeral) prayer","باب الدُّعَاءِ لِلْمَيِّتِ فِي الصَّلاَةِ","26"],[112,"Chapter: Where the Imam should stand in relation to the deceased when performing the funeral prayer","باب أَيْنَ يَقُومُ الإِمَامُ مِنَ الْمَيِّتِ لِلصَّلاَةِ عَلَيْهِ","27"],[115,"Chapter: Riding back after the funeral","باب رُكُوبِ الْمُصَلِّي عَلَى الْجَنَازَةِ إِذَا انْصَرَفَ","28"],[117,"Chapter: The Lahd (Niche), and setting up bricks over the deceased","باب فِي اللَّحْدِ وَنَصْبِ اللَّبِنِ عَلَى الْمَيِّتِ","29"],[118,"Chapter: Putting a piece of velvet in the grave","باب جَعْلِ الْقَطِيفَةِ فِي الْقَبْرِ","30"],[119,"Chapter: The command to level the grave","باب الأَمْرِ بِتَسْوِيَةِ الْقَبْرِ","31"],[121,"Chapter: The prohibition of plastering graves or erecting structures over them","باب النَّهْىِ عَنْ تَجْصِيصِ الْقَبْرِ، وَالْبِنَاءِ، عَلَيْهِ","32"],[124,"Chapter: Prohibition against sitting and praying on graves","باب النَّهْىِ عَنِ الْجُلُوسِ، عَلَى الْقَبْرِ وَالصَّلاَةِ عَلَيْهِ","33"],[128,"Chapter: Offering the funeral prayer in the masjid","باب الصَّلاَةِ عَلَى الْجَنَازَةِ فِي الْمَسْجِدِ","34"],[131,"Chapter: What is to be said when entering the graveyard and supplicating for its occupants","باب مَا يُقَالُ عِنْدَ دُخُولِ الْقُبُورِ وَالدُّعَاءِ لأَهْلِهَا","35"],[134,"Chapter: The prophet (saws) asked his Lord for permission to visit the grave of his mother","باب اسْتِئْذَانِ النَّبِيِّ صلى الله عليه وسلم رَبَّهُ عَزَّ وَجَلَّ فِي زِيَارَةِ قَبْرِ أُمِّهِ","36"],[138,"Chapter: Leaving the funeral prayer for one who committed suicide","باب تَرْكِ الصَّلاَةِ عَلَى الْقَاتِلِ نَفْسَهُ","37"]],"12":[[10,"Chapter: On what one-tenth or half of one-tenth is due","باب مَا فِيهِ الْعُشْرُ أَوْ نِصْفُ الْعُشْرِ","1"],[11,"Chapter: The Muslim is not obliged to give Zakat on his slave nor his horse","باب لاَ زَكَاةَ عَلَى الْمُسْلِمِ فِي عَبْدِهِ وَفَرَسِهِ","2"],[15,"Chapter: Paying or withholding Zakat","باب فِي تَقْدِيمِ الزَّكَاةِ وَمَنْعِهَا","3"],[16,"Chapter: Zakat Al-Fitr is due from the muslims in the form of dates and barley","باب زَكَاةِ الْفِطْرِ عَلَى الْمُسْلِمِينَ مِنَ التَّمْرِ وَالشَّعِيرِ","4"],[26,"Chapter: The command to pay Zakat Al-Fitr before the prayer","باب الأَمْرِ بِإِخْرَاجِ زَكَاةِ الْفِطْرِ قَبْلَ الصَّلاَةِ","5"],[28,"Chapter: The sin of one who withholds Zakat","باب إِثْمِ مَانِعِ الزَّكَاةِ","6"],[35,"Chapter: Pleasing the Su'ah (Zakat Collectors)","باب إِرْضَاءِ السُّعَاةِ","7"],[37,"Chapter: Severe Punishment for the one who does not pay Zakat","باب تَغْلِيظِ عُقُوبَةِ مَنْ لاَ يُؤَدِّي الزَّكَاةَ","8"],[41,"Chapter: Encouragement to give Charity","باب التَّرْغِيبِ فِي الصَّدَقَةِ","9"],[43,"Chapter: Stern warning concerning those who hoard wealth","باب فِي الْكَنَّازِينَ لِلأَمْوَالِ وَالتَّغْلِيظِ عَلَيْهِمْ","10"],[45,"Chapter: Encouragement to spend and glad tidings of compensation for the one who spends on good deeds","باب الْحَثِّ عَلَى النَّفَقَةِ وَتَبْشِيرِ الْمُنْفِقِ بِالْخَلَفِ","11"],[47,"Chapter: The virtue of spending on one's family and slaves, and the sin of the one who neglects them or withholds maintenance from them","باب فَضْلِ النَّفَقَةِ عَلَى الْعِيَالِ وَالْمَمْلُوكِ وَإِثْمِ مَنْ ضَيَّعَهُمْ أَوْ حَبَسَ نَفَقَتَهُمْ عَنْهُمْ","12"],[50,"Chapter: Starting with oneself, then one's family, then one's relatives, when spending","باب الاِبْتِدَاءِ فِي النَّفَقَةِ بِالنَّفْسِ ثُمَّ أَهْلِهِ ثُمَّ الْقَرَابَةِ","13"],[52,"Chapter: The virtue of spending and giving charity to relatives, spuses, children and parents, even if they are idolaters","باب فَضْلِ النَّفَقَةِ وَالصَّدَقَةِ عَلَى الْأَقْرَبِينَ وَالزَّوْجِ وَالْأَوْلَادِ وَالْوَالِدَيْنِ وَلَوْ كَانُوا مُشْرِكِينَ","14"],[63,"Chapter: Charity given on behalf of the deceased will reach him","باب وُصُولِ ثَوَابِ الصَّدَقَةِ عَنِ الْمَيِّتِ، إِلَيْهِ","15"],[65,"Chapter: The word charity (Sadaqah) may apply to all good deeds Ma'ruf","باب بَيَانِ أَنَّ اسْمَ الصَّدَقَةِ يَقَعُ عَلَى كُلِّ نَوْعٍ مِنَ الْمَعْرُوفِ","16"],[73,"Chapter: The one who spends and the one who withholds","باب فِي الْمُنْفِقِ وَالْمُمْسِكِ","17"],[74,"Chapter: Encouragement to give charity before there is no one to accept it","باب التَّرْغِيبِ فِي الصَّدَقَةِ قَبْلَ أَنْ لاَ يُوجَدَ مَنْ يَقْبَلُهَا","18"],[79,"Chapter: Acceptance of charity that comes from good (Tayyib) earnings, and the growth thereof","باب قَبُولِ الصَّدَقَةِ مِنَ الْكَسْبِ الطَّيِّبِ وَتَرْبِيَتِهَا","19"],[84,"Chapter: Encouragement to give charity even if it is with half a date or a kind word. And charity is a shield against the fire.","باب الْحَثِّ عَلَى الصَّدَقَةِ وَلَوْ بِشِقِّ تَمْرَةٍ أَوْ كَلِمَةٍ طَيِّبَةٍ وَأَنَّهَا حِجَابٌ مِنْ النَّارِ","20"],[92,"Chapter: Carrying goods for payment and giving charity out of one's wages, and the stern prohibition of belittling the one who gives something small in charity","باب الْحَمْلِ بِأُجْرَةٍ يُتَصَدَّقُ بِهَا وَالنَّهْىِ الشَّدِيدِ عَنْ تَنْقِيصِ الْمُتَصَدِّقِ بِقَلِيل","21"],[94,"Chapter: The virute of giving gifts","باب فَضْلِ الْمَنِيحَةِ","22"],[96,"Chapter: The Likeness of the giver and the miser","باب مَثَلِ الْمُنْفِقِ وَالْبَخِيلِ","23"],[99,"Chapter: Confirmation of the reward of the one who gives Charity, even if the Charity ends up in the hands of an evildoer, and the like","باب ثُبُوتِ أَجْرِ الْمُتَصَدِّقِ وَإِنْ وَقَعَتِ الصَّدَقَةُ فِي يَدِ غَيْرِ أَهْلِهَا","24"],[100,"Chapter: The reward of the Trustworthy Trustee, and if a woman gives charity from her husband's house without causing any damage, with his explicit or implicit permission","باب أَجْرِ الْخَازِنِ الأَمِينِ وَالْمَرْأَةِ إِذَا تَصَدَّقَتْ مِنْ بَيْتِ زَوْجِهَا غَيْرَ مُفْسِدَةٍ ب","25"],[105,"Chapter: What a slave spends of his master's wealth","باب مَا أَنْفَقَ الْعَبْدُ مِنْ مَالِ مَوْلاَهُ","26"],[108,"Chapter: The virtue of the one who does other kinds of good deeds in addition to giving charity","باب مَنْ جَمَعَ الصَّدَقَةَ وَأَعْمَالَ الْبِرِّ","27"],[112,"Chapter: Encouragement to spend, and it is disliked to count how much","باب الْحَثِّ فِي الإِنْفَاقِ وَكَرَاهَةِ الإِحْصَاءِ","28"],[116,"Chapter: Encouragement to give in charity even if it is a little, and a little should not be withheld because one thinks it is too little","باب الْحَثِّ عَلَى الصَّدَقَةِ وَلَوْ بِالْقَلِيلِ وَلاَ تُمْتَنَعُ مِنَ الْقَلِيلِ لاِحْتِقَارِهِ","29"],[117,"Chapter: The virtue of concealing (what is given in) charity","باب فَضْلِ إِخْفَاءِ الصَّدَقَةِ","30"],[119,"Chapter: The best of charity is that which is given when one is healthy and inclined to be stingy","باب بَيَانِ أَنَّ أَفْضَلَ الصَّدَقَةِ صَدَقَةُ الصَّحِيحِ الشَّحِيحِ","31"],[122,"Chapter: The upper hand is better than the lower hand, and the upper hand is the one that gives and the lower hand is the one that receives","باب بَيَانِ أَنَّ الْيَدَ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى وَأَنَّ الْيَدَ الْعُلْيَا هِيَ الْمُنْفِقَةُ وَأَنَّ السُّفْلَى هِيَ الْآخِذَةُ","32"],[126,"Chapter: The prohibition of Begging","باب النَّهْىِ عَنِ الْمَسْأَلَةِ","33"],[130,"Chapter: The poor person who cannot find enough to make him independent of means, but the people do not realize that he is in need, so they do not give Charity to him","باب الْمِسْكِينِ الَّذِي لاَ يَجِدُ غِنًى وَلاَ يُفْطَنُ لَهُ فَيُتَصَدَّقَ عَلَيْهِ","34"],[133,"Chapter: It is disliked to beg from people","باب كَرَاهَةِ الْمَسْأَلَةِ لِلنَّاسِ","35"],[141,"Chapter: The one for whom it is permissible to ask for help","باب مَنْ تَحِلُّ لَهُ الْمَسْأَلَةُ","36"],[142,"Chapter: It is permissible to take without asking for it or hoping for it","باب إِبَاحَةِ الأَخْذِ لِمَنْ أُعْطِيَ مِنْ غَيْرِ مَسْأَلَةٍ وَلاَ إِشْرَافٍ","37"],[147,"Chapter: It is disliked to be eager to acquire worldly gains","باب كَرَاهَةِ الْحِرْصِ عَلَى الدُّنْيَا","38"],[152,"Chapter: If the Son of Adam had two valleys, he would desire a third","باب لَوْ أَنَّ لاِبْنِ آدَمَ وَادِيَيْنِ لاَبْتَغَى ثَالِثًا","39"],[157,"Chapter: The virtue of contentment and encouragement thereof","باب لَيْسَ الْغِنَى عَنْ كَثْرَةِ الْعَرَضِ","40"],[158,"Chapter: Warning against being deceived by the splendor and luxury of this world","باب تَخَوُّفِ مَا يَخْرُجُ مِنْ زَهْرَةِ الدُّنْيَا","41"],[161,"Chapter: The virtue of refraining from asking and being patient and content","باب فَضْلِ التَّعَفُّفِ وَالصَّبْرِ","42"],[163,"Chapter: Sufficient provision and contentment","باب فِي الْكَفَافِ وَالْقَنَاعَةِ","43"],[165,"Chapter: Giving to those whose hearts have been inclined (towards Islam) and to those for whose faith there is fear if they are not given anything, and putting up with the one who asks rudely due to ignorance, and the Khawarij and rulings regarding them","باب إِعْطَاءِ مَنْ سَأَلَ بِفُحْشٍ وَغِلْظَةٍ","44"],[170,"Chapter: Giving to one whose faith one fears","باب إِعْطَاءِ مَنْ يُخَافُ عَلَى إِيمَانِهِ","45"],[173,"Chapter: Giving to those whose hearts have been inclined (towards Islam) and urging those whose faith is strong to show patience","باب إِعْطَاءِ الْمُؤَلَّفَةِ قُلُوبُهُمْ عَلَى الإِسْلاَمِ وَتَصَبُّرِ مَنْ قَوِيَ إِيمَانُهُ","46"],[186,"Chapter: The Khawarij and their attributes","باب ذِكْرِ الْخَوَارِجِ وَصِفَاتِهِمْ","47"],[199,"Chapter: Exhortation to kill the Khawarij","باب التَّحْرِيضِ عَلَى قَتْلِ الْخَوَارِجِ","48"],[206,"Chapter: The Khawarij are the most evil of people and of all creation","باب الْخَوَارِجُ شَرُّ الْخَلْقِ وَالْخَلِيقَةِ","49"],[210,"Chapter: Zakat is forbidden for the messenger of Allah pbuh and his family, and they are Banu Hashim and Banu Al-Muttalib, and no one else","باب تَحْرِيمِ الزَّكَاةِ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَى آلِهِ وَهُمْ بَنُو هَاشِمٍ وَبَنُو الْمُطَّلِبِ دُونَ غَيْرِهِمْ","50"],[218,"Chapter: Not appointing the family of the prophet (saws) in charge of charity","باب تَرْكِ اسْتِعْمَالِ آلِ النَّبِيِّ عَلَى الصَّدَقَةِ","51"],[220,"Chapter: Gifts are permissible for the Prophet (saws) and Banu Hashim and Banu Al-Muttalib, even if the giver acquired it by way of charity. When the receipient takes possession of Charity, it is no longer described as charity, and it is permissible for anyone for whom charity is otherwise unlawful","باب إِبَاحَةِ الْهَدِيَّةِ لِلنَّبِيِّ صلى الله عليه وسلم وَلِبَنِي هَاشِمٍ وَبَنِي الْمُطَّلِبِ","52"],[228,"Chapter: The prophet (saws) accepted gifts but refused Charity","باب قَبُولِ النَّبِيِّ الْهَدِيَّةَ وَرَدِّهِ الصَّدَقَةَ","53"],[229,"Chapter: The supplication for the one who brings Charity","باب الدُّعَاءِ لِمَنْ أَتَى بِصَدَقَتِهِ","54"],[231,"Chapter: Pleasing the Zakat Collector unless he asks for something unlawful","باب إِرْضَاءِ السَّاعِي مَا لَمْ يَطْلُبْ حَرَامًا","55"]],"13":[[1,"Chapter: The Virtues of the month of Ramadan","باب فَضْلِ شَهْرِ رَمَضَانَ","1"],[4,"Chapter: The obligation to fast Ramadan when the crescent is sighted, and to break the fast when the crescent is sighted, and that if it is cloudy at the beginning or end of the month, then the month should be completed as thirty days.","بَاب وُجُوبِ صَوْمِ رَمَضَانَ لِرُؤْيَةِ الْهِلَالِ وَالْفِطْرِ لِرُؤْيَةِ الْهِلَالِ وَأَنَّهُ إِذَا غُمَّ فِي أَوَّلِهِ أَوْ آخِرِهِ أُكْمِلَتْ عِدَّةُ الشَّهْرِ ثَلَاثِينَ يَوْمًا","2"],[24,"Chapter: Do not start fasting one or two days before Ramadan","باب لاَ تَقَدَّمُوا رَمَضَانَ بِصَوْمِ يَوْمٍ وَلاَ يَوْمَيْنِ","3"],[26,"Chapter: The month may be twenty-nine days","باب الشَّهْرُ يَكُونُ تِسْعًا وَعِشْرِينَ","4"],[34,"Chapter: Each land has its own sighting of the moon, and if they see the crescent in one land, that does not necessarily apply to regions that are far away from it","باب بَيَانِ أَنَّ لِكُلِّ بَلَدٍ رُؤْيَتَهُمْ وَأَنَّهُمْ إِذَا رَأَوْا الْهِلَالَ بِبَلَدٍ لَا يَثْبُتُ حُكْمُهُ لِمَا بَعُدَ عَنْهُمْ","5"],[35,"Chapter: Clarifying that it does not matter whether the crescent is large or small, for Allah, the Most High, causes it to appear for long enough that people can see it, and if it is cloudy then thirty days should be completed","باب بَيَانِ أَنَّهُ لَا اعْتِبَارَ بِكُبْرِ الْهِلَالِ وَصِغَرِهِ وَأَنَّ اللَّهَ تَعَالَى أَمَدَّهُ لِلرُّؤْيَةِ فَإِنْ غُمَّ فَلْيُكْمَلْ ثَلَاثُونَ","6"],[37,"Chapter: The meaning of the Prophet's words: \"The two months of 'Id cannot both be incomplete\"","باب بَيَانِ مَعْنَى قَوْلِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَهْرَا عِيدٍ لَا يَنْقُصَانِ","7"],[39,"Chapter: Clarifying that fasting begins at dawn, and a person may eat and other than that until dawn begins; And clarifying the dawn which has to do with the rulings concerning the beginning of fasting and the beginning of the time for the Subh Prayer, and other than that, which is the Second Dawn, which is called the True Dawn. The First Dawn, which is the False Dawn, has nothing to do with the rulings","بَاب بَيَانِ أَنَّ الدُّخُولَ فِي الصَّوْمِ يَحْصُلُ بِطُلُوعِ الْفَجْرِ وَأَنَّ لَهُ الْأَكْلَ وَغَيْرَهُ حَتَّى يَطْلُعَ الْفَجْرُ وَبَيَانِ صِفَةِ الْفَجْرِ الَّذِي تَتَعَلَّقُ بِهِ الْأَحْكَامُ مِنْ الدُّخُولِ فِي الصَّوْمِ وَدُخُولِ وَقْتِ صَلَاةِ الصُّبْحِ وَغَيْرِ ذَلِكَ","8"],[55,"Chapter: The virtue of sahur, which is recommended. It is recommended to delay it and to hasten the breaking of the fast","باب فَضْلِ السُّحُورِ وَتَأْكِيدِ اسْتِحْبَابِهِ وَاسْتِحْبَابِ تَأْخِيرِهِ وَتَعْجِيلِ الْفِطْرِ","9"],[64,"Chapter: Clarifying the time for ending the fast and the end of the day","باب بَيَانِ وَقْتِ انْقِضَاءِ الصَّوْمِ وَخُرُوجِ النَّهَارِ","10"],[69,"Chapter: The prohibition of Al-Wisal","باب النَّهْىِ عَنِ الْوِصَالِ، فِي الصَّوْمِ","11"],[79,"Chapter: Clarifying that Kissing when fasting is not unlawful for the one whose desire is not provoked by that","باب بَيَانِ أَنَّ الْقُبْلَةَ فِي الصَّوْمِ لَيْسَتْ مُحَرَّمَةً عَلَى مَنْ لَمْ تُحَرِّكْ شَهْوَتَهُ","12"],[95,"Chapter: The fasting is valid for the one who is Junub when dawn comes","باب صِحَّةِ صَوْمِ مَنْ طَلَعَ عَلَيْهِ الْفَجْرُ وَهُوَ جُنُبٌ","13"],[101,"Chapter: The strict prohibition of intercourse during the day in Ramadan for one who is fasting; And the obligation of offering major expiation and the definition thereof; And that it is obligatory for both the one who can afford it and the one who cannot afford it, and it remains an obligation for the one who cannot afford it until he has the means","باب تَغْلِيظِ تَحْرِيمِ الْجِمَاعِ فِي نَهَارِ رَمَضَانَ عَلَى الصَّائِمِ وَوُجُوبِ الْكَفَّارَةِ الْكُبْرَى فِيهِ وبيانها وأنها تجب على الموسر والمعسر وتثبت في ذمة المعسر حتى يستطيع","14"],[110,"Chapter: It is permissible to fast or not to fast during Ramadan for one who is travelling for no sinful purpose, if his journey is two stages or further. But it is better for the one who is able to fast without suffering any harm to do so, and the one for whom it is difficult may break the fast","باب جواز الصوم والفطر في شهر رمضان للمسافر في غير معصية إذا كان سفره مرحلتين فأكثر وأن الأفضل لمن أطاقه بلا ضرر أن يصوم ولمن يشق عليه أن يفطر","15"],[128,"Chapter: The reward of the one who does not fast when travelling if he does any tasks that are required","باب أَجْرِ الْمُفْطِرِ فِي السَّفَرِ إِذَا تَوَلَّى الْعَمَلَ","16"],[131,"Chapter: The choice between fasting and not fasting when travelling","باب التَّخْيِيرِ فِي الصَّوْمِ وَالْفِطْرِ فِي السَّفَرِ","17"],[138,"Chapter: It is recommended for the person performing Hajj in 'Arafat not to fast on the day of 'Arafah.","باب اسْتِحْبَابِ الْفِطْرِ لِلْحَاجِّ بِعَرَفَاتٍ يَوْمَ عَرَفَةَ","18"],[143,"Chapter: Fasting on the day of Ashura'","باب صَوْمِ يَوْمِ عَاشُورَاءَ","19"],[170,"Chapter: Which day should be fasted for 'Ashura?","باب أَىُّ يَوْمٍ يُصَامُ فِي عَاشُورَاءَ","20"],[174,"Chapter: Whoever eats on'Ashura, let him refrain (from eating) for the rest of the day","باب مَنْ أَكَلَ فِي عَاشُورَاءَ فَلْيَكُفَّ بَقِيَّةَ يَوْمِهِ","21"],[177,"Chapter: The prohibition of fasting on the two days of 'Id","باب النَّهْىِ عَنْ صَوْمِ، يَوْمِ الْفِطْرِ وَيَوْمِ الأَضْحَى","22"],[183,"Chapter: The prohibition of fasting the days of At-Tashriq, which are the days of eating, drinking and remembering Allah, The Mighty and Sublime","باب تَحْرِيمِ صَوْمِ أَيَّامِ التَّشْرِيقِ","23"],[187,"Chapter: It is disliked to single out Friday for fasting, unless it coincides with a day that one customarily fasts","باب كَرَاهِيَةِ صِيَامِ يَوْمِ الْجُمُعَةِ مُنْفَرِدًا","24"],[191,"Chapter: The Saying of Allah Most High: \"... And as for those who can fast with difficulty, they have) a choice either to fast or) to feed a Miskin (poor person) (for every day)\" is Abrogated by His saying: \"... So whoever of you sights (the crescent on the first night of) the month (of Ramadan i.e. is present at his home), he must observe Sawm (fasts) that month\"...","باب بَيَانِ نَسْخِ قَوْلِهِ تَعَالَى { وَعَلَى الَّذِينَ يُطِيقُونَه} فِدْيَةٌ بِقَوْلِهِ فَمَنْ شَهِدَ مِنْكُمْ الشَّهْرَ فَلْيَصُمْهُ","25"],[193,"Chapter: It is Permissible to delay making up missed Ramadan Fasts until before the next Ramadan comes, and this is for those who broke the fast for a reason such as sickness, travel, menstruation and the like","باب قَضَاءِ رَمَضَانَ فِي شَعْبَانَ","26"],[198,"Chapter: Making up fasts on behalf of the deceased","باب قَضَاءِ الصِّيَامِ عَنِ الْمَيِّتِ","27"],[208,"Chapter: If a fasting person is invited to eat and he does not want to break his fast, or someone insults him or argues with him, it is recommended for him to say: \"I am Fasting\", and he should protect his fast from obscene speech, ignorance and the like","باب الصَّائِمِ يُدْعَى لِطَعَامٍ أَوْ يُقَاتَلُ فَلْيَقُلْ إِنِّي صَائِمٌ","28"],[209,"Chapter: Guarding One's Tongue when Fasting","باب حِفْظِ اللِّسَانِ لِلصَّائِمِ","29"],[210,"Chapter: The Virtue of Fasting","باب فَضْلِ الصِّيَامِ","30"],[217,"Chapter: The Virtue of Fasting for in the cause of Allah, for those who are able to without suffering any harm or neglecting other duties","باب فَضْلِ الصِّيَامِ فِي سَبِيلِ اللَّهِ لِمَنْ يُطِيقُهُ بِلاَ ضَرَرٍ وَلاَ تَفْوِيتِ حَقٍّ","31"],[220,"Chapter: It is permissible to observe a voluntary fast with an intention formed during the day before the sun reaches its Zenith, and it is permissible for one who is observing a voluntary fast to break his fast with no excuse, although it is better for him to complete it","بَاب جَوَازِ صَوْمِ النَّافِلَةِ بِنِيَّةٍ مِنْ النَّهَارِ قَبْلَ الزَّوَالِ وَجَوَازِ فِطْرِ الصَّائِمِ نَفْلًا مِنْ غَيْرِ عُذْرٍ","32"],[222,"Chapter: The one who eats, drinks, or has intercourse by mistake does not break his fast","باب أَكْلُ النَّاسِي وَشُرْبُهُ وَجِمَاعُهُ لاَ يُفْطِرُ","33"],[223,"Chapter: The Prophet's Fasts at times other than Ramadan; and it is recommended to ensure that no month is free of fasting","بَاب صِيَامِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَيْرِ رَمَضَانَ وَاسْتِحْبَابِ أَنْ لَا يُخْلِيَ شَهْرًا عَنْ صَوْمٍ","34"],[235,"Chapter: Prohibition of Fasting for a lifetime for the one who will be harmed by that or who will neglect other duties, or does not break his fast on the two 'Ids or during the days of At-Tashriq; It is better to fast alternate days","بَاب النَّهْيِ عَنْ صَوْمِ الدَّهْرِ لِمَنْ تَضَرَّرَ بِهِ أَوْ فَوَّتَ بِهِ حَقًّا أَوْ لَمْ يُفْطِرْ الْعِيدَيْنِ وَالتَّشْرِيقَ وَبَيَانِ تَفْضِيلِ صَوْمِ يَوْمٍ وَإِفْطَارِ يَوْمٍ","35"],[250,"Chapter: It is recommended to fast three days of every month, and to fast on the days of 'Arafah and 'Ashura', and to fast on Mondays and Thursdays","باب اسْتِحْبَابِ صِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ وَصَوْمِ يَوْمِ عَرَفَةَ وَعَاشُورَاءَ وَالِاثْنَيْنِ وَالْخَمِيسِ","36"],[257,"Chapter: Fasting at the end of Sha'ban","باب صَوْمِ سَرَرِ شَعْبَانَ","37"],[261,"Chapter: The virtue of fasting Muharram","باب فَضْلِ صَوْمِ الْمُحَرَّمِ","38"],[264,"Chapter: It is recommended to fast Six Days in Shawwal following Ramadan","باب اسْتِحْبَابِ صَوْمِ سِتَّةِ أَيَّامٍ مِنْ شَوَّالٍ اتِّبَاعًا لِرَمَضَانَ","39"],[267,"Chapter: The virtue of Lailat Al-Qadr and the Exhortation to seek it; When it is and the most likely times to seek it","باب فَضْلِ لَيْلَةِ الْقَدْرِ وَالْحَثِّ عَلَى طَلَبِهَا وَبَيَانِ مَحَلِّهَا وَأَرْجَى أَوْقَاتِ طَلَبِهَا","40"]],"14":[[1,"Chapter: I'tikaf during the last ten days of Ramadan","باب اعْتِكَافِ الْعَشْرِ الأَوَاخِرِ مِنْ رَمَضَانَ","1"],[6,"Chapter: When should the one who wants to observe I'tikaf enter his place of I'tikaf ?","باب مَتَى يَدْخُلُ مَنْ أَرَادَ الاِعْتِكَافَ فِي مُعْتَكَفِهِ","2"],[8,"Chapter: Striving harder in worship during the last ten days of Ramadan","باب الاِجْتِهَادِ فِي الْعَشْرِ الأَوَاخِرِ مِنْ شَهْرِ رَمَضَانَ","3"],[10,"Chapter: Fasting the (first) ten days of Dhul Hijjah","باب صَوْمِ عَشْرِ ذِي الْحِجَّةِ","4"]],"15":[[1,"Chapter: What one who has entered Ihram for Hajj or Umrah is permitted to wear, and what is not permissible, and perfume is forbidden for him","باب مَا يُبَاحُ لِلْمُحْرِمِ بِحَجٍّ أَوْ عُمْرَةٍ وَمَا لاَ يُبَاحُ وَبَيَانِ تَحْرِيمِ الطِّيبِ عَلَيْهِ","1"],[13,"Chapter: The Mawaqit of Hajj","باب مَوَاقِيتِ الْحَجِّ وَالْعُمْرَةِ","2"],[21,"Chapter: The Talbiyah, its description and timing","باب التَّلْبِيَةِ وَصِفَتِهَا وَوَقْتِهَا","3"],[26,"Chapter: The command to the people of Al-Madinah to enter Ihram from the Masjid at Dhul-Hulaifah","باب أَمْرِ أَهْلِ الْمَدِينَةِ بِالإِحْرَامِ مِنْ عِنْدِ مَسْجِدِ ذِي الْحُلَيْفَةِ","4"],[28,"Chapter: Clarifying that it is better to enter Ihram when a person's mount sets off with him, heading towards Makkah, not straight after the two rak'ah","باب الإِهْلاَلِ مِنْ حَيْثُ تَنْبَعِثُ الرَّاحِلَةُ","5"],[33,"Chapter: Praying at the Masjid of Dhul-Hulaifah","باب الصَّلاَةِ فِي مَسْجِدِ ذِي الْحُلَيْفَةِ","6"],[34,"Chapter: It is recommended to apply perfume just before entering Ihram, and it is recommended to use Musk, and it does not matter if its glistening traces remain","باب الطِّيبِ لِلْمُحْرِمِ عِنْدَ الإِحْرَامِ","7"],[55,"Chapter: The prohibition of hunting game for the one who has entered Ihram for Hajj or for Umrah or for both","باب تَحْرِيمِ الصَّيْدِ لِلْمُحْرِمِ","8"],[71,"Chapter: What animals it is recommended for the Muhrim and others to kill inside and outside the Sanctuary","باب مَا يُنْدَبُ لِلْمُحْرِمِ وَغَيْرِهِ قَتْلُهُ مِنَ الدَّوَابِّ فِي الْحِلِّ وَالْحَرَمِ","9"],[87,"Chapter: It is permissible for a Muhrim to shave his head if there is a problem, but it is obligatory to offer a Fidyah for shaving it, and Clarifying what the Fidyah is","باب جَوَازِ حَلْقِ الرَّأْسِ لِلْمُحْرِمِ إِذَا كَانَ بِهِ أَذًى وَوُجُوبِ الْفِدْيَةِ لِحَلْقِهِ وَبَيَانِ قَدْرِهَا","10"],[95,"Chapter: Cupping is permissible for the Muhrim (pilgrim in Ihram)","باب جَوَازِ الْحِجَامَةِ لِلْمُحْرِمِ","11"],[97,"Chapter: It is permissible for a Muhrim to treat his eyes","باب جَوَازِ مُدَاوَاةِ الْمُحْرِمِ عَيْنَيْهِ","12"],[99,"Chapter: It is permissible for the Muhrim to wash his body and head","باب جَوَازِ غَسْلِ الْمُحْرِمِ بَدَنَهُ وَرَأْسَهُ","13"],[101,"Chapter: What should be done with a Muhrim if he dies?","باب مَا يُفْعَلُ بِالْمُحْرِمِ إِذَا مَاتَ","14"],[111,"Chapter: It is permissible for the Muhrim to stipulate a condition for exiting Ihram because of sickness and the like","باب جَوَازِ اشْتِرَاطِ الْمُحْرِمِ التَّحَلُّلَ بِعُذْرِ الْمَرَضِ وَنَحْوِهِ","15"],[117,"Chapter: The soundness of Ihram for the woman in Nifas; It is recommended for her to perform Ghusl before entering Ihram, and the same applies to one who is menstruating","باب إِحْرَامِ النُّفَسَاءِ وَاسْتِحْبَابِ اغْتِسَالِهَا لِلإِحْرَامِ وَكَذَا الْحَائِضِ","16"],[119,"Chapter: Clarifying the types of Ihram; and that it is permissible to perfom Hajj that is Ifrad, Tamattu and Qiran. It is permissible to join Hajj to Umrah. And when the pilgrim who is performing Qiran should exit Ihram","باب بَيَانِ وُجُوهِ الإِحْرَامِ وَأَنَّهُ يَجُوزُ إِفْرَادُ الْحَجِّ وَالتَّمَتُّعِ وَالْقِرَانِ وَجَوَازِ إِدْخَالِ الْحَجِّ عَلَى الْعُمْرَةِ وَمَتَى يَحِلُّ الْقَارِنُ مِنْ نُسُكِهِ","17"],[156,"Chapter: Tamattu with Hajj and Umrah","باب فِي الْمُتْعَةِ بِالْحَجِّ وَالْعُمْرَةِ","18"],[159,"Chapter: The Hajj of the Prophet saws","باب حَجَّةِ النَّبِيِّ صلى الله عليه وسلم","19"],[161,"Chapter: All of Arafat is a place of standing","باب مَا جَاءَ أَنَّ عَرَفَةَ كُلَّهَا مَوْقِفٌ","20"],[163,"Chapter: The Standing and the Saying of Allah, The Most High: \"Then depart from the place whence all the people depart\"","باب فِي الْوُقُوفِ وَقَوْلِهِ تَعَالَى { ثُمَّ أَفِيضُوا مِنْ حَيْث أَفَاضَ النَّاسُ}","21"],[166,"Chapter: It is permissible to base one's intention for Ihram on the intention of another","باب فِي نَسْخِ التَّحَلُّلِ مِنَ الإِحْرَامِ وَالأَمْرِ بِالتَّمَامِ","22"],[171,"Chapter: The Permissibilty of Tamattu'","باب جَوَازِ التَّمَتُّعِ","23"],[190,"Chapter: The Obligation For the Pilgrim who is performing Tamattu' to offer a sacrifice; If he has no animal to sacrifice, he must fast for three days during Hajj and seven days when he goes back to his family","باب وُجُوبِ الدَّمِ عَلَى الْمُتَمَتِّعِ وَأَنَّهُ إِذَا عَدِمَهُ لَزِمَهُ صَوْمُ ثَلاَثَةِ أَيَّامٍ فِي الْحَجِّ وَسَبْعَةٍ إِذَا رَجَعَ إِلَى أَهْلِهِ","24"],[192,"Chapter: The pilgrim performing Qiran should not exit Ihram except when the pilgrims performing Ifrad exit Ihram","باب بَيَانِ أَنَّ الْقَارِنَ لاَ يَتَحَلَّلُ إِلاَّ فِي وَقْتِ تَحَلُّلِ الْحَاجِّ الْمُفْرِدِ","25"],[197,"Chapter: It is permissible to exit Ihram if one is prevented from completing Hajj; It is permissible to perform Qiran and the pilgrim performing Qiran should perform just one Tawaf and one Sa'i","باب بَيَانِ جَوَازِ التَّحَلُّلِ بِالإِحْصَارِ وَجَوَازِ الْقِرَانِ","26"],[202,"Chapter: Ifrad and Qiran","باب فِي الإِفْرَادِ وَالْقِرَانِ بِالْحَجِّ وَالْعُمْرَةِ","27"],[205,"Chapter: It is recommended for the pilgrim to perform Tawaf Al-Qudum and As-Sa'i after it","باب مَا يَلْزَمُ مَنْ أَحْرَمَ بِالْحَجِّ ثُمَّ قَدِمَ مَكَّةَ مِنَ الطَّوَافِ وَالسَّعْىِ","28"],[209,"Chapter: Clarifying that the pilgrim who has entered Ihram for Umrah should not exit Ihram after performing Tawaf before Sa'i; And the pilgrim who has entered Ihram for Hajj should not exit Ihram after performing Tawaf Al-Qudum, and the same applies to the pilgrim performing Qiran","باب مَا يَلْزَمُ مَنْ طَافَ بِالْبَيْتِ وَسَعَى مِنَ الْبَقَاءِ عَلَى الإِحْرَامِ وَتَرْكِ التَّحَلُّلِ","29"],[213,"Chapter: Tamattu' in Hajj","باب فِي مُتْعَةِ الْحَجِّ","30"],[217,"Chapter: It is permissible to perform 'Umrah during the months of Hajj","باب جَوَازِ الْعُمْرَةِ فِي أَشْهُرِ الْحَجِّ","31"],[224,"Chapter: Marking and Garlanding the sacrificial animal when entering Ihram","باب تَقْلِيدِ الْهَدْىِ وَإِشْعَارِهِ عِنْدَ الإِحْرَامِ","32"],[229,"Chapter: It is permissible for the pilgrim performing Umrah to shorten his hair and he does not have to shave it. It is recommended for him to shave his hair or shorten it at Al-Marwah","باب التَّقْصِيرِ فِي الْعُمْرَةِ","33"],[234,"Chapter: The Ihram and Hadi of the Prophet (saws)","باب إِهْلاَلِ النَّبِيِّ صلى الله عليه وسلم وَهَدْيِهِ","34"],[239,"Chapter: The number of Umrahs performed by the prophet (saws) and when he performed them","باب بَيَانِ عَدَدِ عُمَرِ النَّبِيِّ صلى الله عليه وسلم وَزَمَانِهِنَّ","35"],[244,"Chapter: The virtue of the Umrah performed during Ramadan","باب فَضْلِ الْعُمْرَةِ فِي رَمَضَانَ","36"],[246,"Chapter: It is recommended to enter Makkah from the Upper Mountain Pass and to leave from the Lower Mountain Pass; Entering a city via a route different than the one by which you leave it","باب اسْتِحْبَابِ دُخُولِ مَكَّةَ مِنَ الثَّنِيَّةِ الْعُلْيَا وَالْخُرُوجِ مِنْهَا مِنَ الثَّنِيَّةِ السُّفْلَى وَدُخُولِ بَلْدَةٍ مِنْ طَرِيقٍ غَيْرِ الَّتِي خَرَجَ مِنْهَا","37"],[250,"Chapter: It is recommended to stay overnight in Dhu Tuwa when intending to enter Makkah, and to perform Ghusl before entering it, and to enter it by day","باب اسْتِحْبَابِ الْمَبِيتِ بِذِي طَوًى عِنْدَ إِرَادَةِ دُخُولِ مَكَّةَ وَالاِغْتِسَالِ لِدُخُولِهَا نَهَارًا","38"],[254,"Chapter: Raml (walking rapidly) is recommended in the Tawaf of Umrah, and in the first Tawaf of Hajj","باب اسْتِحْبَابِ الرَّمَلِ فِي الطَّوَافِ وَالْعُمْرَةِ وَفِي الطَّوَافِ الأَوَّلِ فِي الْحَجِّ","39"],[267,"Chapter: It is recommended to touch the two Yemeni Corners in Tawaf and not the other two corners","باب اسْتِحْبَابِ اسْتِلاَمِ الرُّكْنَيْنِ الْيَمَانِيَيْنِ فِي الطَّوَافِ دُونَ الرُّكْنَيْنِ الآخَرَيْن","40"],[273,"Chapter: It is recommended to kiss the black stone during circumambulation (Tawaf)","باب اسْتِحْبَابِ تَقْبِيلِ الْحَجَرِ الأَسْوَدِ فِي الطَّوَافِ","41"],[279,"Chapter: It is permissible to circumambulate the Ka'bah on a camel and the like, And for one who is riding to touch the (black) stone with a crooked staff and the like.","باب جَوَازِ الطَّوَافِ عَلَى بَعِيرٍ وَغَيْرِهِ وَاسْتِلاَمِ الْحَجَرِ بِمِحْجَنٍ وَنَحْوِهِ لِلرَّاكِبِ","42"],[285,"Chapter: Clarifying that Sa'i between As-safa and Al-Marwah is a pillar of Hajj, without which Hajj is not valid","باب بَيَانِ أَنَّ السَّعْىَ بَيْنَ الصَّفَا وَالْمَرْوَةِ رُكْنٌ لاَ يَصِحُّ الْحَجُّ إِلاَّ بِهِ","43"],[291,"Chapter: Clarifying that Sa'i should not be repeated","باب بَيَانِ أَنَّ السَّعْىَ لاَ يُكَرَّرُ","44"],[293,"Chapter: It is recommended for the pilgrim to continue reciting the Talbiyah until he starts stoning Jamrat Al-'Aqabah on the day of sacrifice","باب اسْتِحْبَابِ إِدَامَةِ الْحَاجِّ التَّلْبِيَةَ حَتَّى يَشْرَعَ فِي رَمْىِ جَمْرَةِ الْعَقَبَةِ يَوْمَ النَّحْرِ","45"],[300,"Chapter: The Talbiyah and the Takbir when going from Mina to 'Arafat on the day of 'Arafat","باب التَّلْبِيَةِ وَالتَّكْبِيرِ فِي الذِّهَابِ مِنْ مِنًى إِلَى عَرَفَاتٍ فِي يَوْمِ عَرَفَةَ","46"],[304,"Chapter: Departing from 'Arafat to Al-Muzdalifah. It is recommended to pray Maghrib and 'Isha together in Al-Muzdalifah on this night","باب الإِفَاضَةِ مِنْ عَرَفَاتٍ إِلَى الْمُزْدَلِفَةِ وَاسْتِحْبَابِ صَلاَتَىِ الْمَغْرِبِ وَالْعِشَاءِ جَمْعًا بِالْمُزْدَلِفَةِ فِي هَذِهِ اللَّيْلَةِ","47"],[320,"Chapter: It is recommended to pray Subh when it is still dark on the day of sacrifice in Al-Muzdalifah, and to do it very early after ascertaining that dawn has broken","باب اسْتِحْبَابِ زِيَادَةِ التَّغْلِيسِ بِصَلاَةِ الصُّبْحِ يَوْمَ النَّحْرِ بِالْمُزْدَلِفَةِ وَالْمُبَالَغَةِ فِيهِ بَعْدَ تَحَقُّقِ طُلُوعِ الْفَجْرِ","48"],[322,"Chapter: It is recommended to send the weak among women and others ahead from Al-Muzdalifah to Mina at the end of the night, before it gets crowded, but it is recommended for others to stay there until they have prayed Subh in Al-Muzdalifah","باب اسْتِحْبَابِ تَقْدِيمِ دَفْعِ الضَّعَفَةِ مِنَ النِّسَاءِ وَغَيْرِهِنَّ مِنْ مُزْدَلِفَةَ إِلَى مِنًى فِي أَوَاخِرِ اللَّيَالِي قَبْلَ زَحْمَةِ النَّاسِ وَاسْتِحْبَابِ الْمُكْثِ لِغَيْرِهِمْ حَتَّى يُصَلُّوا الصُّبْحَ بِمُزْدَلِفَةَ","49"],[335,"Chapter: Stoning Jamrat Al-'Aqabah from the bottom of the valley; Makkah should be on to one's left and one should say Takbir with each throw","باب رَمْىِ جَمْرَةِ الْعَقَبَةِ مِنْ بَطْنِ الْوَادِي وَتَكُونُ مَكَّةُ عَنْ يَسَارِهِ وَيُكَبِّرُ مَعَ كُلِّ حَصَاةٍ","50"],[341,"Chapter: It is recommended to stone Jamrat Al-'Aqabah, on the day of sacrifice, riding, and the prophet saws said: \"Learn your rituals (of Hajj) from me\"","باب اسْتِحْبَابِ رَمْىِ جَمْرَةِ الْعَقَبَةِ يَوْمَ النَّحْرِ رَاكِبًا وَبَيَانِ قَوْلِهِ صَلَّى اللَّهُ تَعَالَى عَلَيْهِ وَسَلَّمَ: «لِتَأْخُذُوا مَنَاسِكَكُمْ»","51"],[344,"Chapter: It is recommended for the pebbles used for stoning to be the size of broad beans","باب اسْتِحْبَابِ كَوْنِ حَصَى الْجِمَارِ بِقَدْرِ حَصَى الْخَذْفِ","52"],[345,"Chapter: The time when it is recommended to stone the Jamrah","باب بَيَانِ وَقْتِ اسْتِحْبَابِ الرَّمْىِ","53"],[347,"Chapter: The number of pebbles for stoning the Jamrahs is seven at a time","باب بَيَانِ أَنَّ حَصَى الْجِمَارِ سَبْعٌ","54"],[348,"Chapter: Shaving the head is preferrable to cutting the hair, although cutting the hair is permissible","باب تَفْضِيلِ الْحَلْقِ عَلَى التَّقْصِيرِ وَجَوَازِ التَّقْصِيرِ","55"],[356,"Chapter: The Sunnah on the day of sacrifice is to stone the Jamrah, then offer the sacrifice, then shave the head, and shaving should be started on the right side of the head","باب بَيَانِ أَنَّ السُّنَّةَ يَوْمَ النَّحْرِ أَنْ يَرْمِيَ ثُمَّ يَنْحَرَ ثُمَّ يَحْلِقَ وَالاِبْتِدَاءِ فِي الْحَلْقِ بِالْجَانِبِ الأَيْمَنِ مِنْ رَأْسِ الْمَحْلُوقِ","56"],[360,"Chapter: It is permissible to offer the sacrifice before stoning the Jamrah, or to shave before offering the sacrifice or stoning the Jamrah, or to perform Tawaf before any of them","باب مَنْ حَلَقَ قَبْلَ النَّحْرِ أَوْ نَحَرَ قَبْلَ الرَّمْىِ","57"],[369,"Chapter: It is recommended to perform Tawaf Al-Ifadah on the day of sacrifice","باب اسْتِحْبَابِ طَوَافِ الإِفَاضَةِ يَوْمَ النَّحْرِ","58"],[371,"Chapter: It is recommended to halt at Al-Muhassab on the day of departing from Mina and to perform Zuhr and subsequent prayers there","باب اسْتِحْبَابِ النُّزُولِ بِالْمُحَصَّبِ يَوْمَ النَّفْرِ وَالصَّلاَةِ بِهِ","59"],[381,"Chapter: It is obligatory to stay overnight in Mina during the nights of the days of At-Tashriq, and the concession allowing those who supply water to leave","باب وُجُوبِ الْمَبِيتِ بِمِنًى لَيَالِيَ أَيَّامِ التَّشْرِيقِ وَالتَّرْخِيصِ فِي تَرْكِهِ لأَهْلِ السِّقَايَةِ","60"],[384,"Chapter: Giving the meat, skin and blankets of the Hadi in charity; the butcher should not be given any of it; It is permissible to delegate someone else to offer the sacrifice","باب فِي الصَّدَقَةِ بِلُحُومِ الْهَدْىِ وَجُلُودِهَا وَجِلاَلِهَا","61"],[389,"Chapter: It is permissible to share in the sacrifice, and a camel or a cow is sufficient for seven people","باب الاِشْتِرَاكِ فِي الْهَدْىِ وَإِجْزَاءِ الْبَقَرَةِ وَالْبَدَنَةِ كُلٍّ مِنْهُمَا عَنْ سَبْعَةٍ","62"],[397,"Chapter: It is recommended to sacrifice the camel when it is standing and tied","باب نَحْرِ الْبُدْنِ قِيَامًا مُقَيَّدَةً","63"],[398,"Chapter: It is recommended to send the sacrificial animal to the Haram for one who does not intend to go there himself; It is reommended to garland it and to make the garland, but the one who sends it does not enter a state of Ihram, and nothing is forbidden to him because of that","باب اسْتِحْبَابِ بَعْثِ الْهَدْىِ إِلَى الْحَرَمِ لِمَنْ لاَ يُرِيدُ الذَّهَابَ بِنَفْسِهِ وَاسْتِحْبَابِ تَقْلِيدِهِ وَفَتْلِ الْقَلاَئِدِ وَأَنَّ بَاعِثَهُ لاَ يَصِيرُ مُحْرِمًا وَلاَ يَحْرُمُ عَلَيْهِ شيء بِذَلِكَ","64"],[412,"Chapter: It is permissible to ride the sacrificial animal if necessary","باب جَوَازِ رُكُوبِ الْبَدَنَةِ الْمُهْدَاةِ لِمَنِ احْتَاجَ إِلَيْهَا","65"],[420,"Chapter: What should be done with the sacrificial animal if it gets injured on the way?","باب مَا يُفْعَلُ بِالْهَدْىِ إِذَا عَطِبَ فِي الطَّرِيقِ","66"],[423,"Chapter: The farewell Tawaf is obligatory, but it is waived in the case of menstruating women","باب وُجُوبِ طَوَافِ الْوَدَاعِ وَسُقُوطِهِ عَنِ الْحَائِضِ","67"],[434,"Chapter: It is recommended for pilgrims and others to enter the Ka'bah and pray therein, and supplicate in all its corners","باب اسْتِحْبَابِ دُخُولِ الْكَعْبَةِ لِلْحَاجِّ وَغَيْرِهِ وَالصَّلاَةِ فِيهَا وَالدُّعَاءِ فِي نَوَاحِيهَا كُلِّهَا","68"],[444,"Chapter: Demolishing the Ka'bah and rebuilding it","باب نَقْضِ الْكَعْبَةِ وَبِنَائِهَا","69"],[453,"Chapter: The wall and the door of the Ka'bah","باب جَدْرِ الْكَعْبَةِ وَبَابِهَا","70"],[455,"Chapter: Hajj on behalf of one who is incapable of doing it because of chronic illness, old age and the like, or on behalf of one who has died","باب الْحَجِّ عَنِ الْعَاجِزِ، لِزَمَانَةٍ وَهِرَمٍ وَنَحْوِهِمَا أَوْ لِلْمَوْتِ","71"],[457,"Chapter: Validity of a child's hajj, and the reward of the one who takes him for Hajj","باب صِحَّةِ حَجِّ الصَّبِيِّ وَأَجْرِ مَنْ حَجَّ بِهِ","72"],[461,"Chapter: Hajj is obligatory once in a lifetime","باب فَرْضِ الْحَجِّ مَرَّةً فِي الْعُمْرِ","73"],[462,"Chapter: A woman travelling with a Mahram for Hajj and other purposes","باب سَفَرِ الْمَرْأَةِ مَعَ مَحْرَمٍ إِلَى حَجٍّ وَغَيْرِهِ","74"],[479,"Chapter: It is recommended to recite statements of remembrance when setting out for Hajj or any other purpose, and the best of this remembrances","باب مَا يَقُولُ إِذَا رَكِبَ إِلَى سَفَرٍ الْحَجِّ وَغَيْرِهِ","75"],[482,"Chapter: What should be said when returning from Hajj and other journeys","باب مَا يَقُولُ إِذَا قَفَلَ مِنْ سَفَرٍ الْحَجِّ وَغَيْرِهِ","76"],[486,"Chapter: It is recommended to stop in Batha' of Dhul-Hulaifah and pray there when departing from Hajj and 'Umrah, or any time one passes through it","باب التَّعْرِيسِ بِذِي الْحُلَيْفَةِ وَالصَّلاَةِ بِهَا إِذَا صَدَرَ مِنَ الْحَجِّ أَوِ الْعُمْرَةِ","77"],[491,"Chapter: No idolator may circumambulate the house, and no one may circumambulate the house naked, and when the greatest day of Hajj is","باب لاَ يَحُجُّ الْبَيْتَ مُشْرِكٌ وَلاَ يَطُوفُ بِالْبَيْتِ عُرْيَانٌ وَبَيَانُ يَوْمِ الْحَجِّ الأَكْبَبَرِ","78"],[492,"Chapter: The virtue of the day of 'Arafat","باب فِي فَضْلِ الْحَجِّ وَالْعُمْرَةِ وَيَوْمِ عَرَفَةَ","79"],[498,"Chapter: Pilgrims staying in Makkah, and Inheriting its houses","باب النُّزُولِ بِمَكَّةَ لِلْحَاجِّ وَتَوْرِيثِ دُورِهَا","80"],[501,"Chapter: It is permissible for the one who emigrated from Makkah to stay there for three days after completing Hajj and 'Umrah, and no more than that","باب جَوَازِ الإِقَامَةِ بِمَكَّةَ لِلْمُهَاجِرِ مِنْهَا بَعْدَ فَرَاغِ الْحَجِّ وَالْعُمْرَةِ ثَلاَثَةَ أَيَّامٍ بِلاَ زِيَادَةٍ","81"],[506,"Chapter: The sanctity of Makkah and the sanctity of its game, grasses, trees and lost property, except for the one who announces it, is forever","باب تَحْرِيمِ مَكَّةَ وَصَيْدِهَا وَخَلاَهَا وَشَجَرِهَا وَلُقَطَتِهَا إِلاَّ لِمُنْشِدٍ عَلَى الدَّوَام","82"],[511,"Chapter: The prohibition of carrying weapons in Makkah when there is no need for that","باب النَّهْىِ عَنْ حَمْلِ السِّلاَحِ، بِمَكَّةَ بِلاَ حَاجَةٍ","83"],[512,"Chapter: It is permissible to enter Makkah without Ihram","باب جَوَازِ دُخُولِ مَكَّةَ بِغَيْرِ إِحْرَامٍ","84"],[517,"Chapter: The virtue of Al-Madinah and the Prophet's Prayer for it to be blessed. Its sanctity and the sanctity of its game and trees. The Boundaries of its sanctuary","باب فَضْلِ الْمَدِينَةِ وَدُعَاءِ النَّبِيِّ صلى الله عليه وسلم فِيهَا بِالْبَرَكَةِ وَبَيَانِ تَحْرِيمِها وَتَحْرِيمِ صَيْدِهَا وَشَجَرِهَا وَبَيَانِ حُدُودِ حَرَمِهَا","85"],[540,"Chapter: Encouragement to live in Al-Madinah and to be patient on bearing its distress and hardships","باب التَّرْغِيبِ فِي سُكْنَى الْمَدِينَةِ وَالصَّبْرِ عَلَى لأْوَائِهَا","86"],[554,"Chapter: Al-Madinah is protected against the plague and the Dajjal entering it","باب صِيَانَةِ الْمَدِينَةِ مِنْ دُخُولِ الطَّاعُونِ وَالدَّجَّالِ إِلَيْهَا","87"],[556,"Chapter: Al-Madinah eliminates its Dross and it is also called Tabah, and Taibah","باب الْمَدِينَةِ تَنْفِي شِرَارَهَا","88"],[562,"Chapter: The prohibition of wishing ill towards the people of Al-Madinah, and that the one who wishes them ill will be caused to melt by Allah","باب مَنْ أَرَادَ أَهْلَ الْمَدِينَةِ بِسُوءٍ أَذَابَهُ اللَّهُ","89"],[568,"Chapter: Encouraging people to stay in Al-Madinah when the regions were conquered","باب التَّرْغِيبِ فِي الْمَدِينَةِ عِنْدَ فَتْحِ الأَمْصَارِ","90"],[570,"Chapter: The Prophet saws foretold that the people will abandon Al-Madinah when it is the best it ever was","باب فِي الْمَدِينَةِ حِينَ يَتْرُكُهَا أَهْلُهَا","91"],[572,"Chapter: The virtue of the area between the prophet's grave and his Minbar, and the virtue of the spot where his minbar is","باب مَا بَيْنَ الْقَبْرِ وَالْمِنْبَرِ رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ","92"],[575,"Chapter: The virtue of Uhud","باب أُحُدٌ جَبَلٌ يُحِبُّنَا وَنُحِبُّهُ","93"],[578,"Chapter: The virtue of praying in the Masajid of Makkah and Al-Madinah","باب فَضْلِ الصَّلاَةِ بِمَسْجِدَىْ مَكَّةَ وَالْمَدِينَةِ","94"],[588,"Chapter: The virtue of the Three Masajid","باب لاَ تُشَدُّ الرِّحَالُ إِلاَّ إِلَى ثَلاَثَةِ مَسَاجِدَ","95"],[591,"Chapter: The Masjid whose foundation was founded upon piety is the Masjid of the Prophet saws in Al-Madinah","باب بَيَانِ أَنَّ الْمَسْجِدَ الَّذِي أُسِّسَ عَلَى التَّقْوَى هُوَ مَسْجِدُ النَّبِيِّ صلى الله عليه وسلم بِالْمَدِينَةِ","96"],[593,"Chapter: The virtue of the Masjid of Quba', and the virtue of praying therein and visiting it","باب فَضْلِ مَسْجِدِ قُبَاءٍ وَفَضْلِ الصَّلاَةِ فِيهِ وَزِيَارَتِهِ","97"]],"16":[[1,"Chapter: Marriage is recommended for the one who desires it and can afford it, and the one who cannot afford it should distract himself by fasting","باب اسْتِحْبَابِ النِّكَاحِ لِمَنْ تَاقَتْ نَفْسُهُ إِلَيْهِ وَوَجَدَ مُؤْنَةً وَاشْتِغَالِ مَنْ عَجَزَ عَنِ الْمُؤَنِ بِالصَّوْمِ","1"],[10,"Chapter: Recommendation to the one who sees a woman and is attracted to her, to go to his wife or slave woman and have intercourse with her","باب نَدْبِ مَنْ رَأَى امْرَأَةً فَوَقَعَتْ فِي نَفْسِهِ إِلَى أَنْ يَأْتِيَ امْرَأَتَهُ أَوْ جَارِيَتَهُ فَيُوَاقِعَهَا","2"],[13,"Chapter: Mut'ah Marriage: It was permitted then abrograted, then permitted then abrogated, and it will remain Forbidden until the day of resurrection","باب نِكَاحِ الْمُتْعَةِ وَبَيَانِ أَنَّهُ أُبِيحَ ثُمَّ نُسِخَ ثُمَّ أُبِيحَ ثُمَّ نُسِخَ وَاسْتَقَرَّ تَحْرِيمُهُ إِلَى يَوْمِ الْقِيَامَةِ","3"],[39,"Chapter: The prohibition of being married to a woman and her paternal aunt or maternal aunt at the same time","باب تَحْرِيمِ الْجَمْعِ بَيْنَ الْمَرْأَةِ وَعَمَّتِهَا أَوْ خَالَتِهَا فِي النِّكَاحِ","4"],[49,"Chapter: The prohibition of marriage for one who is in Ihram, and it is disliked for him to propose marriage","باب تَحْرِيمِ نِكَاحِ الْمُحْرِمِ وَكَرَاهَةِ خِطْبَتِهِ","5"],[57,"Chapter: The prohibition of proposing marriage when one's brother has already proposed, unless he gives permission or gives up the idea","باب تَحْرِيمِ الْخِطْبَةِ عَلَى خِطْبَةِ أَخِيهِ حَتَّى يَأْذَنَ أَوْ يَتْرُكَ","6"],[67,"Chapter: Prohibition and invalidity of Shighar Marriage","باب تَحْرِيمِ نِكَاحِ الشِّغَارِ وَبُطْلاَنِهِ","7"],[74,"Chapter: Fulfilling the conditions stipulated in the Marriage","باب الْوَفَاءِ بِالشُّرُوطِ فِي النِّكَاحِ","8"],[75,"Chapter: Seeking permission of a previously-married woman in words, and of a virgin by silence","باب اسْتِئْذَانِ الثَّيِّبِ فِي النِّكَاحِ بِالنُّطْقِ وَالْبِكْرِ بِالسُّكُوتِ","9"],[81,"Chapter: It is permissible for a father to arrange the marriage of a young virgin","باب تَزْوِيجِ الأَبِ الْبِكْرَ الصَّغِيرَةَ","10"],[85,"Chapter: It is recommended to get married and arrange marriages in Shawwal, and it is recommended to consummate the marriage in that month","باب اسْتِحْبَابِ التَّزَوُّجِ وَالتَّزْوِيجِ فِي شَوَّالٍ وَاسْتِحْبَابِ الدُّخُولِ فِيهِ","11"],[87,"Chapter: It is recommended for the one who wants to marry a woman to look at her face and hands before proposing marriage to her","باب نَدْبِ النَّظَرِ إِلَى وَجْهِ الْمَرْأَةِ وَكَفَّيْهَا لِمَنْ يُرِيدُ تَزَوُّجَهَا","12"],[89,"Chapter: The Dowry. It is permissible for the dowry to be teaching Quran, a ring of iron or anything else, a small or large amount, And it is recommended for it to be Five Hundred Dirham","باب الصَّدَاقِ وَجَوَازِ كَوْنِهِ تَعْلِيمَ قُرْآنٍ وَخَاتَمَ حَدِيدٍ وَغَيْرَ ذَلِكَ مِنْ قَلِيلٍ وَكَثِيرٍ وَاسْتِحْبَابِ كَوْنِهِ خَمْسَمِائَةِ دِرْهَمٍ لِمَنْ لاَ يُجْحَفُ بِهِ","13"],[99,"Chapter: The virute of manumitting one's slave girl, then marrying her","باب فَضِيلَةِ إِعْتَاقِهِ أَمَتَهُ ثُمَّ يَتَزَوَّجُهَا","14"],[105,"Chapter: The Marriage of Zainab Bint Jahsh, The Revelation of (the verse of) Hijab, and confirmation of the importance of the wedding feast.","باب زَوَاجِ زَيْنَبَ بِنْتِ جَحْشٍ وَنُزُولِ الْحِجَابِ وَإِثْبَاتِ وَلِيمَةِ الْعُرْسِ","15"],[112,"Chapter: The command to accept invitations","باب الأَمْرِ بِإِجَابَةِ الدَّاعِي إِلَى دَعْوَةٍ","16"],[128,"Chapter: It is not permissible for a woman who has been thrice-divorced to return to the one who divorced her until she marries another husband who has intercourse with her, then divorces her, and she completes the 'Iddah","باب لاَ تَحِلُّ الْمُطَلَّقَةُ ثَلاَثًا لِمُطَلِّقِهَا حَتَّى تَنْكِحَ زَوْجًا غَيْرَهُ وَيَطَأَهَا ثُمَّ يُفَارِقَهَا وَتَنْقَضِي عِدَّتُهَا","17"],[135,"Chapter: What it is recommended to say when having intercourse","باب مَا يُسْتَحَبُّ أَنْ يَقُولَهُ عِنْدَ الْجِمَاعِ","18"],[137,"Chapter: It is permissible for a man to have intercourse with his wife from the front or from the back, without entering the behind","باب جَوَازِ جِمَاعِهِ امْرَأَتَهُ فِي قُبُلِهَا مِنْ قُدَّامِهَا وَمِنْ وَرَائِهَا مِنْ غَيْرِ تَعَرُّضٍ لِلدُّبُرِ","19"],[140,"Chapter: It is unlawful for the wife to refuse to come to her husband's bed","باب تَحْرِيمِ امْتِنَاعِهَا مِنْ فِرَاشِ زَوْجِهَا","20"],[144,"Chapter: The prohibition of disclosing a woman's secrets","باب تَحْرِيمِ إِفْشَاءِ سِرِّ الْمَرْأَةِ","21"],[146,"Chapter: The ruling on coitus interrupts ('Azl)","باب حُكْمِ الْعَزْلِ","22"],[164,"Chapter: The prohibition of intercourse with a pregnant captive woman","باب تَحْرِيمِ وَطْءِ الْحَامِلِ الْمَسْبِيَّةِ","23"],[166,"Chapter: It is permissible to have intercourse with a breastfeeding woman (Ghilah), and 'Azl is disliked","باب جَوَازِ الْغِيلَةِ وَهِيَ وَطْءُ الْمُرْضِعِ وَكَرَاهَةِ الْعَزْلِ","24"]],"17":[[1,"Chapter: \"Breastfeeding Makes Unlawful What Birth Makes Unlawful.\"","باب يَحْرُمُ مِنَ الرَّضَاعَةِ مَا يَحْرُمُ مِنَ الْوِلاَدَةِ","1"],[4,"Chapter: The prohibition that results from breastfeeding is related to the issue of the male","باب تَحْرِيمِ الرَّضَاعَةِ مِنْ مَاءِ الْفَحْلِ","2"],[14,"Chapter: The daughter of one's brother through breastfeeding is forbidden in marriage","باب تَحْرِيمِ ابْنَةِ الأَخِ مِنَ الرَّضَاعَةِ","3"],[19,"Chapter: The prohibition of marriage to one's stepdaughter and the sister of one's wife","باب تَحْرِيمِ الرَّبِيبَةِ وَأُخْتِ الْمَرْأَةِ","4"],[23,"Chapter: One or Two sucks","باب فِي الْمَصَّةِ وَالْمَصَّتَيْنِ","5"],[30,"Chapter: Becoming Mahram is established by Five Breastfeedings","باب التَّحْرِيمِ بِخَمْسِ رَضَعَاتٍ","6"],[33,"Chapter: Breastfeeding an adult","باب رَضَاعَةِ الْكَبِيرِ","7"],[39,"Chapter: Breastfeeding is because of Hunger (meaning, during infancy)","باب إِنَّمَا الرَّضَاعَةُ مِنَ الْمَجَاعَةِ","8"],[41,"Chapter: It is permissible to have intercourse with a female captive after it is established that she is not pregnant, and if she has a husband, then her marriage is annulled when she is captured","باب جَوَازِ وَطْءِ الْمَسْبِيَّةِ بَعْدَ الاِسْتِبْرَاءِ وَإِنْ كَانَ لَهَا زَوْجٌ انْفَسَخَ نِكَاحُهَا بِالسَّبْي","9"],[46,"Chapter: The child is for the bed and suspicion must be avoided","باب الْوَلَدِ لِلْفِرَاشِ وَتَوَقِّي الشُّبُهَاتِ","10"],[50,"Chapter: Detecting relationships from physical features","باب الْعَمَلِ بِإِلْحَاقِ الْقَائِفِ الْوَلَدَ","11"],[54,"Chapter: How long a virgin and a previously-married woman are entitled to have the husband stay with them after marriage","باب قَدْرِ مَا تَسْتَحِقُّهُ الْبِكْرُ وَالثَّيِّبُ مِنْ إِقَامَةِ الزَّوْجِ عِنْدَهَا عَقِبَ الزِّفَافِ","12"],[61,"Chapter: Dividing one's time among co-wives; The Sunnah is for each one to have one night and one day","باب الْقَسْمِ بَيْنَ الزَّوْجَاتِ وَبَيَانِ أَنَّ السُّنَّةَ أَنْ تَكُونَ لِكُلِّ وَاحِدَةٍ لَيْلَةٌ مَعَ يَوْمِهَا","13"],[62,"Chapter: It is permissible for a wife to give her turn to a co-wife","باب جَوَازِ هِبَتِهَا نَوْبَتَهَا لِضَرَّتِهَا","14"],[68,"Chapter: It is recommended to marry one who is religiously committed","باب اسْتِحْبَابِ نِكَاحِ ذَاتِ الدِّينِ","15"],[70,"Chapter: It is recommended to marry virgins","باب اسْتِحْبَابِ نِكَاحِ الْبِكْرِ","16"],[76,"Chapter: The best temporary joy of this world is a righteous woman","باب خَيْرُ مَتَاعِ الدُّنْيَا الْمَرْأَةُ الصَّالِحَةُ","17"],[77,"Chapter: Advice with regard to women","باب الْوَصِيَّةِ بِالنِّسَاءِ","18"],[83,"Chapter: Were it not for Hawa', no female would ever betray her husband","باب لَوْلاَ حَوَّاءُ لَمْ تَخُنْ أُنْثَى زَوْجَهَا الدَّهْرَ","19"]],"18":[[1,"Chapter: The prohibition of divorcing a menstruating woman without her consent; If a man breaks this rule, it still counts as a divorce, and he should be ordered to take her back","باب تَحْرِيمِ طَلاَقِ الْحَائِضِ بِغَيْرِ رِضَاهَا وَأَنَّهُ لَوْ خَالَفَ وَقَعَ الطَّلاَقُ وَيُؤْمَرُ بِجْعَتِهَا","1"],[22,"Chapter: Threefold Divorce","باب طَلاَقِ الثَّلاَثِ","2"],[25,"Chapter: Expiation must be offered by one who declares his wife to be unlawful for him but does not intend divorce thereby","باب وُجُوبِ الْكَفَّارَةِ عَلَى مَنْ حَرَّمَ امْرَأَتَهُ وَلَمْ يَنْوِ الطَّلاَقَ","3"],[30,"Chapter: Giving one's wife the choice does not count as a divorce, unless it is intended as such","باب بَيَانِ أَنَّ تَخْيِيرَ امْرَأَتِهِ لاَ يَكُونُ طَلاَقًا إِلاَّ بِالنِّيَّةِ","4"],[40,"Chapter: Ila', Keeping away from one's wives and giving them the choice, And the saying of Allah, The Most High: \"But if you help one another against him","باب فِي الإِيلاَءِ وَاعْتِزَالِ النِّسَاءِ وَتَخْيِيرِهِنَّ وَقَوْلِهِ تَعَالَى: {وَإِنْ تَظَاهَرَا عَلَيْهِ}","5"],[45,"Chapter: The woman who has been irrevocably divorced is not entitled to spending","باب الْمُطَلَّقَةُ ثَلاَثًا لاَ نَفَقَةَ لَهَا","6"],[69,"Chapter: It is permissible for a woman who is observing 'Iddah after an irrevocable divorce or the death of her husband to go out during the day if she needs to","باب جَوَازِ خُرُوجِ الْمُعْتَدَّةِ الْبَائِنِ وَالْمُتَوَفَّى عَنْهَا زَوْجُهَا فِي النَّهَارِ لِحَاجَتِهَا","7"],[70,"Chapter: The 'Iddah of a woman whose husband had died, and the like, ends when she gives birth.","باب انْقِضَاءِ عِدَّةِ الْمُتَوَفَّى عَنْهَا زَوْجُهَا وَغَيْرِهَا بِوَضْعِ الْحَمْلِ","8"],[73,"Chapter: The Obligation to mourn during the 'Iddah following the death of one's husband, but it is forbidden to mourn for more than three days in other cases","باب وُجُوبِ الإِحْدَادِ فِي عِدَّةِ الْوَفَاةِ وَتَحْرِيمِهِ فِي غَيْرِ ذَلِكَ إِلاَّ ثَلاَثَةَ أَيَّامٍ","9"]],"19":[[1,"","باب","1"]],"20":[[1,"Chapter: One who frees his share of a slave","باب مَنْ أَعْتَقَ شِرْكًا لَهُ فِي عَبْدٍ","1"],[3,"Chapter: A slave working to pay off the other half","باب ذِكْرِ سِعَايَةِ الْعَبْدِ","2"],[7,"Chapter: Al-Wala' (Right of inheritance) belongs to the one who manumits the slave","باب إِنَّمَا الْوَلاَءُ لِمَنْ أَعْتَقَ","3"],[19,"Chapter: The prohibition of selling or giving away the wala'","باب النَّهْىِ عَنْ بَيْعِ الْوَلاَءِ، وَهِبَتِهِ،","4"],[21,"Chapter: The prohibition of a manumitted slave taking anyone as a Mawla except the one who manumitted him","باب تَحْرِيمِ تَوَلِّي الْعَتِيقِ غَيْرَ مَوَالِيهِ","5"],[25,"Chapter: The virtue of manumitting slaves","باب فَضْلِ الْعِتْقِ","6"],[29,"Chapter: The virtue of manumitting one's father","باب فَضْلِ عِتْقِ الْوَالِدِ","7"]],"21":[[1,"Chapter: The invalidity of Mulamasah and Munabadhah transactions","باب إِبْطَالِ بَيْعِ الْمُلاَمَسَةِ وَالْمُنَابَذَةِ","1"],[8,"Chapter: The invalidity of Hasah transactions and transactions involving ambiguity","باب بُطْلاَنِ بَيْعِ الْحَصَاةِ وَالْبَيْعِ الَّذِي فِيهِ غَرَرٌ","2"],[9,"Chapter: The prohibition of selling Habl Al-Habalah","باب تَحْرِيمِ بَيْعِ حَبَلِ الْحَبَلَةِ","3"],[11,"Chapter: The prohibition of urging a buyer to cancel a purchase in order to sell him one's own goods; And urging a seller to cancel a sale already agreed upon so that one can buy the goods oneself; And the prohibition of artificially inflating prices; And the prohibition of letting milk accumulate in the udder in order to deceive the purchaser","باب تَحْرِيمِ بَيْعِ الرَّجُلِ عَلَى بَيْعِ أَخِيهِ وَسَوْمِهِ عَلَى سَوْمِهِ وَتَحْرِيمِ النَّجْشِ وَتَحْرِيمِ التَّصْرِيَةِ","4"],[19,"Chapter: The prohibition of intercepting traders","باب تَحْرِيمِ تَلَقِّي الْجَلَبِ","5"],[24,"Chapter: The prohibition of the town-dweller selling on behalf of a bedouin","باب تَحْرِيمِ بَيْعِ الْحَاضِرِ لِلْبَادِي","6"],[30,"Chapter: Ruling on selling Al-Musarrah (An animal in whose udder milk has been allowed to accumulate)","باب حُكْمِ بَيْعِ الْمُصَرَّاةِ","7"],[36,"Chapter: It is invalid to sell goods before taking possession of them","باب بُطْلاَنِ بَيْعِ الْمَبِيعِ قَبْلَ الْقَبْضِ","8"],[50,"Chapter: The prohibition of selling a heap of dates the weight of which is unknown","باب تَحْرِيمِ بَيْعِ صُبْرَةِ التَّمْرِ الْمَجْهُولَةِ الْقَدْرِ بِتَمْرٍ","9"],[52,"Chapter: Affirming that both parties to a transaction have the option (of canceling it) while they are still together","باب ثُبُوتِ خِيَارِ الْمَجْلِسِ لِلْمُتَبَايِعَيْنِ","10"],[57,"Chapter: Honesty in selling and disclosure of defects","باب الصِّدْقِ فِي الْبَيْعِ وَالْبَيَانِ","11"],[59,"Chapter: One who is deceived in transactions","باب مَنْ يُخْدَعُ فِي الْبَيْعِ","12"],[61,"Chapter: The prohibition of selling produce before its goodness appears","باب النَّهْىِ عَنْ بَيْعِ الثِّمَارِ، قَبْلَ بُدُوِّ صَلاَحِهَا بِغَيْرِ شَرْطِ الْقَطْعِ","13"],[77,"Chapter: The prohibition of selling fresh dates in exchange for dry dates except in the case of 'Araya","باب تَحْرِيمِ بَيْعِ الرُّطَبِ بِالتَّمْرِ إِلاَّ فِي الْعَرَايَا","14"],[100,"Chapter: One who sells date palms on which there are dates","باب مَنْ بَاعَ نَخْلاً عَلَيْهَا ثَمَرٌ","15"],[107,"Chapter: The prohibition of Muhaqalah and Muzabanah and Mukhabarah: and selling produce before its goodness appears, and Mu'awamah: which is selling years in advance","باب النَّهْيِ عَنِ الْمُحَاقَلَةِ وَالْمُزَابَنَةِ وَعَنِ الْمُخَابَرَةِ وَبَيْعِ الثَّمَرَةِ قَبْلَ بُدُوِّ صَلاَحِهَا وَعَنْ بَيْعِ الْمُعَاوَمَةِ وَهُوَ بَيْعُ السِّنِينَ","16"],[115,"Chapter: Kira (leasing Land)","باب كِرَاءِ الأَرْضِ","17"],[144,"Chapter: Leasing out Land (Kira) in return for food","باب كِرَاءِ الأَرْضِ بِالطَّعَامِ","18"],[150,"Chapter: Leasing out Land (Kira) for gold and silver","باب كِرَاءِ الأَرْضِ بِالذَّهَبِ وَالْوَرِقِ","19"],[154,"Chapter: Muzura'ah (Sharecropping) and Mu'ajarah","باب فِي الْمُزَارَعَةِ وَالْمُؤَاجَرَةِ","20"],[156,"Chapter: Lending Land","باب الأَرْضِ تُمْنَحُ","21"]],"22":[[1,"Chapter: Musaqah And Mu'amalah in return for a share of the fruit and crops","باب الْمُسَاقَاةِ وَالْمُعَامَلَةِ بِجُزْءٍ مِنَ الثَّمَرِ وَالزَّرْعِ","1"],[7,"Chapter: The Virtue of Planting and Cultivating","باب فَضْلِ الْغَرْسِ وَالزَّرْعِ","2"],[14,"Chapter: Waiving Payment in the case of Blight","باب وَضْعِ الْجَوَائِحِ","3"],[20,"Chapter: It is recommended to waive debts","باب اسْتِحْبَابِ الْوَضْعِ مِنَ الدَّيْنِ","4"],[26,"Chapter: If a man finds what he sold with the purchaser, who has become bankrupt, then he has the right to take it back","باب مَنْ أَدْرَكَ مَا بَاعَهُ عِنْدَ الْمُشْتَرِي وَقَدْ أَفْلَسَ فَلَهُ الرُّجُوعُ فِيهِ","5"],[32,"Chapter: The virute of giving more time to one who is suffering difficulty, and letting those go who are suffering difficulty and those who are well off","باب فَضْلِ إِنْظَارِ الْمُعْسِرِ","6"],[41,"Chapter: The prohibition of a rich man delaying repayment. The validity of Hawalah (Transferal of Debts) and it is recommended to accept transferal of a debt if it is transferred to a rich man","بَاب تَحْرِيمِ مَطْلِ الْغَنِيِّ وَصِحَّةِ الْحَوَالَةِ وَاسْتِحْبَابِ قَبُولِهَا إِذَا أُحِيلَ عَلَى مَلِيٍّ","7"],[43,"Chapter: The prohibition of selling surplus water which is in the wilderness and is needed to take care of the pasture. The prohibition of not allowing others to use it. The prohibition of Stud fees","بَاب تَحْرِيمِ بَيْعِ فَضْلِ الْمَاءِ الَّذِي يَكُونُ بِالْفَلَاةِ وَيُحْتَاجُ إِلَيْهِ لِرَعْيِ الْكَلَأِ وَتَحْرِيمِ مَنْعِ بَذْلِهِ وَتَحْرِيمِ بَيْعِ ضِرَابِ الْفَحْلِ","8"],[48,"Chapter: The prohibition of the price of a dog, the fee of a fortuneteller and the payment of a prostitute, and the prohibition of selling cats","باب تَحْرِيمِ ثَمَنِ الْكَلْبِ وَحُلْوَانِ الْكَاهِنِ وَمَهْرِ الْبَغِيِّ وَالنَّهْىِ عَنْ بَيْعِ السِّنّ","9"],[55,"Chapter: The command to kill dogs, and its abrogation. The prohibition of keeping dogs, except for hunting, farming, (herding) livestock and the like","بَاب الْأَمْرِ بِقَتْلِ الْكِلَابِ وَبَيَانِ نَسْخِهِ وَبَيَانِ تَحْرِيمِ اقْتِنَائِهَا إِلَّا لِصَيْدٍ أَوْ زَرْعٍ أَوْ مَاشِيَةٍ وَنَحْوِ ذَلِكَ","10"],[77,"Chapter: The permissibility of a cupper's earnings","باب حِلِّ أُجْرَةِ الْحِجَامَةِ","11"],[82,"Chapter: The prohibition of selling wine","باب تَحْرِيمِ بَيْعِ الْخَمْرِ","12"],[87,"Chapter: The prohibition of selling wine, dead meat, pork and idols","باب تَحْرِيمِ بَيْعِ الْخَمْرِ وَالْمَيْتَةِ وَالْخِنْزِيرِ وَالأَصْنَامِ","13"],[93,"Chapter: Riba (Usury, Interest)","باب الرِّبَا","14"],[98,"Chapter: Exchange and Selling Gold for Silver on the spot","باب الصَّرْفِ وَبَيْعِ الذَّهَبِ بِالْوَرِقِ نَقْدًا","15"],[110,"Chapter: The Prohibition of selling silver for gold to be paid at a later date","باب النَّهْىِ عَنْ بَيْعِ الْوَرِقِ، بِالذَّهَبِ دَيْنًا","16"],[114,"Chapter: Selling a necklace in which there are pearls and gold","باب بَيْعِ الْقِلاَدَةِ فِيهَا خَرَزٌ وَذَهَبٌ","17"],[119,"Chapter: Selling Food Like for Like","باب بَيْعِ الطَّعَامِ مِثْلاً بِمِثْلٍ","18"],[131,"Chapter: Cursing the one who consumes Riba and the one who pays it","باب لَعْنِ آكِلِ الرِّبَا وَمُؤْكِلِهِ","19"],[133,"Chapter: Taking that which is lawful and leaving that which is unclear","باب أَخْذِ الْحَلاَلِ وَتَرْكِ الشُّبُهَاتِ","20"],[137,"Chapter: Selling Camels and Stipulating that one may ride them","باب بَيْعِ الْبَعِيرِ وَاسْتِثْنَاءِ رُكُوبِهِ","21"],[147,"Chapter: It is permissible to lend animals and it is recommended to pay in full, giving something better than that which ts owed","باب مَنِ اسْتَسْلَفَ شَيْئًا فَقَضَى خَيْرًا مِنْهُ وَ \" خَيْرُكُمْ أَحْسَنُكُمْ قَضَاءً \"","22"],[152,"Chapter: The permissibility of selling animals for animals of the same kind and of different quality","باب جَوَازِ بَيْعِ الْحَيَوَانِ بِالْحَيَوَانِ مِنْ جِنْسِهِ مُتَفَاضِلاً","23"],[153,"Chapter: Pawning (Rahn) and its permissibility whether one is travelling or not","باب الرَّهْنِ وَجَوَازِهِ فِي الْحَضَرِ وَالسَّفَرِ","24"],[157,"Chapter: Salam (Payment in Advance)","باب السَّلَمِ","25"],[161,"Chapter: The prohibition of hoarding staple foods","باب تَحْرِيمِ الاِحْتِكَارِ فِي الأَقْوَاتِ","26"],[164,"Chapter: The prohibition of swearing oaths when selling","باب النَّهْىِ عَنِ الْحَلِفِ، فِي الْبَيْعِ","27"],[166,"Chapter: Pre-emption","باب الشُّفْعَةِ","28"],[169,"Chapter: Fixing a piece of wood to a neighbor's wall","باب غَرْزِ الْخَشَبِ فِي جِدَارِ الْجَارِ","29"],[171,"Chapter: The prohibition of wrongdoing, seizing land unlawfully etc","باب تَحْرِيمِ الظُّلْمِ وَغَصْبِ الأَرْضِ وَغَيْرِهَا","30"],[178,"Chapter: The width of the road if there is a dispute about it","باب قَدْرِ الطَّرِيقِ إِذَا اخْتَلَفُوا فِيهِ","31"]],"23":[[2,"Chapter: Give The Shares Of Inheritance To Those Who Are Entitled To Them, And Whatever Is Left Goes To The Closest Male Relative","باب أَلْحِقُوا الْفَرَائِضَ بِأَهْلِهَا فَمَا بَقِيَ فَلأَوْلَى رَجُلٍ ذَكَرٍ","1"],[6,"Chapter: Inheritance Of The Kalalah","باب مِيرَاثِ الْكَلاَلَةِ","2"],[13,"Chapter: The Last Verse To Be Revealed Was The Verse Of Kalalah","باب آخِرِ آيَةٍ أُنْزِلَتْ آيَةُ الْكَلاَلَةِ","3"],[18,"Chapter: Whoever Leaves Behind Wealth, It Is For His Heirs","باب مَنْ تَرَكَ مَالاً فَلِوَرَثَتِهِ","4"]],"24":[[1,"Chapter: It Is Disliked For A Man To Buy What He Gave In Charity From The One To Whom He Gave It","باب كَرَاهَةِ شِرَاءِ الإِنْسَانِ مَا تَصَدَّقَ بِهِ مِمَّنْ تَصَدَّقَ عَلَيْهِ","1"],[8,"Chapter: The Prohibition Of Taking Back One's Charity After It Has Been Accepted, Except In The Case Of What A Father Gives To A Son Or Grandson","بَاب تَحْرِيمِ الرُّجُوعِ فِي الصَّدَقَةِ وَالْهِبَةِ بَعْدَ الْقَبْضِ إِلَّا مَا وَهَبَهُ لِوَلَدِهِ وَإِنْ سَفَلَ","2"],[15,"Chapter: It Is Disliked To Favor Some Of One's Children Over Others In Gift-Giving","باب كَرَاهَةِ تَفْضِيلِ بَعْضِ الأَوْلاَدِ فِي الْهِبَةِ","3"],[26,"Chapter: The 'Umra (Lifelong Gift)","باب الْعُمْرَى","4"]],"25":[[6,"Chapter: Bequeathing One-Third","باب الْوَصِيَّةِ بِالثُّلُثِ","1"],[16,"Chapter: The Reward For Charity Reaches The Deceased","باب وُصُولِ ثَوَابِ الصَّدَقَاتِ إِلَى الْمَيِّتِ","2"],[20,"Chapter: What Reward Reaches A Man After His Death","باب مَا يَلْحَقُ الإِنْسَانَ مِنَ الثَّوَابِ بَعْدَ وَفَاتِهِ","3"],[21,"Chapter: Waqf (Endowment)","باب الْوَقْفِ","4"],[24,"Chapter: Not Making A Will For One Who Has Nothing To Be Bequeathed","باب تَرْكِ الْوَصِيَّةِ لِمَنْ لَيْسَ لَهُ شَىْءٌ يُوصِي فِيهِ","5"]],"26":[[1,"Chapter: The Command To Fulfill Vows","باب الأَمْرِ بِقَضَاءِ النَّذْرِ","1"],[3,"Chapter: he Prohibition Of Vows, And Confirmation That They Do Not Avert Anything","باب النَّهْىِ عَنِ النَّذْرِ، وَأَنَّهُ، لاَ يَرُدُّ شَيْئًا","2"],[11,"Chapter: There is no fulfillment of a vow that involves disobedience towards Allah, or a vow concerning that which a person does not own","باب لاَ وَفَاءَ لِنَذْرٍ فِي مَعْصِيَةِ اللَّهِ وَلاَ فِيمَا لاَ يَمْلِكُ الْعَبْدُ","3"],[13,"Chapter: One Who Vows To Walk To The Ka'bah","باب مَنْ نَذَرَ أَنْ يَمْشِيَ إِلَى الْكَعْبَةِ","4"],[18,"Chapter: Expiation For Breaking A Vow","باب فِي كَفَّارَةِ النَّذْرِ","5"]],"27":[[1,"Chapter: The prohibition of swearing by something other than Allah","باب النَّهْىِ عَنِ الْحَلِفِ بِغَيْرِ اللَّهِ تَعَالَى","1"],[7,"Chapter: Whoever swears by Al-Lat and Al-Uzza, let him say La Ilaha Illallah","باب مَنْ حَلَفَ بِاللاَّتِ وَالْعُزَّى فَلْيَقُلْ لاَ إِلَهَ إِلاَّ اللَّهُ","2"],[10,"Chapter: It is recommended for the one who swears an oath then sees that something else is better than it; To do that which is better and offer expiation for his oath","باب نَدْبِ مَنْ حَلَفَ يَمِينًا فَرَأَى غَيْرَهَا خَيْرًا مِنْهَا أَنْ يَأْتِيَ الَّذِي هُوَ خَيْرٌ وَيُكَفِّرَ عَنْ يَمِينِهِ","3"],[30,"Chapter: An oath is judged on the intention of the one who asks for it to be sworn.","باب يَمِينِ الْحَالِفِ عَلَى نِيَّةِ الْمُسْتَحْلِفِ","4"],[32,"Chapter: Saying: \"If Allah wills\" when swearing oaths and at other times","باب الاِسْتِثْنَاءِ","5"],[38,"Chapter: The prohibition of persisting in an oath that will harm the family of the one who swears it, so long as not persisting in it does not involve anything unlawful","باب النَّهْىِ عَنِ الإِصْرَارِ، عَلَى الْيَمِينِ فِيمَا يَتَأَذَّى بِهِ أَهْلُ الْحَالِفِ مِمَّا لَيْسَ بِحَرَامٍ","6"],[39,"Chapter: The vow of a disbeliever, and what he should do about it if he becomes a muslim","باب نَذْرِ الْكَافِرِ وَمَا يَفْعَلُ فِيهِ إِذَا أَسْلَمَ","7"],[45,"Chapter: Treatment of slaves, and the expiation of one who slaps his slave","باب صُحْبَةِ الْمَمَالِيكِ وَكَفَّارَةِ مَنْ لَطَمَ عَبْدَهُ","8"],[58,"Chapter: Stern warning against accusing a slave of fornication","باب التَّغْلِيظِ عَلَى مَنْ قَذَفَ مَمْلُوكَهُ بِالزِّنَا","9"],[60,"Chapter: Feeding a slave what one eats and clothing him as one clothes oneself, and not burdening him with more than he bear","باب إِطْعَامِ الْمَمْلُوكِ مِمَّا يَأْكُلُ وَإِلْبَاسِهِ مَمَّا يَلْبَسُ وَلاَ يُكَلِّفُهُ مَا يَغْلِبُهُ","10"],[65,"Chapter: The reward of a slave who is sincere towards his master and worships Allah properly","باب ثَوَابِ الْعَبْدِ وَأَجْرِهِ إِذَا نَصَحَ لِسَيِّدِهِ وَأَحْسَنَ عِبَادَةَ اللَّهِ","11"],[72,"Chapter: One who frees his share in a slave","باب مَنْ أَعْتَقَ شِرْكًا لَهُ فِي عَبْدٍ","12"],[85,"Chapter: Permissibility of selling a Mudabbar","باب جَوَازِ بَيْعِ الْمُدَبَّرِ","13"]],"28":[[1,"Chapter: Qasamah (Oaths)","باب الْقَسَامَةِ","1"],[12,"Chapter: The ruling on Muharibin and Apostates","باب حُكْمِ الْمُحَارِبِينَ وَالْمُرْتَدِّينَ","2"],[20,"Chapter: Confirmation of Qisas in the case of killing with a rock and other sharp or heavy objects, and the killing of a man for a woman","باب ثُبُوتِ الْقِصَاصِ فِي الْقَتْلِ بِالْحَجَرِ وَغَيْرِهِ مِنَ الْمُحَدَّدَاتِ وَالْمُثَقَّلاَتِ وَقَتْلِ الرَّجُلِ بِالْمَرْأَةِ","3"],[25,"Chapter: If a person attacks another person's life and limb, and the other defends himself and kills him or injures him, there is no penalty on him","باب الصَّائِلُ عَلَى نَفْسِ الإِنْسَانِ أَوْ عُضْوِهِ إِذَا دَفَعَهُ الْمَصُولُ عَلَيْهِ فَأَتْلَفَ نَفْسَهُ أَوْ عُضْوَهَ لاَ ضَمَانَ عَلَيْهِ","4"],[33,"Chapter: The validity of Qisas for teeth and the like","باب إِثْبَاتِ الْقِصَاصِ فِي الأَسْنَانِ وَمَا فِي مَعْنَاهَا","5"],[34,"Chapter: When it is permissible to shed the blood of a muslim","باب مَا يُبَاحُ بِهِ دَمُ الْمُسْلِمِ","6"],[38,"Chapter: The sin of the one who set the precedent of killing","باب بَيَانِ إِثْمِ مَنْ سَنَّ الْقَتْلَ","7"],[40,"Chapter: The punishment for bloodshed in the hereafter, and bloodshed will be the first thing concerning which judgement is passed among the people on the Day of Resurrection","باب الْمُجَازَاةِ بِالدِّمَاءِ فِي الآخِرَةِ وَأَنَّهَا أَوَّلُ مَا يُقْضَى فِيهِ بَيْنَ النَّاسِ يَوْمَ الْقِيَامَةِ","8"],[42,"Chapter: Emphasis on the sanctity of Blood, Honor and Wealth","باب تَغْلِيظِ تَحْرِيمِ الدِّمَاءِ وَالأَعْرَاضِ وَالأَمْوَالِ","9"],[46,"Chapter: A confession to murder is valid and the heir of the victim is entitled to Qisas, but it is recommended to ask him to let him go","باب صِحَّةِ الإِقْرَارِ بِالْقَتْلِ وَتَمْكِينِ وَلِيِّ الْقَتِيلِ مِنَ الْقِصَاصِ وَاسْتِحْبَابِ طَلَبِ الْعَفْوِ مِنْهُ","10"],[48,"Chapter: The Diyah for a fetus; and the Diyah for accidental killing and the ambiguous killing must be paid by the shahiqilah of the killer","باب دِيَةِ الْجَنِينِ وَوُجُوبِ الدِّيَةِ فِي قَتْلِ الْخَطَإِ وَشِبْهِ الْعَمْدِ عَلَى عَاقِلَةِ الْجَانِي","11"]],"29":[[1,"Chapter: The Hadd for stealing and the minimum threshold","باب حَدِّ السَّرِقَةِ وَنِصَابِهَا","1"],[13,"Chapter: Cutting off the hand of a thief from the nobility and others; the prohibition of interceding with regard to Hudud punishments","باب قَطْعِ السَّارِقِ الشَّرِيفِ وَغَيْرِهِ وَالنَّهْىِ عَنِ الشَّفَاعَةِ فِي الْحُدُودِ","2"],[17,"Chapter: The Hadd punishment for Zina (fornication, adultery)","باب حَدِّ الزِّنَا","3"],[21,"Chapter: Stoning of a married person for Zina","باب رَجْمِ الثَّيِّبِ فِي الزِّنَا","4"],[23,"Chapter: One who confesses to Zina","باب مَنِ اعْتَرَفَ عَلَى نَفْسِهِ بِالزِّنَا","5"],[40,"Chapter: Stoning Jews and Ahl Adh-Dhimmah for Zina","باب رَجْمِ الْيَهُودِ أَهْلِ الذِّمَّةِ فِي الزِّنَا","6"],[53,"Chapter: Delaying the Hadd punishment in the case of women who have just given birth","باب تَأْخِيرِ الْحَدِّ عَنِ النُّفَسَاءِ،","7"],[55,"Chapter: Hadd punishment for drinking alcohol","باب حَدِّ الْخَمْرِ","8"],[63,"Chapter: Number of lashes in the case of ta'zeer","باب قَدْرِ أَسْوَاطِ التَّعْزِيرِ","9"],[64,"Chapter: The Hadd punishments are an expiation for those on whom they are carried out","باب الْحُدُودُ كَفَّارَاتٌ لأَهْلِهَا","10"],[68,"Chapter: There is no Diyah for injuries caused by animals or by falling into a mine or well","باب جَرْحُ الْعَجْمَاءِ وَالْمَعْدِنِ وَالْبِئْرِ جُبَارٌ","11"]],"30":[[1,"Chapter: Oath should be sworn by the defendant","باب الْيَمِينُ عَلَى الْمُدَّعَى عَلَيْهِ","1"],[3,"Chapter: The obligation of judging on the basis of a witness and an oath","باب الْقَضَاءِ بِالْيَمِينِ وَالشَّاهِدِ","2"],[4,"Chapter: So the judgement of the judge does not change what happened","باب الْحُكْمِ بِالظَّاهِرِ وَاللَّحْنِ بِالْحُجَّةِ","3"],[8,"Chapter: The case of Hind","باب قَضِيَّةِ هِنْدٍ","4"],[12,"Chapter: The prohibition of asking too much with no need. The prohibition of withholding the rights of others and asking of them, which means refusing to give others their rights and asking for that to which one is not entitles","باب النَّهْيِ عَنْ كَثْرَةِ الْمَسَائِلِ مِنْ غَيْرِ حَاجَةٍ وَالنَّهْيِ عَنْ مَنْعٍ وَهَاتٍ وَهُوَ الاِمْتِنَاعُ مِنْ أَدَاءِ حَقٍّ لَزِمَهُ أَوْ طَلَبُ مَا لاَ يَسْتَحِقُّهُ","5"],[18,"Chapter: The reward of the judge if he strives to reach a decision, whether he gets it right or wrong","باب بَيَانِ أَجْرِ الْحَاكِمِ إِذَا اجْتَهَدَ فَأَصَابَ أَوْ أَخْطَأَ","6"],[21,"Chapter: It is disliked for a judge to pass a judgement when he is angry","باب كَرَاهَةِ قَضَاءِ الْقَاضِي وَهُوَ غَضْبَانُ","7"],[23,"Chapter: Rejection of wrong rulings and of newly-invented matters","باب نَقْضِ الأَحْكَامِ الْبَاطِلَةِ وَرَدِّ مُحْدَثَاتِ الأُمُورِ","8"],[25,"Chapter: The best of witnesses","باب بَيَانِ خَيْرِ الشُّهُودِ","9"],[26,"Chapter: Differences between mujtahids","باب بَيَانِ اخْتِلاَفِ الْمُجْتَهِدِينَ","10"],[28,"Chapter: It is recommended for a judge to reconcile between disputants","باب اسْتِحْبَابِ إِصْلاَحِ الْحَاكِمِ بَيْنَ الْخَصْمَيْنِ","11"]],"31":[[1,"Chapter: Picking up property lost by a pilgrim","باب","1"],[11,"Chapter: Milking animals is unlawful if the owner has not given permission","باب فِي لُقَطَةِ الْحَاجِّ","2"],[13,"Chapter: Hospitality etc","باب تَحْرِيمِ حَلْبِ الْمَاشِيَةِ بِغَيْرِ إِذْنِ مَالِكِهَا","3"],[15,"Chapter: It is recommended to spend surplus wealth","باب الضِّيَافَةِ وَنَحْوِهَا","4"],[19,"Chapter: It is recommended to mix provisions if they are few, and to share them out","باب اسْتِحْبَابِ الْمُؤَاسَاةِ بِفُضُولِ الْمَالِ","5"],[20,"","باب اسْتِحْبَابِ خَلْطِ الأَزْوَادِ إِذَا قَلَّتْ وَالْمُؤَاسَاةِ فِيهَا","6"]],"32":[[1,"Chapter: Permissibility of raiding the Kuffar, who have been reached with the call of Islam, without giving prior warning","باب جَوَازِ الإِغَارَةِ عَلَى الْكُفَّارِ الَّذِينَ بَلَغَتْهُمْ دَعْوَةُ الإِسْلاَمِ مِنْ غَيْرِ تَقَدُّمِ الإِعْلاَمِ بِالإِغَارَةِ","1"],[3,"Chapter: Ruler appointing leaders of expeditions and advising them of the etiquette of war, etc.","باب تَأْمِيرِ الإِمَامِ الأُمَرَاءَ عَلَى الْبُعُوثِ وَوَصِيَّتِهِ إِيَّاهُمْ بِآدَابِ الْغَزْوِ وَغَيْرِهَا","2"],[6,"Chapter: The command to show leniency and avoid causing aversion (towards Islam)","باب فِي الأَمْرِ بِالتَّيْسِيرِ وَتَرْكِ التَّنْفِيرِ","3"],[10,"Chapter: The prohibition of betrayal","باب تَحْرِيمِ الْغَدْرِ","4"],[20,"Chapter: Permissibility of deceit in war","باب جَوَازِ الْخِدَاعِ فِي الْحَرْبِ","5"],[22,"Chapter: It is disliked to wish to meet the enemy, and the command to be steadfast when meeting the enemy","باب كَرَاهَةِ تَمَنِّي لِقَاءِ الْعَدُوِّ وَالأَمْرِ بِالصَّبْرِ عِنْدَ اللِّقَاءِ","6"],[24,"Chapter: It is recommended to pray for victory when meeting the enemy","باب اسْتِحْبَابِ الدُّعَاءِ بِالنَّصْرِ عِنْدَ لِقَاءِ الْعَدُوِّ","7"],[28,"Chapter: The prohibition of killing women and children in war","باب تَحْرِيمِ قَتْلِ النِّسَاءِ وَالصِّبْيَانِ فِي الْحَرْبِ","8"],[30,"Chapter: Permissibility of killing women and children in night raids, so long as it is not done deliberately","باب جَوَازِ قَتْلِ النِّسَاءِ وَالصِّبْيَانِ فِي الْبَيَاتِ مِنْ غَيْرِ تَعَمُّدٍ","9"],[33,"Chapter: Permissibility of cutting down the trees of the Kuffar and burning them","باب جَوَازِ قَطْعِ أَشْجَارِ الْكُفَّارِ وَتَحْرِيقِهَا","10"],[36,"Chapter: War booty has been made permissible for this Ummah only","باب تَحْلِيلِ الْغَنَائِمِ لِهَذِهِ الأُمَّةِ خَاصَّةً","11"],[37,"Chapter: Spoils of War","باب الأَنْفَالِ","12"],[47,"Chapter: The killer is entitled to the belongings of the one who is killed","باب اسْتِحْقَاقِ الْقَاتِلِ سَلَبَ الْقَتِيلِ","13"],[54,"Chapter: Additional rewards, and ransoming muslims in return for prisoners","باب التَّنْفِيلِ وَفِدَاءِ الْمُسْلِمِينَ بِالأَسَارَى","14"],[55,"Chapter: Ruling on Fai' (Booty acquired without fighting)","باب حُكْمِ الْفَىْءِ","15"],[60,"Chapter: The words of the Prophet (saws): \"We (Prophets) have no heirs and whatever we leave behind is charity.\"","باب قَوْلِ النَّبِيِّ صلى الله عليه وسلم \" لاَ نُورَثُ مَا تَرَكْنَا فَهُوَ صَدَقَةٌ \"","16"],[67,"Chapter: How booty is to be shared among the fighters","باب كَيْفِيَّةِ قِسْمَةِ الْغَنِيمَةِ بَيْنَ الْحَاضِرِينَ","17"],[69,"Chapter: The support of the angels during the Battle of Badr, and the permissibility of the spoils","باب الإِمْدَادِ بِالْمَلاَئِكَةِ فِي غَزْوَةِ بَدْرٍ وَإِبَاحَةِ الْغَنَائِمِ","18"],[70,"Chapter: Tying up and detaining captives, and the permissibility of releasing them without a ransom","باب رَبْطِ الأَسِيرِ وَحَبْسِهِ وَجَوَازِ الْمَنِّ عَلَيْهِ","19"],[72,"Chapter: Expulsion of the Jews from the Hijaz","باب إِجْلاَءِ الْيَهُودِ مِنَ الْحِجَازِ","20"],[75,"Chapter: Expulsion of Jews and Christians from the Arabian Peninsula","باب إِخْرَاجِ الْيَهُودِ وَالنَّصَارَى مِنْ جَزِيرَةِ الْعَرَبِ","21"],[77,"Chapter: Permissibility of fighting those who break a treaty; Permissibility of letting besieged people surrender, subject to the judgement of a just person who is qualified to pass judgement","باب جَوَازِ قِتَالِ مَنْ نَقَضَ الْعَهْدَ وَجَوَازِ إِنْزَالِ أَهْلِ الْحِصْنِ عَلَى حُكْمِ حَاكِمٍ عَدْلٍ أَهْلٍ لِلْحُكْمِ","22"],[83,"Chapter: Hastening to fight, and giving precedence to the more urgent of two tasks when a choice must be made","باب مَنْ لَزِمَهُ أَمْرٌ فَدَخَلَ عَلَيْهِ أَمْرٌ آخَرُ","23"],[84,"Chapter: The Muhajirun returned to the Ansar the gifts of trees and fruits when they became independent of means through the conquests","باب رَدِّ الْمُهَاجِرِينَ إِلَى الأَنْصَارِ مَنَائِحَهُمْ مِنَ الشَّجَرِ وَالثَّمَرِ حِينَ اسْتَغْنَوْا عَنْهَا بِالْفُتُوحِ","24"],[86,"Chapter: Permissibility of eating food seized as booty in Dar Al-Harb","باب أَخْذِ الطَّعَامِ مِنْ أَرْضِ الْعَدُوِّ","25"],[89,"Chapter: The Prophet (saws) wrote to Heraclius, the ruler of Syria, inviting him to Islam","باب كِتَابِ النَّبِيِّ صلى الله عليه وسلم إِلَى هِرَقْلَ يَدْعُوهُ إِلَى الإِسْلاَمِ","26"],[91,"Chapter: The Prophet (saws) wrote to the Kings of the Kuffar, inviting them to Islam","باب كُتُبِ النَّبِيِّ صلى الله عليه وسلم إِلَى مُلُوكِ الْكُفَّارِ يَدْعُوهُمْ إِلَى اللَّهِ عَزَّ وَجَلَّ","27"],[94,"Chapter: The Battle of Hunain","باب فِي غَزْوَةِ حُنَيْنٍ","28"],[102,"Chapter: The Battle of At-Ta'if","باب غَزْوَةِ الطَّائِفِ","29"],[103,"Chapter: The Battle of Badr","باب غَزْوَةِ بَدْرٍ","30"],[104,"Chapter: The conquest of Makkah","باب فَتْحِ مَكَّةَ","31"],[107,"Chapter: Removal of Idols from around the Ka'bah","باب إِزَالَةِ الأَصْنَامِ مِنْ حَوْلِ الْكَعْبَةِ","32"],[109,"Chapter: No man if Quraish is to be captured then killed, after the conquest","باب لاَ يُقْتَلُ قُرَشِيٌّ صَبْرًا بَعْدَ الْفَتْحِ","33"],[111,"Chapter: The truce of Al-Hudaybiyah","باب صُلْحِ الْحُدَيْبِيَةِ فِي الْحُدَيْبِيَةِ","34"],[121,"Chapter: Upholding Covenants","باب الْوَفَاءِ بِالْعَهْدِ","35"],[122,"Chapter: The Battle of Al-Ahzab (The Confederates)","باب غَزْوَةِ الأَحْزَابِ","36"],[123,"Chapter: The Battle of Uhud","باب غَزْوَةِ أُحُدٍ","37"],[130,"Chapter: The intense wrath of Allah towards the one who was killed by the messenger of Allah (saws)","باب اشْتِدَادِ غَضَبِ اللَّهِ عَلَى مَنْ قَتَلَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم","38"],[131,"Chapter: The persecution suffered by the prophet (saws) at the hands of the idolaters and hypocrites","باب مَا لَقِيَ النَّبِيُّ صلى الله عليه وسلم مِنْ أَذَى الْمُشْرِكِينَ وَالْمُنَافِقِينَ","39"],[141,"Chapter: The supplication of the Prophet (saws) and his steadfastness in the face of the hypocrites' persecution","باب فِي دُعَاءِ النَّبِيِّ صلى الله عليه وسلم إِلَى اللَّهِ وَصَبْرِهِ عَلَى أَذَى الْمُنَافِقِينَ","40"],[144,"Chapter: The slaying of Abu Jahl","باب قَتْلِ أَبِي جَهْلٍ","41"],[146,"Chapter: The slaying of Ka'b Bin Al-Ashraf, the Tagut of the Jews","باب قَتْلِ كَعْبِ بْنِ الأَشْرَفِ طَاغُوتِ الْيَهُودِ","42"],[147,"Chapter: The Battle of Khaibar","باب غَزْوَةِ خَيْبَرَ","43"],[152,"Chapter: The Battle of Al-Ahzab (The Confederates), also known as Al-Khandaq (The Ditch)","باب غَزْوَةِ الأَحْزَابِ وَهِيَ الْخَنْدَقُ","44"],[159,"Chapter: The Battle of Dhu Qarad and other battles","باب غَزْوَةِ ذِي قَرَدٍ وَغَيْرِهَا","45"],[162,"Chapter: The words of Allah, the Most High: \"And He it is who has withheld their hands from you\"","باب قَوْلِ اللَّهِ تَعَالَى: {وَهُوَ الَّذِي كَفَّ أَيْدِيَهُمْ عَنْكُمْ} الآيَةَ:","46"],[163,"Chapter: Women participating in military expeditions with the men","باب غَزْوَةِ النِّسَاءِ مَعَ الرِّجَالِ","47"],[166,"Chapter: Women who take part in military expeditions are to be given a reward but not a regular share; And the prohibition of killing children of the enemy","باب النِّسَاءُ الْغَازِيَاتُ يُرْضَخُ لَهُنَّ وَلاَ يُسْهَمُ وَالنَّهْىُ عَنْ قَتْلِ صِبْيَانِ أَهْلِ الْحَرْبِ","48"],[174,"Chapter: The number of campaigns of the Prophet (saws)","باب عَدَدِ غَزَوَاتِ النَّبِيِّ صلى الله عليه وسلم","49"],[181,"Chapter: The campaign of Dhat Ar-Riqa","باب غَزْوَةِ ذَاتِ الرِّقَاعِ","50"],[182,"Chapter: It is disliked to seek the help of a disbeliever in wars (except in cases of necessity, or if he thinks well of the Muslims)","باب كَرَاهَةِ الاِسْتِعَانَةِ فِي الْغَزْوِ بِكَافِرٍ","51"]],"33":[[1,"Chapter: The people follow the Quraish and the Caliphate belongs to the Quraish","باب النَّاسُ تَبَعٌ لِقُرَيْشٍ وَالْخِلاَفَةُ فِي قُرَيْشٍ","1"],[13,"Chapter: Appointing a successor or not doing so","باب الاِسْتِخْلاَفِ وَتَرْكِهِ","2"],[15,"Chapter: The prohibition of seeking or desiring a position of authority","باب النَّهْىِ عَنْ طَلَبِ الإِمَارَةِ، وَالْحِرْصِ، عَلَيْهَا","3"],[19,"Chapter: It is disliked to be appointed to a position of authority unnecessarily","باب كَرَاهَةِ الإِمَارَةِ بِغَيْرِ ضَرُورَةٍ","4"],[21,"Chapter: The virtue of a just ruler and the punishment of a tyrant; Encouragement to treat those under one's authority with kindness and the prohibition against causing them hardship","باب فَضِيلَةِ الإِمَامِ الْعَادِلِ وَعُقُوبَةِ الْجَائِرِ وَالْحَثِّ عَلَى الرِّفْقِ بِالرَّعِيَّةِ وَالنَّهْيِ عَنْ إِدْخَالِ الْمَشَقَّةِ عَلَيْهِمْ","5"],[33,"Chapter: Emphatic prohibition against stealing from the spoils of war (Ghulul)","باب غِلَظِ تَحْرِيمِ الْغُلُولِ","6"],[37,"Chapter: The prohibition of giving gifts to agents","باب تَحْرِيمِ هَدَايَا الْعُمَّالِ","7"],[45,"Chapter: The obligation of obeying leaders in matters that do not involve sin, but it is forbidden to obey them in sinful matters","باب وُجُوبِ طَاعَةِ الأُمَرَاءِ فِي غَيْرِ مَعْصِيَةٍ وَتَحْرِيمِهَا فِي الْمَعْصِيَةِ","8"],[70,"Chapter: The ruler is a shield from behind whom they fight and by whom they are protected","باب فِي الإِمَامِ إِذَا أَمَرَ بِتَقْوَى اللَّهِ وَعَدَلَ كَانَ لَهُ أَجْرٌ","9"],[71,"Chapter: The obligation of fulfilling oaths of allegiance is owed to the first of two Caliphs","باب الْوَفَاءِ بِبَيْعَةِ الْخُلَفَاءِ الأَوَّلِ فَالأَوَّلِ","10"],[77,"Chapter: The command to be patient in the face of oppressive rulers and their selfishness","باب الأَمْرِ بِالصَّبْرِ عِنْدَ ظُلْمِ الْوُلاَةِ وَاسْتِئْثَارِهِمْ","11"],[79,"Chapter: Obeying Rulers even if they withhold the people's rights","باب فِي طَاعَةِ الأُمَرَاءِ وَإِنْ مَنَعُوا الْحُقُوقَ","12"],[81,"Chapter: The obligation of staying with the Jama'ah (main body) of the muslims when Fitn (tribulations) appear, and in all circumstances. The prohibition of refusing to obey and on splitting away from the Jama'ah","باب الأَمْرِ بِلُزُومِ الْجَمَاعَةِ عِنْدَ ظُهُورِ الْفِتَنِ وَتَحْذِيرِ الدُّعَاةِ إِلَى الْكُفْرِ","13"],[93,"Chapter: The ruling on one who seeks to divide the muslims when they are united","باب حُكْمِ مَنْ فَرَّقَ أَمْرَ الْمُسْلِمِينَ وَهُوَ مُجْتَمِعٌ","14"],[96,"Chapter: When allegiance has been sworn to two caliphs","باب إِذَا بُويِعَ لِخَلِيفَتَيْنِ","15"],[97,"Chapter: The obligation to denounce rulers for that in which they go against Shari'ah, but they should not be fought so long as they pray regularly, etc","باب وُجُوبِ الإِنْكَارِ عَلَى الأُمَرَاءِ فِيمَا يُخَالِفُ الشَّرْعَ وَتَرْكِ قِتَالِهِمْ مَا صَلَّوْا وَنَحْوِ ذَلِكَ","16"],[101,"Chapter: The best and worst of rulers","باب خِيَارِ الأَئِمَّةِ وَشِرَارِهِمْ","17"],[104,"Chapter: It is recommended for the army to swear allegiance to the ruler when intending to fight, and an account of Bay'at Ar-Ridwan beneath the tree","باب اسْتِحْبَابِ مُبَايَعَةِ الإِمَامِ الْجَيْشَ عِنْدَ إِرَادَةِ الْقِتَالِ وَبَيَانِ بَيْعَةِ الرِّضْوَانِ تَحْتَ الشَّجَرَةِ","18"],[121,"Chapter: The prohibition against a Muhajir returning to settle in his former homeland","باب تَحْرِيمِ رُجُوعِ الْمُهَاجِرِ إِلَى اسْتِيطَانِ وَطَنِهِ","19"],[122,"Chapter: Swearing Allegiance and Pledging to adhere to Islam, to engage in Jihad and to do Good, after the conquest of Makkah, and the meaning of the phrase: \"There is No Hijrah (migration) after the Conquest.\"","باب الْمُبَايَعَةِ بَعْدَ فَتْحِ مَكَّةَ عَلَى الإِسْلاَمِ وَالْجِهَادِ وَالْخَيْرِ وَبَيَانِ مَعْنَى: «لاَ هِجْرَةَ بَعْدَ الْفَتْحِ»","20"],[130,"Chapter: How women gave their oath of allegiance","باب كَيْفِيَّةِ بَيْعَةِ النِّسَاءِ","21"],[132,"Chapter: Oath of allegiance pledging to hear and obey as much as possible","باب الْبَيْعَةِ عَلَى السَّمْعِ وَالطَّاعَةِ فِيمَا اسْتَطَاعَ","22"],[133,"Chapter: The age of responsibility","باب بَيَانِ سِنِّ الْبُلُوغِ","23"],[135,"Chapter: The prohibition of travelling with the Mushaf to the land of the disbelievers if there is the fear that it may fall into their hands.","باب النَّهْىِ أَنْ يُسَافَرَ بِالْمُصْحَفِ إِلَى أَرْضِ الْكُفَّارِ إِذَا خِيفَ وُقُوعُهُ بِأَيْدِيهِمْ","24"],[139,"Chapter: Horse Races and Training Horses for Racing","باب الْمُسَابَقَةِ بَيْنَ الْخَيْلِ وَتَضْمِيرِهَا","25"],[141,"Chapter: The virtue of horses; \"Goodness is tied to their Forelocks.\"","باب الْخَيْلُ فِي نَوَاصِيهَا الْخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ","26"],[152,"Chapter: Disliked qualities in Horses","باب مَا يُكْرَهُ مِنْ صِفَاتِ الْخَيْلِ","27"],[155,"Chapter: The virtue of Jihad and going out (to fight) in the cause of Allah","باب فَضْلِ الْجِهَادِ وَالْخُرُوجِ فِي سَبِيلِ اللَّهِ","28"],[163,"Chapter: The virtue of Martyrdom in the cause of Allah","باب فَضْلِ الشَّهَادَةِ فِي سَبِيلِ اللَّهِ تَعَالَى","29"],[169,"Chapter: The virtue of going out in the morning or the evening in the cause of Allah","باب فَضْلِ الْغَدْوَةِ وَالرَّوْحَةِ فِي سَبِيلِ اللَّهِ","30"],[175,"Chapter: The High Positions that Allah has prepared for the Mujahid in Paradise","باب بَيَانِ مَا أَعَدَّهُ اللَّهُ تَعَالَى لِلْمُجَاهِدِ فِي الْجَنَّةِ مِنَ الدَّرَجَاتِ","31"],[176,"Chapter: If a person is killed in the cause of Allah, all his sins will be expiated except debt","باب مَنْ قُتِلَ فِي سَبِيلِ اللَّهِ كُفِّرَتْ خَطَايَاهُ إِلاَّ الدَّيْنَ","32"],[181,"Chapter: The souls of the martyrs are in Paradise, and they are alive with their Lord and they have provision","باب فِي بَيَانِ أَنَّ أَرْوَاحَ الشُّهَدَاءِ فِي الْجَنَّةِ وَأَنَّهُمْ أَحْيَاءٌ عِنْدَ رَبِّهِمْ يُرْزَقُونَ","33"],[182,"Chapter: The virtue of Jihad and keeping watch over the frontier","باب فَضْلِ الْجِهَادِ وَالرِّبَاطِ","34"],[188,"Chapter: Two Men, one of whom kills the other, and both will enter Paradise","باب بَيَانِ الرَّجُلَيْنِ يَقْتُلُ أَحَدُهُمَا الآخَرَ يَدْخُلاَنِ الْجَنَّةَ","35"],[191,"Chapter: One who kills a disbeliever then keeps to the right path","باب مَنْ قَتَلَ كَافِرًا ثُمَّ سَدَّدَ","36"],[193,"Chapter: The virtue of Charity in the Cause of Allah, and its Manifold reward","باب فَضْلِ الصَّدَقَةِ فِي سَبِيلِ اللَّهِ وَتَضْعِيفِهَا","37"],[195,"Chapter: The virtue of helping the warrior who is fighting in the cause of Allah with mounts etc., and looking after his family in his absence","باب فَضْلِ إِعَانَةِ الْغَازِي فِي سَبِيلِ اللَّهِ بِمَرْكُوبٍ وَغَيْرِهِ وَخِلاَفَتِهِ فِي أَهْلِهِ بِخَيْرٍ","38"],[203,"Chapter: The sanctity of the wives of the Mujahidin, and the sin of the one who betrays them with regard to them","باب حُرْمَةِ نِسَاءِ الْمُجَاهِدِينَ وَإِثْمِ مَنْ خَانَهُمْ فِيهِنَّ","39"],[206,"Chapter: The duty of Jihad is waived for those who have excuses","باب سُقُوطِ فَرْضِ الْجِهَادِ عَنِ الْمَعْذُورِينَ،","40"],[208,"Chapter: Affirmation of Paradise for the Martyr","باب ثُبُوتِ الْجَنَّةِ لِلشَّهِيدِ","41"],[214,"Chapter: One who fights so that the word of Allah will be supreme is fighting in the cause of Allah","باب مَنْ قَاتَلَ لِتَكُونَ كَلِمَةُ اللَّهِ هِيَ الْعُلْيَا فَهُوَ فِي سَبِيلِ اللَّهِ","42"],[218,"Chapter: One who fights to show off and gain a reputation deserves Hell","باب مَنَ قَاتَلَ لِلرِّيَاءِ وَالسُّمْعَةِ اسْتَحَقَّ النَّارَ","43"],[220,"Chapter: The reward of those who fought and acquired spoils of war and those who did not acquire spoils of war","باب بَيَانِ قَدْرِ ثَوَابِ مَنْ غَزَا فَغَنِمَ وَمَنْ لَمْ يَغْنَمْ","44"],[222,"Chapter: The words of the prophets saws: \"Deeds are but with intentions\" which includes fighting and other deeds","باب قَوْلِهِ صلى الله عليه وسلم \" إِنَّمَا الأَعْمَالُ بِالنِّيَّةِ.\" وَأَنَّهُ يَدْخُلُ فِيهِ الْغَزْوُ وَغَيْرُهُ مِنَ الأَعْمَالِ","45"],[224,"Chapter: It is recommended to seek Martyrdom in the Cause of Allah, Exalted is He.","باب اسْتِحْبَابِ طَلَبِ الشَّهَادَةِ فِي سَبِيلِ اللَّهِ تَعَالَى","46"],[226,"Chapter: Criticism of one who dies without having fought (in Jihad) or having thought of fighting","باب ذَمِّ مَنْ مَاتَ وَلَمْ يَغْزُ وَلَمْ يُحَدِّثْ نَفْسَهُ بِالْغَزْوِ","47"],[227,"Chapter: The reward of one who is kept from fighting by sickness or any other excuse","باب ثَوَابِ مَنْ حَبَسَهُ عَنِ الْغَزْوِ، مَرَضٌ أَوْ عُذْرٌ آخَرُ","48"],[229,"Chapter: The virtue of campaigning by sea","باب فَضْلِ الْغَزْوِ فِي الْبَحْرِ","49"],[233,"Chapter: The virtue of guarding the frontier in the cause of Allah (Glorified and Exalted is He)","باب فَضْلِ الرِّبَاطِ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ","50"],[235,"Chapter: About the Martyrs","باب بَيَانِ الشُّهَدَاءِ","51"],[241,"Chapter: The virtue of Shooting and Encouragement to learn it, and criticism of the one who learns it and then forgets it","باب فَضْلِ الرَّمْىِ وَالْحَثِّ عَلَيْهِ وَذَمِّ مَنْ عَلِمَهُ ثُمَّ نَسِيَهُ","52"],[245,"Chapter: The words of the prophet saws: \"A Group of my Ummah will continue to Prevail on the basis of the Truth, and They will not be Harmed by those who oppose them.\"","باب قَوْلِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «لاَ تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي ظَاهِرِينَ عَلَى الْحَقِّ لاَ يَضُرُّهُمْ مَنْ خَالَفَهُمْ»","53"],[254,"Chapter: Keeping animals' well being in mind when traveling, and the prohibition of halting in the road at the end of the night.","باب مُرَاعَاةِ مَصْلَحَةِ الدَّوَابِّ فِي السَّيْرِ وَالنَّهْىِ عَنِ التَّعْرِيسِ فِي الطَّرِيقِ","54"],[256,"Chapter: Travel is a kind of torment, and it is recommended for the traveler to hasten back to his family after finishing his business","باب السَّفَرِ قِطْعَةٌ مِنَ الْعَذَابِ وَاسْتِحْبَابِ تَعْجِيلِ الْمُسَافِرِ إِلَى أَهْلِهِ بَعْدَ قَضَاءِ شُغْلِهِ","55"],[257,"Chapter: It is disliked to enter at night when coming home from a journey","باب كَرَاهَةِ الطُّرُوقِ وَهُوَ الدُّخُولُ لَيْلاً لِمَنْ وَرَدَ مِنْ سَفَرٍ","56"]],"34":[[1,"Chapter: Hunting with trained dogs and arrows","باب الصَّيْدِ بِالْكِلاَبِ الْمُعَلَّمَةِ","1"],[14,"Chapter: If the game disappears, then is found afterwards","باب إِذَا غَابَ عَنْهُ الصَّيْدُ ثُمَّ وَجَدَهُ","2"],[17,"Chapter: The prohibition of eating any wild animal with Fangs and any bird with Talons","باب تَحْرِيمِ أَكْلِ كُلِّ ذِي نَابٍ مِنَ السِّبَاعِ وَكُلِّ ذِي مِخْلَبٍ مِنَ الطَّيْرِ","3"],[27,"Chapter: Permissibility of dead animals from the sea","باب إِبَاحَةِ مَيْتَاتِ الْبَحْرِ","4"],[34,"Chapter: The prohibition of eating the meat of domesticated donkeys","باب تَحْرِيمِ أَكْلِ لَحْمِ الْحُمُرِ الإِنْسِيَّةِ","5"],[51,"Chapter: The permissibility of eating horse meat","باب فِي أَكْلِ لُحُومِ الْخَيْلِ","6"],[56,"Chapter: The permissibility of eating the Dabb (mastigure)","باب إِبَاحَةِ الضَّبِّ","7"],[74,"Chapter: The permissibility of eating Locusts","باب إِبَاحَةِ الْجَرَادِ","8"],[77,"Chapter: The permissibility of eating Rabbit","باب إِبَاحَةِ الأَرْنَبِ","9"],[79,"Chapter: The permissibility of using things that help in hunting and pursuing the enemy, but throwing small pebbles is disliked","باب إِبَاحَةِ مَا يُسْتَعَانُ بِهِ عَلَى الاِصْطِيَادِ وَالْعَدُوِّ وَكَرَاهَةِ الْخَذْفِ","10"],[84,"Chapter: The command to be proficient in slaughtering and killing, and to sharpen the blade","باب الأَمْرِ بِإِحْسَانِ الذَّبْحِ وَالْقَتْلِ وَتَحْدِيدِ الشَّفْرَةِ","11"],[86,"Chapter: The prohibition of cornering animals in order to kill them (for sport)","باب النَّهْىِ عَنْ صَبْرِ الْبَهَائِمِ،","12"]],"35":[[1,"Chapter: The time for sacrifice","باب وَقْتِهَا","1"],[19,"Chapter: The age of sacrificial animals","باب سِنِّ الأُضْحِيَةِ","2"],[24,"Chapter: It is recommended to select a good animal for the sacrifice and to slaughter it oneself, not delegating it to anyone else, and to say the name of Allah, and to say the Takbir","باب اسْتِحْبَابِ الضَّحِيَّةِ وَذَبْحِهَا مُبَاشَرَةً بِلاَ تَوْكِيلٍ وَالتَّسْمِيَةِ وَالتَّكْبِيرِ","3"],[29,"Chapter: The permissibility of slaughtering with anything that makes the blood flow, except teeth and other bones","باب جَوَازِ الذَّبْحِ بِكُلِّ مَا أَنْهَرَ الدَّمَ إِلاَّ السِّنَّ وَالظُّفُرَ وَسَائِرَ الْعِظَامِ","4"],[34,"Chapter: The prohibition of eating sacrificial meat for more than three days, which applied at the beginning of Islam but was then abrogated, and now it is permissible to eat it as long as one wants.","باب بَيَانِ مَا كَانَ مِنَ النَّهْىِ عَنْ أَكْلِ لُحُومِ الأَضَاحِيِّ بَعْدَ ثَلاَثٍ فِي أَوَّلِ الإِسْلاَمِ وَبَيَانِ نَسْخِهِ وَإِبَاحَتِهِ إِلَى مَتَى شَاءَ","5"],[52,"Chapter: Fara' and 'Atirah","باب الْفَرَعِ وَالْعَتِيرَةِ","6"],[53,"Chapter: When the first ten days of Dhul-Hijjah begin, it is forbidden for the one who wants to offer a sacrifice to remove anything from his hair, nails or skin","باب نَهْيِ مَنْ دَخَلَ عَلَيْهِ عَشْرُ ذِي الْحِجَّةِ وَهُوَ مُرِيدُ التَّضْحِيَةِ أَنْ يَأْخُذَ مِنْ شَعْرِهِ أَوْ أَظْفَارِهِ شَيْئًا","7"],[60,"Chapter: The prohibition of slaughtering a sacrifice for anything other than Allah, and the one who does that is cursed","باب تَحْرِيمِ الذَّبْحِ لِغَيْرِ اللَّهِ تَعَالَى وَلَعْنِ فَاعِلِهِ","8"]],"36":[[1,"Chapter: The prohibition of Khamr, which may be made from the juice of grapes, dried dates, unripe dates, raisins and other things that intoxicate","باب تَحْرِيمِ الْخَمْرِ وَبَيَانِ أَنَّهَا تَكُونُ مِنْ عَصِيرِ الْعِنَبِ وَمِنَ التَّمْرِ وَالْبُسْرِ وَالزَّبِيبِ وَغَيْرِهَا مِمَّا يُسْكِرُ","1"],[14,"Chapter: The prohibition of making vinegar from wine","باب تَحْرِيمِ تَخْلِيلِ الْخَمْرِ","2"],[15,"Chapter: The prohibition of using Khamr as a remedy; It is not a remedy","باب تَحْرِيمِ التَّدَاوِي بِالْخَمْرِ","3"],[16,"Chapter: Everything that is taken from the date palm or grape vine and steeped is called Khamr","باب بَيَانِ أَنَّ جَمِيعَ مَا يُنْبَذُ مِمَّا يُتَّخَذُ مِنَ النَّخْلِ وَالْعِنَبِ يُسَمَّى خَمْرًا","4"],[19,"Chapter: It is disliked to make Nabidh by mixing dried dates and raisins","باب كَرَاهَةِ انْتِبَاذِ التَّمْرِ وَالزَّبِيبِ مَخْلُوطَيْنِ","5"],[40,"Chapter: The prohibition of making Nabidh in Al-Muzaffat, Ad-Dubba' (Gourds), Al-Hantam and An-Naqir; This has been abrogated and now it is permitted, so long as it does not become intoxicating","باب النَّهْيِ عَنْ الاِنْتِبَاذِ فِي الْمُزَفَّتِ وَالدُّبَّاءِ وَالْحَنْتَمِ وَالنَّقِيرِ وَبَيَانِ أَنَّهُ مَنْسُوخٌ وَأَنَّهُ الْيَوْمَ حَلاَلٌ مَا لَمْ يَصِرْ مُسْكِرًا","6"],[85,"Chapter: Every intoxicant is Khamr and all Khamr is Haram","باب بَيَانِ أَنَّ كُلَّ مُسْكِرٍ خَمْرٌ وَأَنَّ كُلَّ خَمْرٍ حَرَامٌ","7"],[96,"Chapter: The punishment of one who drinks Khamr if he does not repent from it: he will be denied it in the hereafter","باب عُقُوبَةِ مَنْ شَرِبَ الْخَمْرَ إِذَا لَمْ يَتُبْ مِنْهَا بِمَنْعِهِ إِيَّاهَا فِي الآخِرَةِ","8"],[100,"Chapter: The permissibility of Nabidh so long as it has not become strong and has not become intoxicating","باب إِبَاحَةِ النَّبِيذِ الَّذِي لَمْ يَشْتَدَّ وَلَمْ يَصِرْ مُسْكِرًا","9"],[112,"Chapter: The permissibility of drinking milk","باب جَوَازِ شُرْبِ اللَّبَنِ","10"],[116,"Chapter: Drinking Nabidh and covering vessels","باب فِي شُرْبِ النَّبِيذِ وَتَخْمِيرِ الإِنَاءِ","11"],[120,"Chapter: It is recommended to cover vessels, tie up waterskins, close doors and mention the name of Allah over them, extinguish lamps and fires when going to sleep, and keep children and animals in after maghrib","باب الأَمْرِ بِتَغْطِيَةِ الإِنَاءِ وَإِيكَاءِ السِّقَاءِ وَإِغْلاَقِ الأَبْوَابِ وَذِكْرِ اسْمِ اللَّهِ عَلَيْهَا وَإِطْفَاءِ السِّرَاجِ وَالنَّارِ عِنْدَ النَّوْمِ وَكَفِّ الصِّبْيَانِ وَالْمَوَاشِي بَعْدَ الْمَغْرِبِ","12"],[133,"Chapter: The etiquette of eating and drinking, and rulings thereon","باب آدَابِ الطَّعَامِ وَالشَّرَابِ وَأَحْكَامِهِمَا","13"],[148,"Chapter: Drinking while standing","باب كَرَاهِيَةِ الشُّرْبِ قَائِمًا","14"],[154,"Chapter: Drinking zamzam water while standing","باب فِي الشُّرْبِ مِنْ زَمْزَمَ قَائِمًا","15"],[159,"Chapter: It is disliked to breathe into the vessel, and it is recommended to take three breaths, outside the vessel","باب كَرَاهَةِ التَّنَفُّسِ فِي نَفْسِ الإِنَاءِ وَاسْتِحْبَابِ التَّنَفُّسِ ثَلاَثًا خَارِجَ الإِنَاءِ","16"],[163,"Chapter: It is recommended to pass water and milk etc., to the right of the one who drinks first","باب اسْتِحْبَابِ إِدَارَةِ الْمَاءِ وَاللَّبَنِ وَنَحْوِهِمَا عَنْ يَمِينِ الْمُبْتَدِئِ","17"],[168,"Chapter: It is recommended to lick one's fingers and wipe the bowl, and to eat a piece of food that is dropped after removing any dirt on it. It is disliked to wipe one's hand before licking it, because of the possibility that the blessing of the food may be in that remaining part. The Sunnah is to eat with three fingers","باب اسْتِحْبَابِ لَعْقِ الأَصَابِعِ وَالْقَصْعَةِ وَأَكْلِ اللُّقْمَةِ السَّاقِطَةِ بَعْدَ مَسْحِ مَا يُصِيبُهَا مِنْ أَذًى وَكَرَاهَةِ مَسْحِ الْيَدِ قَبْلَ لَعْقِهَا","18"],[183,"Chapter: What the guest should do if he is accompanied by someone who was not invited by the host; it is recommended for the host to give permission to the one who has accompanied the guest","باب مَا يَفْعَلُ الضَّيْفُ إِذَا تَبِعَهُ غَيْرُ مَنْ دَعَاهُ صَاحِبُ الطَّعَامِ وَاسْتِحْبَابُ إِذْنِ صَاحِبِ الطَّعَامِ لِلتَّابِعِ","19"],[187,"Chapter: It is permissible to take someone else to the house of one who you are certain will approve of that and will not mind. It is recommended to gather to eat","باب جَوَازِ اسْتِتْبَاعِهِ غَيْرَهُ إِلَى دَارِ مَنْ يَثِقُ بِرِضَاهُ بِذَلِكَ وَيَتَحَقَّقُهُ تَحَقُّقًا تَامًّا وَاسْتِحْبَابِ الاِجْتِمَاعِ عَلَى الطَّعَامِ","20"],[199,"Chapter: It is permissible to eat soup, and it is recommended to eat squash, And for the people eating together to show preference to one another even if they are guests, so long as the host does not object to that","باب جَوَازِ أَكْلِ الْمَرَقِ وَاسْتِحْبَابِ أَكْلِ الْيَقْطِينِ وَإِيثَارِ أَهْلِ الْمَائِدَةِ بَعْضِهِمْ بَعْضًا وَإِنْ كَانُوا ضِيفَانًا إِذَا لَمْ يَكْرَهْ ذَلِكَ صَاحِبُ الطَّعَامِ","21"],[202,"Chapter: It is recommended to take the stones out of dates, and it is recommended for the guest to pray for the host and to ask a righteous guest to supplicate, and he should respond to that request","باب اسْتِحْبَابِ وَضْعِ النَّوَى خَارِجَ التَّمْرِ وَاسْتِحْبَابِ دُعَاءِ الضَّيْفِ لأَهْلِ الطَّعَامِ وَطَلَبِ الدُّعَاءِ مِنَ الضَّيْفِ الصَّالِحِ وَإِجَابَتِهِ لِذَلِكَ","22"],[204,"Chapter: Eating cucumbers with fresh dates","باب أَكْلِ الْقِثَّاءِ بِالرُّطَبِ","23"],[205,"Chapter: It is recommended to be humble when eating, and how to sit","باب اسْتِحْبَابِ تَوَاضُعِ الآكِلِ وَصِفَةِ قُعُودِهِ","24"],[207,"Chapter: The prohibition of eating two dates etc., at a time when eating with a group, except with the permission of one's companions","باب نَهْيِ الآكِلِ مَعَ جَمَاعَةٍ عَنْ قِرَانِ تَمْرَتَيْنِ وَنَحْوِهِمَا فِي لُقْمَةٍ إِلاَّ بِإِذْنِ أَصْحَابِهِ","25"],[210,"Chapter: Storing dates and other provisions for one's children","باب فِي ادْخَالِ التَّمْرِ وَنَحْوِهِ مِنَ الأَقْوَاتِ لِلْعِيَالِ","26"],[212,"Chapter: The virtue of the dates of Al-Madinah","باب فَضْلِ تَمْرِ الْمَدِينَةِ","27"],[216,"Chapter: The virtue of truffles, and treating the eyes with them","باب فَضْلِ الْكَمْأَةِ وَمُدَاوَاةِ الْعَيْنِ بِهَا","28"],[223,"Chapter: The virtue of the black fruit from the Arak tree","باب فَضِيلَةِ الأَسْوَدِ مِنَ الْكَبَاثِ","29"],[224,"Chapter: The virtue of vinegar and using it as a condiment","باب فَضِيلَةِ الْخَلِّ وَالتَّأَدُّمِ بِهِ","30"],[230,"Chapter: It is permissible to eat garlic, but the one who is going to address prominent people should refrain from eating it, and the same applies to other, similar foods","باب إِبَاحَةِ أَكْلِ الثُّومِ وَأَنَّهُ يَنْبَغِي لِمَنْ أَرَادَ خِطَابِ الْكِبَارِ تَرْكُهُ وَكَذَا مَا فِي مَعْنَاهُ","31"],[233,"Chapter: Honoring guests and the virtue of showing preference to one's guest","باب إِكْرَامِ الضَّيْفِ وَفَضْلِ إِيثَارِهِ","32"],[241,"Chapter: The virtue of sharing a small amount of food, and the food of two is sufficient for three, and so on.","باب فَضِيلَةِ الْمُوَاسَاةِ فِي الطَّعَامِ الْقَلِيلِ وَأَنَّ طَعَامَ الاِثْنَيْنِ يَكْفِي الثَّلاَثَةَ وَنَحْوِ ذَلِكَ","33"],[246,"Chapter: The believer eats in one intestine and the disbeliever eats in seven intestines.","باب الْمُؤْمِنُ يَأْكُلُ فِي مِعًى وَاحِدٍ وَالْكَافِرُ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ","34"],[254,"Chapter: Do not criticize food","باب لاَ يَعِيبُ الطَّعَامَ","35"]],"37":[[1,"Chapter: The Prohibition Of Using Vessels Of Gold And Silver For Drinking Etc., For Men And Women","باب تَحْرِيمِ أَوَانِي الذَّهَبِ وَالْفِضَّةِ فِي الشُّرْبِ وَغَيْرِهِ عَلَى الرِّجَالِ وَالنِّسَاءِ","1"],[4,"Chapter: The Prohibition Of Using Vessels Of Gold And Silver For Men And Women, And Gold Rings And Silk For Men, But They Are Permissible For Women. Permissibility Of Silken Borders On Garments For Men, But It Should Not Be More Than Four Fingers Wide","باب تَحْرِيمِ اسْتِعْمَالِ إِنَاءِ الذَّهَبِ وَالْفِضَّةِ عَلَى الرِّجَالِ وَالنِّسَاءِ وَخَاتَمِ الذَّهَبِ وَالْحَرِيرِ عَلَى الرَّجُلِ وَإِبَاحَتِهِ لِلنِّسَاءِ وَإِبَاحَةِ الْعَلَمِ وَنَحْوِهِ لِلرَّجُلِ مَا لَمْ يَزِدْ عَلَى أَرْبَعِ أَصَابِعَ","2"],[44,"Chapter: The Permissibility Of Wearing Silk For Men, If A Man Has A Skin Disease Or Similar Problem","باب إِبَاحَةِ لُبْسِ الْحَرِيرِ لِلرَّجُلِ إِذَا كَانَ بِهِ حِكَّةٌ أَوْ نَحْوُهَا","3"],[49,"Chapter: The Prohibition Of A Man Wearing A Garment Dyed With Safflower","باب النَّهْىِ عَنْ لُبْسِ الرَّجُلِ الثَّوْبَ الْمُعَصْفَرَ،","4"],[55,"Chapter: The Virtue Of Wearing The Hibarah","باب فَضْلِ لِبَاسِ ثِيَابِ الْحِبَرَةِ","5"],[57,"Chapter: Humility In Dress And Sticking To Coarse And Simple Clothes, Furnishings Etc., Permissibility Of Wearing Clothes Made From Camel Hair And Those On Which There Are Markings","بَاب التَّوَاضُعِ فِي اللِّبَاسِ وَالِاقْتِصَارِ عَلَى الْغَلِيظِ مِنْهُ وَالْيَسِيرِ فِي اللِّبَاسِ وَالْفِرَاشِ وَغَيْرِهِمَا","6"],[64,"Chapter: The Permissibility Of Using Blankets","باب جَوَازِ اتِّخَاذِ الأَنْمَاطِ","7"],[67,"Chapter: It Is Disliked To Have More Furniture And Bedding Than One Needs","باب كَرَاهَةِ مَا زَادَ عَلَى الْحَاجَةِ مِنَ الْفِرَاشِ وَاللِّبَاسِ","8"],[68,"Chapter: The Prohibition Of Letting One's Garment Drag Out Of Pride, And The Extent To Which It Is Permissible To Let It Hang Down And The Extent To Which It Is Recommended","باب تَحْرِيمِ جَرِّ الثَّوْبِ خُيَلاَءَ وَبَيَانِ حَدِّ مَا يَجُوزُ إِرْخَاؤُهُ إِلَيْهِ وَمَا يُسْتَحَبّ","9"],[80,"Chapter: The Prohibition Against Strutting With Pride, And Being Amazed With One's Clothes","باب تَحْرِيمِ التَّبَخْتُرِ فِي الْمَشْىِ مَعَ إِعْجَابِهِ بِثِيَابِهِ","10"],[85,"Chapter: The Prohibition Of Gold Rings For Men, And Abrogation Of Their Allowance After The Beginning Of Islam","بَاب تَحْرِيمِ خَاتَمِ الذَّهَبِ عَلَى الرِّجَالِ وَنَسْخِ مَا كَانَ مِنْ إِبَاحَتِهِ فِي أَوَّلِ الْإِسْلَامِ","11"],[91,"Chapter: The Prophet (SAW) Wore A Ring Of Silver On Which Was Inscribed The Words Muhammad Rasul Allah (Muhammad the Messenger of Allah), And The Caliphs Wore It After He Died","بَاب لُبْسِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاتَمًا مِنْ وَرِقٍ نَقْشُهُ مُحَمَّدٌ رَسُولُ اللَّهِ وَلُبْسِ الْخُلَفَاءِ لَهُ مِنْ بَعْدِهِ","12"],[95,"Chapter: The Prophet (SAW) Acquired A Ring When He Wanted To Send Letters To The Non-Arabs","باب فِي اتِّخَاذِ النَّبِيِّ صلى الله عليه وسلم خَاتَمًا لَمَّا أَرَادَ أَنْ يَكْتُبَ إِلَى الْعَجَمِ","13"],[98,"Chapter: Discarding Rings","باب فِي طَرْحِ الْخَوَاتِمِ .","14"],[101,"Chapter: Silver Ring With An Abyssinian Stone","باب فِي خَاتَمِ الْوَرِقِ فَصُّهُ حَبَشِيٌّ .","15"],[104,"Chapter: Wearing Rings On The Little Finger","باب فِي لُبْسِ الْخَاتَمِ فِي الْخِنْصَرِ مِنَ الْيَدِ .","16"],[105,"Chapter: The Prohibition Of Wearing Rings On The Middle Finger And The One That Is Next To It","باب النَّهْىِ عَنِ التَّخَتُّمِ، فِي الْوُسْطَى وَالَّتِي تَلِيهَا .","17"],[109,"Chapter: It Is Recommended To Wear Sandals et","بَاب اسْتِحْبَابِ لُبْسِ النِّعَالِ وَمَا فِي مَعْنَاهَا","18"],[110,"Chapter: It Is Recommended To Put Shoes On The Right Foot First, And To Take Them Off From The Left Foot First, And It Is Disliked To Walk In One Shoe","بَاب اسْتِحْبَابِ لُبْسِ النَّعْلِ فِي الْيُمْنَى أَوَّلًا وَالْخَلْعِ مِنْ الْيُسْرَى أَوَّلًا وَكَرَاهَةِ الْمَشْيِ فِي نَعْلٍ وَاحِدَةٍ","19"],[114,"Chapter: The Prohibition Of Ishtimal As-Samma' (Wrapping Oneself Up Entirely In One's Garment With No Room For The Arms To Emerge), And Al-Ihtiba' (Wrapping Oneself Up) In A Single Garment With The Legs Drawn Up To The Belly Exposing Part Of The 'Awrah","باب النَّهْىِ عَنِ اشْتِمَالِ الصَّمَّاءِ، وَالاِحْتِبَاءِ، فِي ثَوْبٍ وَاحِدٍ .","20"],[116,"Chapter: The Ruling On Lying On Ones Back With One Leg On Top Of The Other","باب فِي مَنْعِ الاِسْتِلْقَاءِ عَلَى الظَّهْرِ وَوَضْعِ إِحْدَى الرِّجْلَيْنِ عَلَى الأُخْرَى .","21"],[119,"Chapter: The Permissibility Of Lying Down And Placing One Leg On Top Of The Other","باب فِي إِبَاحَةِ الاِسْتِلْقَاءِ وَوَضْعِ إِحْدَى الرِّجْلَيْنِ عَلَى الأُخْرَى .","22"],[121,"Chapter: The Prohibition Of A Man Dyeing From With Saffron","بَاب نَهْيِ الرَّجُلِ عَنْ التَّزَعْفُرِ","23"],[123,"Chapter: It Is Recommended To Dye White Hair With Yellow Or Red Dye, But Black Dye Is Haram","بَاب اسْتِحْبَابِ خِضَابِ الشَّيْبِ بِصُفْرَةٍ أَوْ حُمْرَةٍ وَتَحْرِيمِهِ بِالسَّوَادِ","24"],[125,"Chapter: Differing From The Jews With Regard To Dyeing","باب فِي مُخَالَفَةِ الْيَهُودِ فِي الصَّبْغِ .","25"],[126,"Chapter: The Prohibition Of Making Images Of Living Beings, And The Prohibition Of Using Images That Are Not Subjected To Disrespect In Furnishings And The Like; The Angels (Peace Be Upon Them) Do Not Enter A House In Which There Is An Image Or A Dog","بَاب تَحْرِيمِ تَصْوِيرِ صُورَةِ الْحَيَوَانِ وَتَحْرِيمِ اتِّخَاذِ مَا فِيهِ صُورَةٌ غَيْرُ مُمْتَهَنَةٍ بِالْفَرْشِ وَنَحْوِهِ","26"],[157,"Chapter: It Is Disliked To Take Dogs And Bells On A Journey","باب كَرَاهَةِ الْكَلْبِ وَالْجَرَسِ فِي السَّفَرِ .","27"],[160,"Chapter: It Is Disliked To Hang Garlands On The Necks Of Camels","باب كَرَاهَةِ قِلاَدَةِ الْوَتَرِ فِي رَقَبَةِ الْبَعِيرِ .","28"],[161,"Chapter: The Prohibition Of Striking Or Branding Animals On The Face","باب النَّهْىِ عَنْ ضَرْبِ الْحَيَوَانِ، فِي وَجْهِهِ وَوَسْمِهِ فِيهِ .","29"],[165,"Chapter: The Permissibility Of Branding Animals Anywhere But On The Face, And This Is Recommended In The Case Of Animals Given As Zakat Ot Jizyah","بَاب جَوَازِ وَسْمِ الْحَيَوَانِ غَيْرِ الْآدَمِيِّ فِي غَيْرِ الْوَجْهِ وَنَدْبِهِ فِي نَعَمْ الزَّكَاةِ وَالْجِزْيَةِ","30"],[169,"Chapter: It Is Disliked To Shave Part Of The Head And Leave Part","باب كَرَاهَةِ الْقَزَعِ .","31"],[173,"Chapter: The Prohibition Of Sitting In The Street; And Giving The Street Its Rights","باب النَّهْىِ عَنِ الْجُلُوسِ، فِي الطُّرُقَاتِ وَإِعْطَاءِ الطَّرِيقِ حَقَّهُ .","32"],[175,"Chapter: The Prohibition Adding Hair Extensions, Having Them Added, Tattooing, Being Tattooed, An-Namisah, Al-Mutanamisah, Separating Teeth, And Changing The Creation Of Allah","بَاب تَحْرِيمِ فِعْلِ الْوَاصِلَةِ وَالْمُسْتَوْصِلَةِ وَالْوَاشِمَةِ وَالْمُسْتَوْشِمَةِ وَالنَّامِصَةِ وَالْمُتَنَمِّصَةِ وَالْمُتَفَلِّجَاتِ وَالْمُغَيِّرَاتِ خَلْقِ اللَّهِ","33"],[190,"Chapter: Women Who Are Clothed Yet Naked, Turning Away From Righteousness And Leading Others Astray","باب النِّسَاءِ الْكَاسِيَاتِ الْعَارِيَاتِ الْمَائِلاَتِ الْمُمِيلاَتِ .","34"],[191,"Chapter: The Prohibition Of Wearing A Garment Of Falsehood Etc., And Pretending To Have That Which Has Not Been Given To One","باب النَّهْىِ عَنِ التَّزْوِيرِ، فِي اللِّبَاسِ وَغَيْرِهِ وَالتَّشَبُّعِ بِمَا لَمْ يُعْطَ .","35"]],"38":[[1,"Chapter: The Prohibition Of Taking The Kunyah Abul-Qasim, And The Names Which Are Recommended","باب النَّهْىِ عَنِ التَّكَنِّي، بِأَبِي الْقَاسِمِ وَبَيَانِ مَا يُسْتَحَبُّ مِنَ الأَسْمَاءِ .","1"],[14,"Chapter: It Is Disliked To Use Objectionable Names And Names Such As Nafi' (Beneficial) Etc","باب كَرَاهَةِ التَّسْمِيَةِ بِالأَسْمَاءِ الْقَبِيحَةِ وَبِنَافِعٍ وَنَحْوِهِ .","2"],[19,"Chapter: It Is Recommended To Change Bad Names To Good Names, And To Change The Name Barrah To Zainab, Juwayriyah And The Like","بَاب اسْتِحْبَابِ تَغْيِيرِ الِاسْمِ الْقَبِيحِ إِلَى حَسَنٍ وَتَغْيِيرِ اسْمِ بَرَّةَ إِلَى زَيْنَبَ وَجُوَيْرِيَةَ وَنَحْوِهِمَا","3"],[25,"Chapter: The Prohibition Of The Names Malik Al-Amlak Or Malik Al-Muluk \"King Of Kings\"","باب تَحْرِيمِ التَّسَمِّي بِمَلِكِ الأَمْلاَكِ وَبِمَلِكِ الْمُلُوكِ","4"],[27,"Chapter: It Is Recommended To Perform Tahnik For The Newborn When He Is Born And To Take Him To A Righteous Man To Perform Tahnik For Him; It Is Permissible To Name Him On The Day He Is Born, And It Is Recommended To Use The Names 'Abdullah, Ibrahim, And The Names Of All Other Prophets, Peace Be Upon Them","بَاب اسْتِحْبَابِ تَحْنِيكِ الْمَوْلُودِ عِنْدَ وِلَادَتِهِ وَحَمْلِهِ إِلَى صَالِحٍ يُحَنِّكُهُ وَجَوَازِ تَسْمِيَتِهِ يَوْمَ وِلَادَتِهِ وَاسْتِحْبَابِ التَّسْمِيَةِ بِعَبْدِ اللَّهِ وَإِبْرَاهِيمَ وَسَائِرِ أَسْمَاءِ الْأَنْبِيَاءِ عَلَيْهِمْ السَّلَام","5"],[38,"Chapter: It Is Permissible To Say: \"O My Son\" To Someone Other Than One's Son, And It Is Recommended To Speak Kindly","باب جَوَازِ قَوْلِهِ لِغَيْرِ ابْنِهِ يَا بُنَىَّ وَاسْتِحْبَابِهِ لِلْمُلاَطَفَةِ","6"],[41,"Chapter: Seeking Permission To Enter A House","باب الاِسْتِئْذَانِ","7"],[50,"Chapter: It Is Disliked For The Person Who Is Seeking Permission To Say \"Me\" When Asked \"Who Is It?\"","باب كَرَاهَةِ قَوْلِ الْمُسْتَأْذِنِ أَنَا إِذَا قِيلَ مَنْ هَذَا","8"],[53,"Chapter: The Prohibition Of Looking Into A House","باب تَحْرِيمِ النَّظَرِ فِي بَيْتِ غَيْرِهِ","9"],[59,"Chapter: An Accidental Glance","باب نَظَرِ الْفَجْأَةِ","10"]],"39":[[1,"Chapter: The One Who Is Riding Should Greet The One Who Is Walking, And The Smaller Group Should Greet The Larger Group","باب يُسَلِّمُ الرَّاكِبُ عَلَى الْمَاشِي وَالْقَلِيلُ عَلَى الْكَثِيرِ","1"],[2,"Chapter: One Of The Duties Of Sitting In The Street Is To Return Salam","باب مِنْ حَقِّ الْجُلُوسِ عَلَى الطَّرِيقِ رَدُّ السَّلاَمِ","2"],[5,"Chapter: One Of The Rights Of One Muslim Over Another Is (The Greeting Of) Salam","باب مِنْ حَقِّ الْمُسْلِمِ لِلْمُسْلِمِ رَدُّ السَّلاَمِ","3"],[7,"Chapter: The Prohibition Of Initiating The Greeting With The People Of The Book, And How To Respond To Them","باب النَّهْىِ عَنِ ابْتِدَاءِ، أَهْلِ الْكِتَابِ بِالسَّلاَمِ وَكَيْفَ يَرُدُّ عَلَيْهِمْ","4"],[18,"Chapter: It Is Recommended To Greet Children With Salam","باب اسْتِحْبَابِ السَّلاَمِ عَلَى الصِّبْيَانِ","5"],[21,"Chapter: It Is Permissible To Give Permission To Enter By Raising The Curtain Or Giving Some Other Sign","باب جَوَازِ جَعْلِ الإِذْنِ رَفْعَ حِجَابٍ أَوْ نَحْوَهُ مِنَ الْعَلاَمَاتِ","6"],[23,"Chapter: The Permissibility Of Women Going Out To Relieve Themselves","باب إِبَاحَةُ الْخُرُوجِ لِلنِّسَاءِ لِقَضَاءِ حَاجَةِ الإِنْسَانِ","7"],[27,"Chapter: The Prohibition Of Being Alone With A Non-Mahram Woman Or Entering Upon Her","باب تَحْرِيمِ الْخَلْوَةِ بِالأَجْنَبِيَّةِ وَالدُّخُولِ عَلَيْهَا","8"],[32,"Chapter: It Is Recommended For The One Who Is Seen Alone With A Woman Who Is His Wife Or Mahram, To Say; \"This Is So-And-So,' To Ward off Suspicion","باب بَيَانِ أَنَّهُ يُسْتَحَبُّ لِمَنْ رُئِيَ خَالِيًا بِامْرَأَةٍ وَكَانَتْ زَوْجَةً أَوْ مَحْرَمًا لَهُ","9"],[35,"Chapter: If A Man Comes To A Gathering And Finds A Space. Let Him Sit There, Otherwise Let Him Sit Behind Them","باب مَنْ أَتَى مَجْلِسًا فَوَجَدَ فُرْجَةً فَجَلَسَ فِيهَا وَإِلاَّ وَرَاءَهُمْ","10"],[37,"Chapter: The Prohibition Of Making A Man Get Up From A Place That He Reached First","باب تَحْرِيمِ إِقَامَةِ الإِنْسَانِ مِنْ مَوْضِعِهِ الْمُبَاحِ الَّذِي سَبَقَ إِلَيْهِ","11"],[43,"Chapter: If A Man Gets Up From His Spot Then Comes Back To It, He Has More Right To It","باب إِذَا قَامَ مِنْ مَجْلِسِهِ ثُمَّ عَادَ فَهُوَ أَحَقُّ بِهِ","12"],[44,"Chapter: Forbidding A Hermaphrodite From Entering Upon Non-Mahram Women","باب مَنْعِ الْمُخَنَّثِ مِنَ الدُّخُولِ عَلَى النِّسَاءِ الأَجَانِبِ","13"],[46,"Chapter: It Is Permissible To Seat A Non-Mahram Woman Behind One (On A Mount) If She Is Exhausted On The Road","باب جَوَازِ إِرْدَافِ الْمَرْأَةِ الأَجْنَبِيَّةِ إِذَا أَعْيَتْ فِي الطَّرِيقِ","14"],[48,"Chapter: The Prohibition Of Two People Conversing Privately To The Exclusion Of A Third Without His Consent","باب تَحْرِيمِ مُنَاجَاةِ الاِثْنَيْنِ دُونَ الثَّالِثِ بِغَيْرِ رِضَاهُ","15"],[53,"Chapter: Medicine, Sickness And Ruqyah","باب الطِّبِّ وَالْمَرَضِ وَالرُّقَى","16"],[57,"Chapter: Witchcraft","باب السِّحْرِ","17"],[59,"Chapter: Poison","باب السَّمِّ","18"],[61,"Chapter: It Is Recommended To Recite Ruqyah For One Who Is Sick","باب اسْتِحْبَابِ رُقْيَةِ الْمَرِيضِ","19"],[68,"Chapter: Reciting Al-Mu'awwidhat As Ruqyah For The Sick, And Blowing Over Them","باب رُقْيَةِ الْمَرِيضِ بِالْمُعَوِّذَاتِ وَالنَّفْثِ","20"],[71,"Chapter: It Is Recommended To Recite Ruqyah For The Evil Eye, Pustules, And Stings","باب اسْتِحْبَابِ الرُّقْيَةِ مِنَ الْعَيْنِ وَالنَّمْلَةِ وَالْحُمَةِ وَالنَّظْرَةِ","21"],[86,"Chapter: There Is Nothing Wrong With Ruqyah That Does Not Involve Shirk","باب لاَ بَأْسَ بِالرُّقَى مَا لَمْ يَكُنْ فِيهِ شِرْكٌ","22"],[87,"Chapter: The Permissibility Of Accepting A Reward For Reciting Ruqyah With Qur'an And Supplications","باب جَوَازِ أَخْذِ الأُجْرَةِ عَلَى الرُّقْيَةِ بِالْقُرْآنِ وَالأَذْكَارِ","23"],[91,"Chapter: It Is Recommended To Put Ones Hand On The Site Of The Pain When Supplicating","باب اسْتِحْبَابِ وَضْعِ يَدِهِ عَلَى مَوْضِعِ الأَلَمِ مَعَ الدُّعَاءِ","24"],[92,"Chapter: Seeking Refuge With Allah From The Devil Who Whispers During Prayer","باب التَّعَوُّذِ مِنْ شَيْطَانِ الْوَسْوَسَةِ فِي الصَّلاَةِ","25"],[95,"Chapter: For Every Disease There Is A Remedy, And It Is Recommended To Treat Disease","باب لِكُلِّ دَاءٍ دَوَاءٌ وَاسْتِحْبَابُ التَّدَاوِي","26"],[115,"Chapter: It Is Disliked To Administer Medicine In The Side Of The Mouth Forcibly","باب كَرَاهَةِ التَّدَاوِي بِاللَّدُودِ","27"],[116,"Chapter: Treatment With Indian Aloeswood, Which Is Costmary","باب التَّدَاوِي بِالْعُودِ الْهِنْدِيِّ وَهُوَ الْكُسْتُ","28"],[118,"Chapter: Healing Sickness With The Black Seed","باب التَّدَاوِي بِالْحَبَّةِ السَّوْدَاءِ","29"],[121,"Chapter: Talbinah Gives Comfort To The Sick Person","باب التَّلْبِينَةُ مَجَمَّةٌ لِفُؤَادِ الْمَرِيضِ","30"],[122,"Chapter: Treating Sickness With A Drink Of Honey","باب التَّدَاوِي بِسَقْىِ الْعَسَلِ","31"],[124,"Chapter: The Plague, Ill Omens, Soothsaying And The Like","باب الطَّاعُونِ وَالطِّيَرَةِ وَالْكَهَانَةِ وَنَحْوِهَا","32"],[140,"Chapter: There Is No 'Adwa, No Tiyarah (Evil Omens), No Hamah. No Safar, No Nawa', And No Ghoul, And No Sick Camel Should Be Brought To A Healthy Camel","باب لاَ عَدْوَى وَلاَ طِيَرَةَ وَلاَ هَامَةَ وَلاَ صَفَرَ","33"],[150,"Chapter: (Evil) Omens And Al-Fa'l, And That Which May Be Regarded As Inauspicious","باب الطِّيَرَةِ وَالْفَأْلِ وَمَا يَكُونُ فِيهِ الشُّؤْمُ","34"],[165,"Chapter: The Prohibition Of Soothsaying And Going To Soothsayers","باب تَحْرِيمِ الْكِهَانَةِ وَإِتْيَانِ الْكُهَّانِ","35"],[174,"Chapter: Avoiding Lepers Etc.","باب اجْتِنَابِ الْمَجْذُومِ وَنَحْوِهِ","36"],[175,"Chapter: Killing Snakes Etc.","باب قَتْلِ الْحَيَّاتِ وَغَيْرِهَا","37"],[193,"Chapter: It Is Recommended To Kill Geckos","باب اسْتِحْبَابِ قَتْلِ الْوَزَغِ","38"],[200,"Chapter: The Prohibition Of Killing Ants","باب النَّهْىِ عَنْ قَتْلِ النَّمْلِ،","39"],[203,"Chapter: The Prohibition Of Killing Cats","باب تَحْرِيمِ قَتْلِ الْهِرَّةِ","40"],[210,"Chapter: The Virtue Of Giving Food And Water To Animals Which Are Unlawful To Eat","باب فَضْلِ سَاقِي الْبَهَائِمِ الْمُحْتَرَمَةِ وَإِطْعَامِهَا","41"]],"40":[[1,"Chapter: The Prohibition Of Cursing Time","باب النَّهْىِ عَنْ سَبِّ الدَّهْرِ،","1"],[6,"Chapter: It Is Disliked To Call Grapes Karm","باب كَرَاهَةِ تَسْمِيَةِ الْعِنَبِ كَرْمًا","2"],[13,"Chapter: Ruling On Using The Words 'Abd And Amah (For Slaves) And Mawla And Sayyid (For Masters)","باب حُكْمِ إِطْلاَقِ لَفْظَةِ الْعَبْدِ وَالأَمَةِ وَالْمَوْلَى وَالسَّيِّدِ","3"],[17,"Chapter: It Is Disliked For A Man To Say: \"Khabuthat Nafsi\" (I Feel Bad)","باب كَرَاهَةِ قَوْلِ الإِنْسَانِ خَبُثَتْ نَفْسِي","4"],[20,"Chapter: Using Musk, Which Is The Best Of Perfume. It Is Disliked To Refuse A Gift Of Scent Or Perfume","باب اسْتِعْمَالِ الْمِسْكِ وَأَنَّهُ أَطْيَبُ الطِّيبِ وَكَرَاهَةِ رَدِّ الرَّيْحَانِ وَالطِّيبِ","5"]],"41":[[1,"Chapter:","باب","1"],[11,"Chapter: The Prohibition Of Playing Nardashir","باب تَحْرِيمِ اللَّعِبِ بِالنَّرْدَشِيرِ","2"]],"42":[[23,"Chapter: The Words Of The Prophet (SAW): \"Whoever Sees Me In A Dream Has Indeed Seen Me.\"","باب قَوْلِ النَّبِيِّ صلى الله عليه وسلم \" مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي \"","1"],[29,"Chapter: No One Should Speak Of How The Shaitan Toyed With Him In His Sleep","باب لاَ يُخْبِرُ بِتَلَعُّبِ الشَّيْطَانِ بِهِ فِي الْمَنَامِ","2"],[32,"Chapter: Interpretation Of Dreams","باب فِي تَأْوِيلِ الرُّؤْيَا","3"],[36,"Chapter: The Dreams Of The Prophet (SAW)","باب رُؤْيَا النَّبِيِّ صلى الله عليه وسلم","4"]],"43":[[1,"Chapter: The Superiority Of The Prophet's Lineage, And The Stone That Greeted Him Before His Prophethood","باب فَضْلِ نَسَبِ النَّبِيِّ صلى الله عليه وسلم وَتَسْلِيمِ الْحَجَرِ عَلَيْهِ قَبْلَ النُّبُوَّةِ","1"],[3,"Chapter: The Superiority Of Our Prophet (SAW) Over All Of Creation","باب تَفْضِيلِ نَبِيِّنَا صلى الله عليه وسلم عَلَى جَمِيعِ الْخَلاَئِقِ","2"],[4,"Chapter: The Miracles Of The Prophet (SAW)","باب فِي مُعْجِزَاتِ النَّبِيِّ صلى الله عليه وسلم","3"],[13,"Chapter: He Put His Trust In Allah And Allah Protected Him From The People","باب تَوَكُّلِهِ عَلَى اللَّهِ وَعِصْمَةِ اللَّهِ تَعَالَى لَهُ مِنَ النَّاسِ","4"],[16,"Chapter: The Likeness Of The Guidance And Knowledge With Which The Prophet (SAW) Was Sent","باب بَيَانِ مَثَلِ مَا بُعِثَ بِهِ النَّبِيُّ صلى الله عليه وسلم مِنَ الْهُدَى وَالْعِلْمِ","5"],[17,"Chapter: His Compassion Towards His Ummah, And His Intense Concern To Warn Them Against That Which May Harm Them","باب شَفَقَتِهِ صلى الله عليه وسلم عَلَى أُمَّتِهِ وَمُبَالَغَتِهِ فِي تَحْذِيرِهِمْ مِمَّا يَضُرُّهُمْ","6"],[22,"Chapter: He (SAW) Was The Seal Of The Prophets","باب ذِكْرِ كَوْنِهِ صلى الله عليه وسلم خَاتَمَ النَّبِيِّينَ","7"],[28,"Chapter: When Allah Wants To Show Mercy To A Nation, He takes Their Prophet Before Them","باب إِذَا أَرَادَ اللَّهُ تَعَالَى رَحْمَةَ أُمَّةٍ قَبَضَ نَبِيَّهَا قَبْلَهَا","8"],[29,"Chapter: The Cistern Of Our Prophet (SAW) And Its Attributes","باب إِثْبَاتِ حَوْضِ نَبِيِّنَا صلى الله عليه وسلم وَصِفَاتِهِ","9"],[63,"Chapter: The Angels Fought Alongside Him (SAW)","باب فِي قِتَالِ جِبْرِيلَ وَمِيكَائِيلَ عَنِ النَّبِيِّ صلى الله عليه وسلم يَوْمَ أُحُدٍ","10"],[65,"Chapter: His Courage","باب فِي شَجَاعَةِ النَّبِيِّ صلى الله عليه وسلم وَتَقَدُّمِهِ لِلْحَرْبِ","11"],[68,"Chapter: His Generosity","باب كَانَ النَّبِيُّ صلى الله عليه وسلم أَجْوَدَ النَّاسِ بِالْخَيْرِ مِنَ الرِّيحِ الْمُرْسَلَةِ","12"],[70,"Chapter: His Good Manners","باب كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم أَحْسَنَ النَّاسِ خُلُقًا","13"],[76,"Chapter: His Generosity","باب مَا سُئِلَ رَسُولُ اللَّهِ صلى الله عليه وسلم شَيْئًا قَطُّ فَقَالَ لاَ وَكَثْرَةِ عَطَائِهِ","14"],[83,"Chapter: His Compassion Towards Children And His Humbleness, And The Virtue Of That","باب رَحْمَتِهِ صلى الله عليه وسلم الصِّبْيَانَ وَالْعِيَالَ وَتَوَاضُعِهِ وَفَضْلِ ذَلِكَ","15"],[90,"Chapter: His Great Modesty","باب كَثْرَةِ حَيَائِهِ صلى الله عليه وسلم .","16"],[93,"Chapter: His Smile And Easy Going Attitude","باب تَبَسُّمِهِ صلى الله عليه وسلم وَحُسْنِ عِشْرَتِهِ .","17"],[94,"Chapter: His Compassion Towards Women And His Command To Treat Them Kindly","باب فِي رَحْمَةِ النَّبِيِّ صلى الله عليه وسلم لِلنِّسَاءِ وَأَمْرِ السُّوَّاقِ مَطَايَاهُنَّ بِالرِّفْقِ","18"],[100,"Chapter: His Closeness To The People, Their Seeking Blessing From Him And His Humility Towards Them","باب قُرْبِ النَّبِيِّ عَلَيْهِ السَّلاَمُ مِنَ النَّاسِ وَتَبَرُّكِهِمْ بِهِ .","19"],[103,"Chapter: His Avoidance Of Sin, His Choosing The Easier Of Permissible Things, And His Vengeance For The Sake Of Allah If His Sacred Limits Were Transgressed","باب مُبَاعَدَتِهِ صلى الله عليه وسلم لِلآثَامِ وَاخْتِيَارِهِ مِنَ الْمُبَاحِ أَسْهَلَهُ وَانْتِقَامِهِ ل","20"],[110,"Chapter: His Good Fragrance And Soft Touch, And Seeking Blessing From His Touch","باب طِيبِ رَائِحَةِ النَّبِيِّ صلى الله عليه وسلم وَلِينِ مَسِّهِ وَالتَّبَرُّكِ بِمَسْحِهِ .","21"],[113,"Chapter: The Fragrance Of His Sweat, And Seeking Blessing Therefrom","باب طِيبِ عَرَقِ النَّبِيِّ صلى الله عليه وسلم وَالتَّبَرُّكِ بِهِ .","22"],[116,"Chapter: The Prophet (SAW) Sweated When It Was Cold, And When The Revelation Came To Him","باب عَرَقِ النَّبِيِّ صلى الله عليه وسلم فِي الْبَرْدِ وَحِينَ يَأْتِيهِ الْوَحْىُ .","23"],[120,"Chapter: Description Of His Hair, Attributes And Appearance","باب فِي سَدْلِ النَّبِيِّ صلى الله عليه وسلم شَعْرَهُ وَفَرْقِهِ .","24"],[122,"Chapter: Description Of The Prophet (SAW); He Was The Most Handsome Of People","باب فِي صِفَةِ النَّبِيِّ صلى الله عليه وسلم وَأَنَّهُ كَانَ أَحْسَنَ النَّاسِ وَجْهًا .","25"],[125,"Chapter: Description Of His Hair","باب صِفَةِ شَعْرِ النَّبِيِّ صلى الله عليه وسلم .","26"],[128,"Chapter: The Mouth, Eyes And Heels Of The Prophet (SAW)","باب فِي صِفَةِ فَمِ النَّبِيِّ صلى الله عليه وسلم وَعَيْنَيْهِ وَعَقِبَيْهِ .","27"],[129,"Chapter: The Prophet (SAW) Was White With An Elegant Face","باب كَانَ النَّبِيُّ صلى الله عليه وسلم أَبْيَضَ مَلِيحَ الْوَجْهِ .","28"],[131,"Chapter: His Grey Hairs","باب شَيْبِهِ صلى الله عليه وسلم .","29"],[143,"Chapter: The Seal Of Prophethood, Its Attributes And Its Location On The Body Of The Prophet (SAW)","باب إِثْبَاتِ خَاتَمِ النُّبُوَّةِ وَصِفَتِهِ وَمَحِلِّهِ مِنْ جَسَدِهِ صلى الله عليه وسلم .","30"],[147,"Chapter: How Long He (SAW) Lived, And How Long He Stayed In Makkah And Al-Madinah","باب فِي صِفَةِ النَّبِيِّ صلى الله عليه وسلم وَمَبْعَثِهِ وَسِنِّهِ .","31"],[149,"Chapter: The Age Of The Prophet (SAW) When He Died","باب كَمْ سِنُّ النَّبِيِّ صلى الله عليه وسلم يَوْمَ قُبِضَ .","32"],[152,"Chapter: How Long Did The Prophet ft Stay In Makkah And Al-Madinah?","باب كَمْ أَقَامَ النَّبِيُّ صلى الله عليه وسلم بِمَكَّةَ وَالْمَدِينَةِ .","33"],[163,"Chapter: His Names","باب فِي أَسْمَائِهِ صلى الله عليه وسلم .","34"],[167,"Chapter: His Knowledge Of Allah And His Great Fear Of Him","باب عِلْمِهِ صلى الله عليه وسلم بِاللَّهِ تَعَالَى وَشِدَّةِ خَشْيَتِهِ .","35"],[170,"Chapter: The Obligation To Follow Him (SAW)","باب وُجُوبِ اتِّبَاعِهِ صلى الله عليه وسلم .","36"],[171,"Chapter: Respecting Him And Not Asking Him Unnecessary Questions","باب تَوْقِيرِهِ صلى الله عليه وسلم وَتَرْكِ إِكْثَارِ سُؤَالِهِ عَمَّا لاَ ضَرُورَةَ إِلَيْهِ أَوْ لاَ يَت","37"],[184,"Chapter: The Obligation To Obey What He Says With Regard To Matters Of Religion, But Not What He Says With Regard To Worldly Matters","باب وُجُوبِ امْتِثَالِ مَا قَالَهُ شَرْعًا دُونَ مَا ذَكَرَهُ صلى الله عليه وسلم مِنْ مَعَايِشِ الدُّنْيَا","38"],[187,"Chapter: The Virtue Of Looking At Him And Longing To See Him","باب فَضْلِ النَّظَرِ إِلَيْهِ صلى الله عليه وسلم وَتَمَنِّيهِ","39"],[188,"Chapter: The Virtues Of Eisa, Peace Be Upon Him","باب فَضَائِلِ عِيسَى عَلَيْهِ السَّلاَمُ","40"],[196,"Chapter: The Virtues Of Ibrahim, Peace Be Upon Him","باب مِنْ فَضَائِلِ إِبْرَاهِيمَ الْخَلِيلِ صلى الله عليه وسلم","41"],[204,"Chapter: The Virtues Of Musa, Peace Be Upon Him","باب مِنْ فَضَائِلِ مُوسَى صلى الله عليه وسلم","42"],[217,"Chapter: Yunus, Peace Be Upon Him, And The Words Of The Prophet (SAW): \"No One Should Say: I Am Better Than Yunus Bin Matta.\"","باب فِي ذِكْرِ يُونُسَ عَلَيْهِ السَّلاَمُ وَقَوْلِ النَّبِيِّ صلى الله عليه وسلم \" لاَ يَنْبَغِي لِعَبْ","43"],[219,"Chapter: The Virtues Of Yusuf, Peace Be Upon Him","باب مِنْ فَضَائِلِ يُوسُفَ عَلَيْهِ السَّلاَمُ","44"],[220,"Chapter: The Virtues Of Zakariyya, Peace Be Upon Him","باب مِنْ فَضَائِلِ زَكَرِيَّاءَ عَلَيْهِ السَّلاَمُ","45"],[221,"Chapter: The Virtues Of Al-Khadir, Peace Be Upon Him","باب مِنْ فَضَائِلِ الْخَضِرِ عَلَيْهِ السَّلاَمُ","46"]],"44":[[1,"Chapter: The Virtues Of Abu Bakr As-Siddiq (RA)","باب مِنْ فَضَائِلِ أَبِي بَكْرٍ الصِّدِّيقِ رضى الله عنه","1"],[18,"Chapter: The Virtues Of 'Umar (RA)","باب مِنْ فَضَائِلِ عُمَرَ رضى الله تعالى عنه","2"],[39,"Chapter: The Virtues Of 'Uthman Bin 'Affan (RA)","باب مِنْ فَضَائِلِ عُثْمَانَ بْنِ عَفَّانَ رضى الله عنه","3"],[47,"Chapter: The Virtues Of 'Ali Bin Abi Talib (RA)","باب مِنْ فَضَائِلِ عَلِيِّ بْنِ أَبِي طَالِبٍ رضى الله عنه","4"],[60,"Chapter: The Virtues Of Sa'd Bin Abi Waqqas (RA)","باب فِي فَضْلِ سَعْدِ بْنِ أَبِي وَقَّاصٍ رضى الله عنه","5"],[72,"Chapter: The Virtues Of Talhah And Az-Zubair (RA)","باب مِنْ فَضَائِلِ طَلْحَةَ وَالزُّبَيْرِ رضى الله عنهما","6"],[82,"Chapter: The Virtues Of Abu 'Ubaidah Bin Al-Jarrah (RA)","باب فَضَائِلِ أَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ رضى الله تعالى عنه","7"],[86,"Chapter: The Virtues Of Al-Hasan And Al-Husain (RA)","باب فَضَائِلِ الْحَسَنِ وَالْحُسَيْنِ رضى الله عنهما","8"],[91,"Chapter: The Virtues Of The Household Of The Prophet (SAW)","باب فَضَائِلِ أَهْلِ بَيْتِ النَّبِيِّ صلى الله عليه وسلم","9"],[92,"Chapter: The Virtues Of Zaid Bin Harithah And His Son Usamah (RA)","باب فَضَائِلِ زَيْدِ بْنِ حَارِثَةَ وَأُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللَّهُ عَنْهُمَا","10"],[96,"Chapter: The Virtues Of Abdullah Bin Ja'far (RA)","باب فَضَائِلِ عَبْدِ اللَّهِ بْنِ جَعْفَرٍ رضى الله عنهما","11"],[101,"Chapter: The Virtues Of Khadijah, The Mother Of The Believers (RA)","باب فَضَائِلِ خَدِيجَةَ أُمِّ الْمُؤْمِنِينَ رضى الله تعالى عنها","12"],[113,"Chapter: The Virtues Of 'Aishah, The Mother Of The Believers (RA)","باب فِي فَضْلِ عَائِشَةَ رضى الله تعالى عنها","13"],[135,"Chapter: The Hadith Of Umm Zar","باب ذِكْرِ حَدِيثِ أُمِّ زَرْعٍ","14"],[137,"Chapter: The Virtues Of Fatimah (RA), The Daughter Of The Prophet (SAW)","باب فَضَائِلِ فَاطِمَةَ بِنْتِ النَّبِيِّ عَلَيْهَا الصَّلاَةُ وَالسَّلاَمُ","15"],[145,"Chapter: The Virtues Of Umm Salamah, The Mother Of The Believers (RA)","باب مِنْ فَضَائِلِ أُمِّ سَلَمَةَ أُمِّ الْمُؤْمِنِينَ رضى الله عنها","16"],[146,"Chapter: The Virtues Of Zainab, The Mother Of The Believers (RA)","باب مِنْ فَضَائِلِ زَيْنَبَ أُمِّ الْمُؤْمِنِينَ رضى الله عنها","17"],[147,"Chapter: The Virtues Of Umm Ayman (RA)","باب مِنْ فَضَائِلِ أُمِّ أَيْمَنَ رضى الله عنها","18"],[149,"Chapter: The Virtues Of Umm Sulaim, The Mother Of Anas Bin Malik, And Bilal (RA)","باب مِنْ فَضَائِلِ أُمِّ سُلَيْمٍ أُمِّ أَنَسِ بْنِ مَالِكٍ وَبِلاَلٍ رضى الله عنهما","19"],[152,"Chapter: The Virtues Of Abu Talhah Al-Ansari (RA)","باب مِنْ فَضَائِلِ أَبِي طَلْحَةَ الأَنْصَارِيِّ رضى الله تعالى عنه","20"],[154,"Chapter: The Virtues Of Bilal (RA)","باب مِنْ فَضَائِلِ بِلاَلٍ رضى الله عنه","21"],[155,"Chapter: The Virtues Of 'Abdullah Bin Mas'ud And His Mother (RA)","باب مِنْ فَضَائِلِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ وَأُمِّهِ رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا","22"],[170,"Chapter: The Virtues Of Ubayy Bin Ka'b And A Group Of The Ansar (RA)","باب مِنْ فَضَائِلِ أُبَىِّ بْنِ كَعْبٍ وَجَمَاعَةٍ مِنَ الأَنْصَارِ رَضِيَ اللَّهُ تَعَالَى عَنْهُمْ .","23"],[175,"Chapter: The Virtues Of Sa'd Bin Mu'adh (RA)","باب مِنْ فَضَائِلِ سَعْدِ بْنِ مُعَاذٍ رضى الله عنه","24"],[183,"Chapter: The Virtues Of Abu Dujanah Simak Bin Kharashah (RA)","باب مِنْ فَضَائِلِ أَبِي دُجَانَةَ سِمَاكِ بْنِ خَرَشَةَ رضى الله تعالى عنه","25"],[184,"Chapter: The Virtues Of 'Abdullah Bin 'Amr Bin Haram, The Father Of Jabir (RA)","باب مِنْ فَضَائِلِ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ حَرَامٍ وَالِدِ جَابِرٍ رضى الله تعالى عنهما","26"],[188,"Chapter: The Virtues Of Julaibib (RA)","باب مِنْ فَضَائِلِ جُلَيْبِيبٍ رضى الله عنه","27"],[189,"Chapter: The Virtues Of Abu Dharr (RA)","باب مِنْ فَضَائِلِ أَبِي ذَرٍّ رضى الله عنه","28"],[193,"Chapter: The Virtues Of Jarir Bin 'Abdullah (RA)","باب مِنْ فَضَائِلِ جَرِيرِ بْنِ عَبْدِ اللَّهِ رضى الله تعالى عنه","29"],[198,"Chapter: The Virtues Of 'Abdullah Bin 'Abbas (RA)","باب فَضَائِلِ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رضى الله عنهما","30"],[199,"Chapter: The Virtues Of 'Abdullah Bin 'Umar (RA)","باب مِنْ فَضَائِلِ عَبْدِ اللَّهِ بْنِ عُمَرَ رضى الله عنهما","31"],[202,"Chapter: The Virtues Of Anas bin Malik (RA)","باب مِنْ فَضَائِلِ أَنَسِ بْنِ مَالِكٍ رضى الله عنه","32"],[210,"Chapter: The Virtues Of Abdullah Bin Salam (RA)","باب مِنْ فَضَائِلِ عَبْدِ اللَّهِ بْنِ سَلاَمٍ رضى الله عنه","33"],[214,"Chapter: The Virtues Of Hassan Bin Thabit (RA)","باب فَضَائِلِ حَسَّانَ بْنِ ثَابِتٍ رضى الله عنه","34"],[226,"Chapter: The Virtues Of Abu Hurairah [Ad-Dawsi] (RA)","باب مِنْ فَضَائِلِ أَبِي هُرَيْرَةَ الدَّوْسِيِّ رضى الله عنه","35"],[232,"Chapter: The Virtues Of Habib Bin Abi Balta'ah And The People Of Badr (RA)","باب مِنْ فَضَائِلِ أَهْلِ بَدْرٍ رضى الله عنهم وَقِصَّةِ حَاطِبِ بْنِ أَبِي بَلْتَعَةَ","36"],[235,"Chapter: The Virtues Of The Companions Of The Tree, Those Who Gave Their Oath Of Allegiance Bay'at Ar-Ridwan (RA)","باب مِنْ فَضَائِلِ أَصْحَابِ الشَّجَرَةِ أَهْلِ بَيْعَةِ الرِّضْوَانِ رضى الله عنهم","37"],[236,"Chapter: The Virtues Of The Two Ash'aris; Abu Musa And Abu 'Amir (RA)","باب مِنْ فَضَائِلِ أَبِي مُوسَى وَأَبِي عَامِرٍ الأَشْعَرِيَّيْنِ رَضِيَ اللَّهُ عَنْهُمَا","38"],[238,"Chapter: The Virtues Of The Ash'aris (RA)","باب مِنْ فَضَائِلِ الأَشْعَرِيِّينَ رضى الله عنهم","39"],[240,"Chapter: The Virtues Of Abu Sufyan Sakhr bin Harb (RA)","باب مِنْ فَضَائِلِ أَبِي سُفْيَانَ بْنِ حَرْبٍ رضى الله عنه","40"],[241,"Chapter: The Virtues Of Ja'far Bin Abi Talib And Asma' Bint Umais, And The People Of Their Ship (RA)","باب مِنْ فَضَائِلِ جَعْفَرِ بْنِ أَبِي طَالِبٍ وَأَسْمَاءَ بِنْتِ عُمَيْسٍ وَأَهْلِ سَفِينَتِهِمْ رضى","41"],[242,"Chapter: The Virtues Of Salman, Bilal And Suhaib (RA)","باب مِنْ فَضَائِلِ سَلْمَانَ وَصُهَيْبٍ وَبِلاَلٍ رضى الله تعالى عنهم","42"],[243,"Chapter: The Virtues Of The Ansar (RA)","باب مِنْ فَضَائِلِ الأَنْصَارِ رضى الله تعالى عنهم","43"],[250,"Chapter: The Best Clans Of The Ansar","باب فِي خَيْرِ دُورِ الأَنْصَارِ رضى الله عنهم","44"],[257,"Chapter: Keeping Good Company With The Ansar (RA)","باب فِي حُسْنِ صُحْبَةِ الأَنْصَارِ رضى الله عنهم","45"],[258,"Chapter: The Supplication Of The Prophet (SAW) For Ghifar And Aslam","باب دُعَاءِ النَّبِيِّ صلى الله عليه وسلم لِغِفَارَ وَأَسْلَمَ","46"],[267,"Chapter: The Virtues Of Ghifar, Aslam, Juhainah, Ashja', Muzainah, Tamim, Daws and Tayy'","باب مِنْ فَضَائِلِ غِفَارَ وَأَسْلَمَ وُجُهَيْنَةَ وَأَشْجَعَ وَمُزَيْنَةَ وَتَمِيمٍ وَدَوْسٍ وَطَيِّئٍ","47"],[283,"Chapter: The Best Of People","باب خِيَارِ النَّاسِ","48"],[285,"Chapter: The Virtues Of The Women Of The Quraish","باب مِنْ فَضَائِلِ نِسَاءِ قُرَيْشٍ","49"],[291,"Chapter: The Prophet (SAW) Established Bonds Of Brotherhood Among His Companions (RA)","باب مُؤَاخَاةِ النَّبِيِّ صلى الله عليه وسلم بَيْنَ أَصْحَابِهِ رضى الله تعالى عنهم","50"],[295,"Chapter: The Presence Of The Prophet (SAW) Is A Source Of Security For His Companions And The Presence Of His Companions Is A Source Of Security For The Ummah","باب بَيَانِ أَنَّ بَقَاءَ النَّبِيِّ صلى الله عليه وسلم أَمَانٌ لأَصْحَابِهِ وَبَقَاءَ أَصْحَابِهِ أَمَانٌ","51"],[296,"Chapter: The Virtues Of the Sahabah, Then Those Who Come After Them, Then Those Who Come After Them","باب فَضْلِ الصَّحَابَةِ ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ","52"],[308,"Chapter: The Meaning Of The Words Of The Prophet (SAW): \"After One Hundred Years There Will Be No Soul Left Alive That Is Living Now\"","باب قَوْلِهِ صلى الله عليه وسلم \" لاَ تَأْتِي مِائَةُ سَنَةٍ وَعَلَى الأَرْضِ نَفْسٌ مَنْفُوسَةٌ الْيَوْ","53"],[316,"Chapter: The Prohibition Of Reviling The Companions (RA)","باب تَحْرِيمِ سَبِّ الصَّحَابَةِ رضى الله عنهم","54"],[319,"Chapter: The Virtues Of Uwais Al-Qarani (RA)","باب مِنْ فَضَائِلِ أُوَيْسٍ الْقَرَنِيِّ رضى الله عنه","55"],[322,"Chapter: The Advice Of The Prophet (SAW) Concerning The People Of Egypt","باب وَصِيَّةِ النَّبِيِّ صلى الله عليه وسلم بِأَهْلِ مِصْرَ","56"],[324,"Chapter: The Virtues Of The People Of Oman","باب فَضْلِ أَهْلِ عُمَانَ","57"],[325,"Chapter: The Liar And Great Slaughterer Of Thaqif","باب ذِكْرِ كَذَّابِ ثَقِيفٍ وَمُبِيرِهَا","58"],[326,"Chapter: The Virtues Of The Persians","باب فَضْلِ فَارِسَ","59"],[328,"Chapter: The Words Of The Prophet (SAW): \"People Are Like A Hundred Camels Among Whom You Cannot Find One That Is Fit For Riding\"","باب قَوْلِهِ صلى الله عليه وسلم \" النَّاسُ كَإِبِلٍ مِائَةٍ لاَ تَجِدُ فِيهَا رَاحِلَةً \"","60"]],"45":[[1,"Chapter: Being Dutiful To One's Parents, And Which Of Them Is More Entitled To It","باب بِرِّ الْوَالِدَيْنِ وَأَنَّهُمَا أَحَقُّ بِهِ","1"],[8,"Chapter: Being Dutiful To One's Parents Takes Precedence Over Voluntary Prayer, Etc.","باب تَقْدِيمِ بِرِّ الْوَالِدَيْنِ عَلَى التَّطَوُّعِ بِالصَّلاَةِ وَغَيْرِهَا","2"],[10,"Chapter: The Disgrace Of One Whose Parents, One Or Both Of Them, Reach Old Age During His Lifetime, And He Does Not Enter Paradise","باب رَغِمَ أَنْفُ مَنْ أَدْرَكَ أَبَوَيْهِ أَوْ أَحَدَهُمَا عِنْدَ الْكِبَرِ فَلَمْ يَدْخُلِ الْجَنَّةَ","3"],[13,"Chapter: The Virtue Of Maintaining Ties With The Friends Of One's Father And Mother, Etc.","باب فَضْلِ صِلَةِ أَصْدِقَاءِ الأَبِ وَالأُمِّ وَنَحْوِهِمَا","4"],[16,"Chapter: Meaning Of Righteousness And Sin","باب تَفْسِيرِ الْبِرِّ وَالإِثْمِ","5"],[18,"Chapter: Upholding Ties Of Kinship, And The Prohibition Of Severing Them","باب صِلَةِ الرَّحِمِ وَتَحْرِيمِ قَطِيعَتِهَا","6"],[26,"Chapter: The Prohibition Of Mutual Jealousy And Hatred, And Turning Away From One Another","باب النَّهْىِ عَنِ التَّحَاسُدِ، وَالتَّبَاغُضِ، وَالتَّدَابُرِ،","7"],[31,"Chapter: The Prohibition Of Forsaking Someone For More Than Three Days For No Legitimate Reason","باب تَحْرِيمِ الْهَجْرِ فَوْقَ ثَلاَثٍ بِلاَ عُذْرٍ شَرْعِيٍّ","8"],[35,"Chapter: The Prohibition Of Suspicion, Spying, Competition, Artificial Inflation Of Prices, And So On","باب تَحْرِيمِ الظَّنِّ وَالتَّجَسُّسِ وَالتَّنَافُسِ وَالتَّنَاجُشِ وَنَحْوِهَا","9"],[40,"Chapter: The Prohibition Of Wronging, Forsaking, Or Despising A Muslim And The Inviolability Of His Blood, Honor And Wealth","باب تَحْرِيمِ ظُلْمِ الْمُسْلِمِ وَخَذْلِهِ وَاحْتِقَارِهِ وَدَمِهِ وَعِرْضِهِ وَمَالِهِ","10"],[43,"Chapter: The Prohibition Of Holding Grudges","باب النَّهْىِ عَنِ الشَّحْنَاءِ، وَالتَّهَاجُرِ،","11"],[46,"Chapter: The Virtue Of Love For The Sake Of Allah, May He Be Exalted","باب فِي فَضْلِ الْحُبِّ فِي اللَّهِ","12"],[49,"Chapter: The Virtue Of Visiting The Sick","باب فَضْلِ عِيَادَةِ الْمَرِيضِ","13"],[55,"Chapter: The Reward Of The Believer For Whatever Befalls Him Of Sickness, Grief And The Like, Even A Thorn That Pricks Him","باب ثَوَابِ الْمُؤْمِنِ فِيمَا يُصِيبُهُ مِنْ مَرَضٍ أَوْ حُزْنٍ أَوْ نَحْوِ ذَلِكَ حَتَّى الشَّوْكَةِ يُش","14"],[70,"Chapter: The Prohibition Of Oppression","باب تَحْرِيمِ الظُّلْمِ","15"],[80,"Chapter: Supporting One's Brother Whether He Is Doing Wrong Or Being Wronged","باب نَصْرِ الأَخِ ظَالِمًا أَوْ مَظْلُومًا","16"],[83,"Chapter: The Mutual Mercy, Compassion And Support Of The Believers","باب تَرَاحُمِ الْمُؤْمِنِينَ وَتَعَاطُفِهِمْ وَتَعَاضُدِهِمْ","17"],[89,"Chapter: The Prohibition Of Reviling","باب النَّهْىِ عَنِ السِّبَابِ،","18"],[90,"Chapter: It Is Recommended To Forgive And Be Humble","باب اسْتِحْبَابِ الْعَفْوِ وَالتَّوَاضُعِ","19"],[91,"Chapter: The Prohibition Of Backbiting","باب تَحْرِيمِ الْغِيبَةِ","20"],[92,"Chapter: Glad Tidings That Whomever Allah Conceals In This World He Will Conceal Him In The Hereafter","باب بِشَارَةِ مَنْ سَتَرَ اللَّهُ تَعَالَى عَيْبَهُ فِي الدُّنْيَا بِأَنْ يَسْتُرَ عَلَيْهِ فِي الآخِرَةِ","21"],[94,"Chapter: Being Kind To Protect Oneself From Another's Vile Behavior","باب مُدَارَاةِ مَنْ يُتَّقَى فُحْشُهُ","22"],[96,"Chapter: The Virtue Of Gentleness","باب فَضْلِ الرِّفْقِ","23"],[102,"Chapter: The Prohibition Of Cursing Animals Etc.","باب النَّهْىِ عَنْ لَعْنِ الدَّوَابِّ، وَغَيْرِهَا،","24"],[112,"Chapter: Whomever Is Cursed, Reviled Or Prayed Against By The Prophet (SAW) When He Does Not Deserve That, It Will Be Purification, Reward And Mercy For Him","باب مَنْ لَعَنَهُ النَّبِيُّ صلى الله عليه وسلم أَوْ سَبَّهُ أَوْ دَعَا عَلَيْهِ","25"],[127,"Chapter: Criticism Of The One Who Is Two-Faced, And The Prohibition Of Doing That","باب ذَمِّ ذِي الْوَجْهَيْنِ وَتَحْرِيمِ فِعْلِهِ","26"],[130,"Chapter: The Prohibition Of Lying, And What Is Permitted Thereof","باب تَحْرِيمِ الْكَذِبِ وَبَيَانِ مَا يُبَاحُ مِنْهُ","27"],[133,"Chapter: The Prohibition Of Malicious Gossip (Namimah)","باب تَحْرِيمِ النَّمِيمَةِ","28"],[134,"Chapter: The Abhorrence Of Lying, And The Goodness And Virtue Of Honesty","باب قُبْحِ الْكَذِبِ وَحُسْنِ الصِّدْقِ وَفَضْلِهِ","29"],[138,"Chapter: The Virtue Of One Who Controls Himself At Times Of Anger, And What Takes Away Anger","باب فَضْلِ مَنْ يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ وَبِأَىِّ شَىْءٍ يَذْهَبُ الْغَضَبُ","30"],[146,"Chapter: 'Man Is Created In Such A Way That He Is Not Steadfast'","باب خُلِقَ الإِنْسَانُ خَلْقًا لاَ يَتَمَالَكُ","31"],[148,"Chapter: The Prohibition Of Striking The Face","باب النَّهْىِ عَنْ ضَرْبِ الْوَجْهِ،","32"],[154,"Chapter: Stern Warning To One Who Torments People Unlawfully","باب الْوَعِيدِ الشَّدِيدِ لِمَنْ عَذَّبَ النَّاسَ بِغَيْرِ حَقٍّ","33"],[158,"Chapter: Telling The One Who Carries A Weapon In The Masjid, Marketplace Or Other Place Where People Gather, To Hold It By Its Point","باب أَمْرِ مَنْ مَرَّ بِسِلاَحٍ فِي مَسْجِدٍ أَوْ سُوقٍ أَوْ غَيْرِهِمَا مِنَ الْمَوَاضِعِ الْجَامِعَةِ لِ","34"],[163,"Chapter: The Prohibition Of Pointing At A Muslim With A Weapon","باب النَّهْىِ عَنِ الإِشَارَةِ، بِالسِّلاَحِ إِلَى مُسْلِمٍ","35"],[166,"Chapter: The Virtue Of Removing A Harmful Thing From The Road","باب فَضْلِ إِزَالَةِ الأَذَى عَنِ الطَّرِيقِ،","36"],[172,"Chapter: The Prohibition Of Tormenting Cats And Other Animals That Are Not Harmful","باب تَحْرِيمِ تَعْذِيبِ الْهِرَّةِ وَنَحْوِهَا مِنَ الْحَيَوَانِ الَّذِي لاَ يُؤْذِي","37"],[177,"Chapter: The Prohibition Of Arrogance","باب تَحْرِيمِ الْكِبْرِ","38"],[178,"Chapter: The Prohibition Of Making Others Despair Of The Mercy Of Allah","باب النَّهْىِ عَنْ تَقْنِيطِ الإِنْسَانِ، مِنْ رَحْمَةِ اللَّهِ تَعَالَى","39"],[179,"Chapter: The Virtue Of The Weak And Downtrodden","باب فَضْلِ الضُّعَفَاءِ وَالْخَامِلِينَ","40"],[180,"Chapter: The Prohibition Of Saying \"The People Are Doomed\"","باب النَّهْىِ عَنْ قَوْلِ، هَلَكَ النَّاسُ","41"],[182,"Chapter: Advice To Treat One's Neighbor Well","باب الْوَصِيَّةِ بِالْجَارِ وَالإِحْسَانِ إِلَيْهِ","42"],[187,"Chapter: It Is Recommend To Show A Cheerful Countenance When Meeting Others","باب اسْتِحْبَابِ طَلاَقَةِ الْوَجْهِ عِنْدَ اللِّقَاءِ","43"],[188,"Chapter: It Is Recommend To Intercede With Regard To That Which Is Not Unlawful","باب اسْتِحْبَابِ الشَّفَاعَةِ فِيمَا لَيْسَ بِحَرَامٍ","44"],[189,"Chapter: It Is Recommend To Keep Company With Righteous People And Avoid Bad Company","باب اسْتِحْبَابِ مُجَالَسَةِ الصَّالِحِينَ وَمُجَانَبَةِ قُرَنَاءِ السَّوْءِ","45"],[190,"Chapter: The Virtue Of Treating Daughters Well","باب فَضْلِ الإِحْسَانِ إِلَى الْبَنَاتِ","46"],[193,"Chapter: The Virtue Of One Whose Child Dies And He Seeks Reward","باب فَضْلِ مَنْ يَمُوتُ لَهُ وَلَدٌ فَيَحْتَسِبُهُ","47"],[201,"Chapter: When Allah Loves A Person. He Commands Jibril To Love Him, And He Loves Him, And The People Of Heaven Love Him, Then He Finds Acceptance On Earth","باب إِذَا أَحَبَّ اللَّهُ عَبْدًا حَبَّبَهُ إِلَى عِبَادِهِ","48"],[204,"Chapter: Souls Are Like Conscripted Soldiers","باب الأَرْوَاحِ جُنُودٌ مُجَنَّدَةٌ","49"],[206,"Chapter: A Man Will Be With Those Whom He Loves","باب الْمَرْءُ مَعَ مَنْ أَحَبَّ","50"],[216,"Chapter: If A Righteous Man Is Praised, It Is Glad Tidings For Him And Will Not Harm Him","باب إِذَا أُثْنِيَ عَلَى الصَّالِحِ فَهِيَ بُشْرَى وَلاَ تَضُرُّهُ","51"]],"46":[[1,"Chapter: How The Human Being Is Created, In His Mother's Womb, And His Provision, Lifespan And Deeds Are Written Down, And His Misery and Happiness","بَاب كَيْفِيَّةِ خَلْقِ الْآدَمِيِّ فِي بَطْنِ أُمِّهِ وَكِتَابَةِ رِزْقِهِ وَأَجَلِهِ وَعَمَلِهِ وَشَقَاوَتِهِ وَسَعَادَتِهِ","1"],[20,"Chapter: The Debate Between Adam And Musa (Peace And Blessings Of Allah Be Upon Them)","باب حِجَاجِ آدَمَ وَمُوسَى عَلَيْهِمَا السَّلاَمُ","2"],[29,"Chapter: Allah Directs Hearts As He Wills","باب تَصْرِيفِ اللَّهِ تَعَالَى الْقُلُوبَ كَيْفَ شَاءَ","3"],[30,"Chapter: Everything Is Decided And Decreed","باب كُلُّ شَىْءٍ بِقَدَرٍ","4"],[32,"Chapter: The Son Of Adam's Share Of Zina Etc. Is Decreed For Him","باب قُدِّرَ عَلَى ابْنِ آدَمَ حَظُّهُ مِنَ الزِّنَى وَغَيْرِهِ","5"],[34,"Chapter: The Meaning Of \"Every Child Is Born In A State Of Fitrah\" And The Ruling On The Dead Children Of The Disbelievers And Of The Muslims.","بَاب مَعْنَى كُلِّ مَوْلُودٍ يُولَدُ عَلَى الْفِطْرَةِ وَحُكْمِ مَوْتِ أَطْفَالِ الْكُفَّارِ وَأَطْفَالِ الْمُسْلِمِينَ","6"],[49,"Chapter: Lifespans, Provisions, Etc. Do Not Increase Or Decrease From What Has Already Been Decreed","بَاب بَيَانِ أَنَّ الْآجَالَ وَالْأَرْزَاقَ وَغَيْرَهَا لَا تَزِيدُ وَلَا تَنْقُصُ عَمَّا سَبَقَ بِهِ الْقَدَرُ","7"],[52,"Chapter: Belief In The Divine Decree And Submission To It","بَاب فِي الْأَمْرِ بِالْقُوَّةِ وَتَرْكِ الْعَجْزِ وَالِاسْتِعَانَةِ بِاللَّهِ وَتَفْوِيضِ الْمَقَادِيرِ لِلَّهِ","8"]],"47":[[1,"Chapter: The Prohibition Of, And Warning Against Seeking Out Verses Of The Quran Whose Meanings Are Not Decisive; The Prohibition Of Arguing About The Qur'an","بَاب النَّهْيِ عَنْ اتِّبَاعِ مُتَشَابِهِ الْقُرْآنِ وَالتَّحْذِيرِ مِنْ مُتَّبِعِيهِ وَالنَّهْيِ عَنْ الِاخْتِلَافِ فِي الْقُرْآنِ","1"],[6,"Chapter: The One Who Is Harsh In Arguing","باب فِي الأَلَدِّ الْخَصِمِ","2"],[7,"Chapter: Following The Ways Of The Jews And Christians","باب اتِّبَاعِ سُنَنِ الْيَهُودِ وَالنَّصَارَى","3"],[10,"Chapter: The Destruction Of Those Who Go To Extremes","باب هَلَكَ الْمُتَنَطِّعُونَ","4"],[11,"Chapter: The Taking Away Of Knowledge And The Spread Of Ignorance At The End Of Time","باب رَفْعِ الْعِلْمِ وَقَبْضِهِ وَظُهُورِ الْجَهْلِ وَالْفِتَنِ فِي آخِرِ الزَّمَانِ","5"],[26,"Chapter: The One Who Starts Something Good Or Something Bad; The One Who Calls Others To Guidance Or Misguidance","باب مَنْ سَنَّ سُنَّةً حَسَنَةً أَوْ سَيِّئَةً وَمَنْ دَعَا إِلَى هُدًى أَوْ ضَلاَلَةٍ","6"]],"48":[[1,"Chapter: Encouragement To Remember Allah, Exalted is He","باب الْحَثِّ عَلَى ذِكْرِ اللَّهِ تَعَالَى","1"],[5,"Chapter: The Names Of Allah, Exalted is He, And The Virtue Of The One Who Learns Them By Heart","باب فِي أَسْمَاءِ اللَّهِ تَعَالَى وَفَضْلِ مَنْ أَحْصَاهَا","2"],[7,"Chapter: Being Firm In Supplication And Not Saying: \"If You Will\"","باب الْعَزْمِ بِالدُّعَاءِ وَلاَ يَقُلْ إِنْ شِئْتَ","3"],[10,"Chapter: It Is Disliked To Wish For Death Because Of Some Harm That Has Befallen One","باب كَرَاهَةِ تَمَنِّي الْمَوْتِ لِضُرٍّ نَزَلَ بِهِ","4"],[16,"Chapter: Whoever Loves To Meet Allah, Allah Loves To Meet Him, And Whoever Hates To Meet Allah, Allah Hates To Meet Him","بَاب مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللَّهُ لِقَاءَهُ وَمَنْ كَرِهَ لِقَاءَ اللَّهِ كَرِهَ اللَّهُ لِقَاءَهُ","5"],[25,"Chapter: The Virtue Of Remembrance, Supplication, Drawing Close To Allah And Thinking Positively Of Him","باب فَضْلِ الذِّكْرِ وَالدُّعَاءِ وَالتَّقَرُّبِ إِلَى اللَّهِ تَعَالَى","6"],[31,"Chapter: It Is Disliked To Pray For Punishment To Be Brought Forward In This World","باب كَرَاهَةِ الدُّعَاءِ بِتَعْجِيلِ الْعُقُوبَةِ فِي الدُّنْيَا","7"],[35,"Chapter: The Virtues Of Gathering To Remember Allah (Adh-Dhikr)","باب فَضْلِ مَجَالِسِ الذِّكْرِ","8"],[36,"Chapter: The Virtue Of The Supplication: \"O Allah, Give Us Good In This World And Good In The Hereafter, And Save Us From The Torment Of The Fire\"","بَاب فَضْلِ الدُّعَاءِ بِاللَّهُمَّ آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ","9"],[38,"Chapter: The Virtue Of Tahlil (Saying La Ilaha Ill-Allah), Tasbih (Saying Subhan Allah) And (Du'a) Supplication","باب فَضْلِ التَّهْلِيلِ وَالتَّسْبِيحِ وَالدُّعَاءِ","10"],[48,"Chapter: The Virtue Of Gathering To Read Quran And To Remember Allah","باب فَضْلِ الاِجْتِمَاعِ عَلَى تِلاَوَةِ الْقُرْآنِ وَعَلَى الذِّكْرِ","11"],[52,"Chapter: It Is Recommend To Pray For Forgiveness A Great Deal","باب اسْتِحْبَابِ الاِسْتِغْفَارِ وَالاِسْتِكْثَارِ مِنْهُ","12"],[56,"Chapter: It Is Recommend To Lower One's Voice When Saying Remembrance, Except In The Cases Where It Is Commanded To Raise The Voice Such As The Talbiyah Etc. It Is Recommend To Say A Great Deal, \"There Is No Power And No Strength Except With Allah\"","باب اسْتِحْبَابِ خَفْضِ الصَّوْتِ بِالذِّكْرِ","13"],[65,"Chapter: Supplications And Seeking Refuge With Allah","باب التَّعَوُّذِ مِنْ شَرِّ الْفِتَنِ وَغَيْرِهَا","14"],[67,"Chapter: Seeking Refuge With Allah From Helplessness, Laziness Etc","باب التَّعَوُّذِ مِنَ الْعَجْزِ وَالْكَسَلِ وَغَيْرِهِ","15"],[71,"Chapter: Seeking Refuge From A Bad End, And Misery Etc","باب فِي التَّعَوُّذِ مِنْ سُوءِ الْقَضَاءِ وَدَرَكِ الشَّقَاءِ وَغَيْرِهِ","16"],[75,"Chapter: Supplication When Going To Sleep","باب مَا يَقُولُ عِنْدَ النَّوْمِ وَأَخْذِ الْمَضْجَعِ","17"],[88,"Chapter: Supplications [Of The Prophet (SAW)]","باب التَّعَوُّذِ مِنْ شَرِّ مَا عَمِلَ وَمِنْ شَرِّ مَا لَمْ يَعْمَلْ","18"],[106,"Chapter: The Tasbih At The Beginning Of The Day And When Going To Sleep","باب التَّسْبِيحِ أَوَّلَ النَّهَارِ وَعِنْدَ النَّوْمِ","19"],[112,"Chapter: It Is Recommend To Say Supplication When A Rooster Crows","باب اسْتِحْبَابِ الدُّعَاءِ عِنْدَ صِيَاحِ الدِّيكِ","20"],[113,"Chapter: Supplication At Times Of Distress","باب دُعَاءِ الْكَرْبِ","21"],[117,"Chapter: The Virtue Of (Saying): \"Glory To Allah And With His Praise\"","باب فَضْلِ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ","22"],[119,"Chapter: The Virtue Of Praying For The Muslims In Their Absence","باب فَضْلِ الدُّعَاءِ لِلْمُسْلِمِينَ بِظَهْرِ الْغَيْبِ","23"],[123,"Chapter: It Is Recommend To Praise Allah After Eating And Drinking","باب اسْتِحْبَابِ حَمْدِ اللَّهِ تَعَالَى بَعْدَ الأَكْلِ وَالشُّرْبِ","24"],[125,"Chapter: It Is Recommended For The One Who Supplicated Not To Be Impatient. And Not To Say: \"I Supplicated And Received No Response\"","باب بَيَانِ أَنَّهُ يُسْتَجَابُ لِلدَّاعِي مَا لَمْ يَعْجَلْ فَيَقُولُ دَعَوْتُ فَلَمْ يُسْتَجَبْ لِي","25"]],"49":[[1,"Chapter: \"Most Of The People Of Paradise Are Poor, And Most Of The Inhabitants Of The Fire Are Women, And The Fitnah Of Women\"","بَاب أَكْثَرُ أَهْلِ الْجَنَّةِ الْفُقَرَاءُ وَأَكْثَرُ أَهْلِ النَّارِ النِّسَاءُ وَبَيَانِ الْفِتْنَةِ بِالنِّسَاءِ","1"],[13,"Chapter: The Story Of Three Men In The Cave And Their Tawossul (Seeking To Draw Close To Allah) By Means Of Righteous Deeds","باب قِصَّةِ أَصْحَابِ الْغَارِ الثَّلاَثَةِ وَالتَّوَسُّلِ بِصَالِحِ الأَعْمَالِ","2"]],"50":[[1,"Chapter: Exhortation To Repent And Rejoicing Therein","باب فِي الْحَضِّ عَلَى التَّوْبَةِ وَالْفَرَحِ بِهَا","1"],[11,"Chapter: Sins Are Erased By Praying For Forgiveness And Repenting","باب سُقُوطِ الذُّنُوبِ بِالاِسْتِغْفَارِ تَوْبَةً","2"],[14,"Chapter: The Virtue Of Constant Dhikr, Thinking Of The Hereafter, And Remembering That Allah Is Always Watching; Permissibility Of Stopping That Sometimes, And Attending To Worldly Matters","بَاب فَضْلِ دَوَامِ الذِّكْرِ وَالْفِكْرِ فِي أُمُورِ الْآخِرَةِ وَالْمُرَاقَبَةِ وَجَوَازِ تَرْكِ ذَلِكَ فِي بَعْضِ الْأَوْقَاتِ وَالِاشْتِغَالِ بِالدُّنْيَا","3"],[17,"Chapter: The Vastaess Of Allah's Mercy, Which Prevails Over His Wrath","باب فِي سَعَةِ رَحْمَةِ اللَّهِ تَعَالَى وَأَنَّهَا سَبَقَتْ غَضَبَهُ","4"],[33,"Chapter: Acceptance Of Repentance From Sin, Even If The Sin And Repentance Happen Repeatedly","باب قَبُولِ التَّوْبَةِ مِنَ الذُّنُوبِ وَإِنْ تَكَرَّرَتِ الذُّنُوبُ وَالتَّوْبَةُ","5"],[37,"Chapter: The Protective Jealousy (Ghirah) Of Allah The Most High, And The Prohibition Of Immoral Behavior","باب غَيْرَةِ اللَّهِ تَعَالَى وَتَحْرِيمِ الْفَوَاحِشِ","6"],[47,"Chapter: The Words Of Allah The Most High: \"Verily, The Good Deeds Remove The Evil Deeds\"","باب قَوْلِهِ تَعَالَى { إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ}","7"],[54,"Chapter: The Acceptance Of The Repentance Of The One Who Kills, Even If He Has Killed A Great Deal","باب قَبُولِ تَوْبَةِ الْقَاتِلِ وَإِنْ كَثُرَ قَتْلُهُ","8"],[62,"Chapter: The Repentance Of Ka'b Ibn Malik And His Two Companions","باب حَدِيثِ تَوْبَةِ كَعْبِ بْنِ مَالِكٍ وَصَاحِبَيْهِ","9"],[65,"Chapter: Al-Ifk (The Slander) And The Acceptance Of The Slanderer's Repentance","باب فِي حَدِيثِ الإِفْكِ وَقَبُولِ تَوْبَةِ الْقَاذِفِ","10"],[68,"Chapter: Exoneration Of The Prophet's Concubine","باب بَرَاءَةِ حَرَمِ النَّبِيِّ صلى الله عليه وسلم مِنَ الرِّيبَةِ","11"]],"52":[[10,"Chapter: The Beginning Of Creation And The Creation Of Adam, (Peace Be Upon Him)","باب ابْتِدَاءِ الْخَلْقِ وَخَلْقِ آدَمَ عَلَيْهِ السَّلاَمُ","1"],[11,"Chapter: The Resurrection And Description Of The Earth On The Day Of Resurrection","باب فِي الْبَعْثِ وَالنُّشُورِ وَصِفَةِ الأَرْضِ يَوْمَ الْقِيَامَةِ","2"],[13,"Chapter: The Welcoming Feast Of The People Of Paradise","باب نُزُلِ أَهْلِ الْجَنَّةِ","3"],[15,"Chapter: The Jews' Asking The Prophet (SAW) About The Soul, And The Words Of Allah: \"And They Ask You Concerning The Ruh (The Spirit)\"","بَاب سُؤَالِ الْيَهُودِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ الرُّوحِ وَقَوْله تَعَالَى يَسْأَلُونَكَ عَنْ الرُّوحِ الْآيَةَ","4"],[20,"Chapter: The Words Of Allah The Most High: \"And Allah Would Not Punish Them While You Are Amongst Them\"","باب فِي قَوْلِهِ تَعَالَى { وَمَا كَانَ اللَّهُ لِيُعَذِّبَهُمْ وَأَنْتَ فِيهِمْ}","5"],[21,"Chapter: The Words Of Allah: \"Verily, Man Does Transgress Because He Considers Himself Self-Sufficient.\"","باب قَوْلِهِ { إِنَّ الإِنْسَانَ لَيَطْغَى * أَنْ رَآهُ اسْتَغْنَى}","6"],[22,"Chapter: The Smoke (Ad-Dukhan)","باب الدُّخَانِ","7"],[27,"Chapter: The Splitting Of The Moon","باب انْشِقَاقِ الْقَمَرِ","8"],[35,"Chapter: The Disbelievers","باب لاَ أَحَدَ أَصْبَرُ عَلَى أَذًى مِنَ اللَّهِ عَزَّ وَجَلَّ","9"],[37,"Chapter: The Disbeliever Seeking Ransom With An Earthful Of Gold","باب طَلَبِ الْكَافِرِ الْفِدَاءَ بِمِلْءِ الأَرْضِ ذَهَبًا","10"],[41,"Chapter: The Disbeliever Will Be Driven Upon His Face","باب يُحْشَرُ الْكَافِرُ عَلَى وَجْهِهِ","11"],[42,"Chapter: The Most Affluent Of People In This World Will Be Dipped In The Fire, And The Most Destitute Will Be Dipped In Paradise","باب صَبْغِ أَنْعَمِ أَهْلِ الدُّنْيَا فِي النَّارِ وَصَبْغِ أَشَدِّهِمْ بُؤْسًا فِي الْجَنَّةِ","12"],[43,"Chapter: The Believer Is Rewarded For His Good Deeds In This World, And In The Hereafter, And The Disbeliever Is Rewarded For His Good Deeds In This World","بَاب جَزَاءِ الْمُؤْمِنِ بِحَسَنَاتِهِ فِي الدُّنْيَا وَالْآخِرَةِ وَتَعْجِيلِ حَسَنَاتِ الْكَافِرِ فِي الدُّنْيَا","13"],[46,"Chapter: The Believer Is Like A Plant And The Hypocrite And The Disbeliever Are Like Cedars","باب مَثَلُ الْمُؤْمِنِ كَالزَّرْعِ وَمَثَلُ الْكَافِرِ كَشَجَرِ الأَرْزِ","14"],[52,"Chapter: The Likeness Of The Believer Is That Of A Date Palm","باب مَثَلُ الْمُؤْمِنِ مَثَلُ النَّخْلَةِ","15"],[57,"Chapter: The Mischief Of The Shaitan And How He Sends His Troops To Tempt People, And With Every Person There Is A Qarin (Companion From Among The Jinn)","بَاب تَحْرِيشِ الشَّيْطَانِ وَبَعْثِهِ سَرَايَاهُ لِفِتْنَةِ النَّاسِ وَأَنَّ مَعَ كُلِّ إِنْسَانٍ قَرِينًا","16"],[65,"Chapter: No One Will Enter Paradise By Virtue Of His Deeds, Rather By The Mercy Of Allah, Exalted Is He","باب لَنْ يَدْخُلَ أَحَدٌ الْجَنَّةَ بِعَمَلِهِ بَلْ بِرَحْمَةِ اللَّهِ تَعَالَى","17"],[77,"Chapter: Doing A Lot Of Good Deeds And Striving Hard In Worship","باب إِكْثَارِ الأَعْمَالِ وَالاِجْتِهَادِ فِي الْعِبَادَةِ","18"],[80,"Chapter: Moderation In Preaching","باب الاِقْتِصَادِ فِي الْمَوْعِظَةِ","19"]],"53":[[7,"Chapter: In Paradise There Is A Tree In Whose Shade A Rider Could Travel For One Hundred Years And Still Not Cross It","باب إِنَّ فِي الْجَنَّةِ شَجَرَةً يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ عَامٍ لاَ يَقْطَعُهَا","1"],[10,"Chapter: Bestowal Of Divine Pleasure On The People Of Paradise, And Allah Will Never Be Angry With Them","باب إِحْلاَلِ الرِّضْوَانِ عَلَى أَهْلِ الْجَنَّةِ فَلاَ يَسْخَطُ عَلَيْهِمْ أَبَدًا","2"],[11,"Chapter: The Inhabitants Of Paradise Will See The People In The Highest Place In Paradise As Planets Are Seen In The Sky","باب تَرَائِي أَهْلِ الْجَنَّةِ أَهْلَ الْغُرَفِ كَمَا يُرَى الْكَوْكَبُ فِي السَّمَاءِ","3"],[14,"Chapter: One Who Would Love To Have Seen The Prophet (SAW) Even If That Was At The Expense Of His Family And His Wealth","باب فِيمَنْ يَوَدُّ رُؤْيَةَ النَّبِيِّ صلى الله عليه وسلم بِأَهْلِهِ وَمَالِهِ","4"],[15,"Chapter: The Market Of Paradise, And What They Will Get There Of Delight And Beauty","باب فِي سُوقِ الْجَنَّةِ وَمَا يَنَالُونَ فِيهَا مِنَ النَّعِيمِ وَالْجَمَالِ","5"],[16,"Chapter: The First Group To Enter Paradise Will Look Like The Moon When It Is Full; Their Attributes And Their Spouses","بَاب أَوَّلُ زُمْرَةٍ تَدْخُلُ الْجَنَّةَ عَلَى صُورَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ وَصِفَاتُهُمْ وَأَزْوَاجُهُمْ","6"],[20,"Chapter: The Attributes Of Paradise And Its People, And Their Glorifying Allah Every Morning And Evening","باب فِي صِفَاتِ الْجَنَّةِ وَأَهْلِهَا وَتَسْبِيحِهِمْ فِيهَا بُكْرَةً وَعَشِيًّا","7"],[25,"Chapter: The Eternal Delight Of The People Of Paradise, And The Verse In Which Allah Says: \"And It Will Be Announced To Them: This Is The Paradise Which You Have Inherited For What You Used To Do\"","بَاب فِي دَوَامِ نَعِيمِ أَهْلِ الْجَنَّةِ وَقَوْله تَعَالَى وَنُودُوا أَنْ تِلْكُمْ الْجَنَّةُ أُورِثْتُمُوهَا بِمَا كُنْتُمْ تَعْمَلُونَ","8"],[27,"Chapter: The Tents Of Paradise, And The Wives That The Believers Will Have In Them","باب فِي صِفَةِ خِيَامِ الْجَنَّةِ وَمَا لِلْمُؤْمِنِينَ فِيهَا مِنَ الأَهْلِينَ","9"],[30,"Chapter: Rivers Of Paradise In This World","باب مَا فِي الدُّنْيَا مِنْ أَنْهَارِ الْجَنَّةِ","10"],[31,"Chapter: People Will Enter Paradise Whose Hearts Are Like The Hearts Of Birds","باب يَدْخُلُ الْجَنَّةَ أَقْوَامٌ أَفْئِدَتُهُمْ مِثْلُ أَفْئِدَةِ الطَّيْرِ","11"],[33,"Chapter: About Hell - May Allah Protect Us From It","باب فِي شِدَّةِ حَرِّ نَارِ جَهَنَّمَ وَبُعْدِ قَعْرِهَا وَمَا تَأْخُذُ مِنَ الْمُعَذَّبِينَ","12"],[41,"Chapter: The Arrogant Will Enter The Fire, And The Humble Will Enter Paradise","باب النَّارُ يَدْخُلُهَا الْجَبَّارُونَ وَالْجَنَّةُ يَدْخُلُهَا الضُّعَفَاءُ","13"],[66,"Chapter: The Passing Away Of This World, And The Gathering On The Day Of Resurrection","باب فَنَاءِ الدُّنْيَا وَبَيَانِ الْحَشْرِ يَوْمَ الْقِيَامَةِ","14"],[72,"Chapter: The Description Of The Day Of Resurrection - May Allah Save Us From Its Terrors","باب فِي صِفَةِ يَوْمِ الْقِيَامَةِ أَعَانَنَا اللَّهُ عَلَى أَهْوَالِهَا","15"],[76,"Chapter: Attributes By Which The People Of Paradise And The People Of The Fire May Be Recognized In This World","باب الصِّفَاتِ الَّتِي يُعْرَفُ بِهَا فِي الدُّنْيَا أَهْلُ الْجَنَّةِ وَأَهْلُ النَّارِ","16"],[80,"Chapter: The Deceased Is Shown His Place In Paradise Or The Fire; And Confirmation Of The Torment In The Grave - We Seek Refuge With Allah From That","بَاب عَرْضِ مَقْعَدِ الْمَيِّتِ مِنْ الْجَنَّةِ أَوْ النَّارِ عَلَيْهِ وَإِثْبَاتِ عَذَابِ الْقَبْرِ وَالتَّعَوُّذِ مِنْهُ","17"],[94,"Chapter: The Surety Of Reckoning","باب إِثْبَاتِ الْحِسَابِ","18"],[98,"Chapter: The Command To Think Positively Of Allah At The Time Of Death","باب الأَمْرِ بِحُسْنِ الظَّنِّ بِاللَّهِ تَعَالَى عِنْدَ الْمَوْتِ","19"]],"54":[[1,"Chapter: The Approach Of Tribulations And The Opening Of The Barrier Of Ya'juj And Ma'juj","باب اقْتِرَابِ الْفِتَنِ وَفَتْحِ رَدْمِ يَأْجُوجَ وَمَأْجُوجَ","1"],[6,"Chapter: The Earth Swallowing Up The Army That Aims To Attack The Ka'bah","باب الْخَسْفِ بِالْجَيْشِ الَّذِي يَؤُمُّ الْبَيْتَ","2"],[11,"Chapter: Onset Of Tribulations Like Rainfall","باب نُزُولِ الْفِتَنِ كَمَوَاقِعِ الْقَطْرِ","3"],[18,"Chapter: If Two Muslims Confront One Another With Their Swords","باب إِذَا تَوَاجَهَ الْمُسْلِمَانِ بِسَيْفَيْهِمَا","4"],[24,"Chapter: (Parts of) This Ummah Will Destroy One Another","باب هَلاَكُ هَذِهِ الأُمَّةِ بَعْضِهِمْ بِبَعْضٍ","5"],[28,"Chapter: The Prophet's Foretelling Of What Will Happen Until The Hour Begins","باب إِخْبَارِ النَّبِيِّ صلى الله عليه وسلم فِيمَا يَكُونُ إِلَى قِيَامِ السَّاعَةِ","6"],[34,"Chapter: The Tribulation That Will Come like Waves Of The Ocean","باب فِي الْفِتْنَةِ الَّتِي تَمُوجُ كَمَوْجِ الْبَحْرِ","7"],[38,"Chapter: The Hour Will Not Begin Until The Euphrates Uncovers A Mountain Of Gold","باب لاَ تَقُومُ السَّاعَةُ حَتَّى يَحْسِرَ الْفُرَاتُ عَنْ جَبَلٍ مِنْ ذَهَبٍ","8"],[44,"Chapter: The Conquest Of Constantinople, The Emergence Of The Dajjal And The Descent Of 'Eisa bin Mariam","باب فِي فَتْحِ قُسْطُنْطِينِيَّةَ وَخُرُوجِ الدَّجَّالِ وَنُزُولِ عِيسَى ابْنِ مَرْيَمَ","9"],[45,"Chapter: The Hour Will Begin When The Byzantines Are The Most Prevalent Of People","باب تَقُومُ السَّاعَةُ وَالرُّومُ أَكْثَرُ النَّاسِ","10"],[47,"Chapter: Fighting The Byzantines, And A Great Deal Of Killing When Ad-Dajjal Emerges","باب إِقْبَالِ الرُّومِ فِي كَثْرَةِ الْقَتْلِ عِنْدَ خُرُوجِ الدَّجَّالِ","11"],[50,"Chapter: Conquests Of The Muslims Before The Appearance Of Ad-Dajjal","باب مَا يَكُونُ مِنْ فُتُوحَاتِ الْمُسْلِمِينَ قَبْلَ الدَّجَّالِ","12"],[51,"Chapter: The Signs Which Will Appear Before The Hour","باب فِي الآيَاتِ الَّتِي تَكُونُ قَبْلَ السَّاعَةِ","13"],[55,"Chapter: The Hour Will Not Begin Until A Fire Emerges From The Land Of The Hijaz","باب لاَ تَقُومُ السَّاعَةُ حَتَّى تَخْرُجَ نَارٌ مِنْ أَرْضِ الْحِجَازِ","14"],[56,"Chapter: The Inhabitants Of Al-Madinah And How Far It Will Be Developed Before The Hour","باب فِي سُكْنَى الْمَدِينَةِ وَعِمَارَتِهَا قَبْلَ السَّاعَةِ","15"],[58,"Chapter: Tribulation From The East, From Where The Horns Of The Shaitan Appear","باب الْفِتْنَةِ مِنَ الْمَشْرِقِ مِنْ حَيْثُ يَطْلُعُ قَرْنَا الشَّيْطَانِ","16"],[64,"Chapter: The Hour Will Not Begin Until Daws Worship Dhul-Khalasah","باب لاَ تَقُومُ السَّاعَةُ حَتَّى تَعْبُدَ دَوْسٌ ذَا الْخَلَصَةِ","17"],[67,"Chapter: The Hour Will Not Begin Until A Man Passes By Another Man's Grave And Wishes That He Was In The Place Of The Deceased, Because Of Calamity","بَاب لَا تَقُومُ السَّاعَةُ حَتَّى يَمُرَّ الرَّجُلُ بِقَبْرِ الرَّجُلِ فَيَتَمَنَّى أَنْ يَكُونَ مَكَانَ الْمَيِّتِ مِنْ الْبَلَاءِ","18"],[108,"Chapter: Ibn Sayyad","باب ذِكْرِ ابْنِ صَيَّادٍ","19"],[123,"Chapter: Ad-Dajjal","باب ذِكْرِ الدَّجَّالِ وَصِفَتِهِ وَمَا مَعَهُ","20"],[136,"Chapter: Description Of Ad-Dajjal; Al-Madinah Is Forbidden To Him; He Will Kill A Believer And Bring Him Back To Life","باب فِي صِفَةِ الدَّجَّالِ وَتَحْرِيمِ الْمَدِينَةِ عَلَيْهِ وَقَتْلِهِ الْمُؤْمِنَ وَإِحْيَائِهِ","21"],[139,"Chapter: Ad-Dajjal Is Very Insignificant Before Allah","باب فِي الدَّجَّالِ وَهُوَ أَهْوَنُ عَلَى اللَّهِ عَزَّ وَجَلَّ","22"],[142,"Chapter: The Emergence Of Ad-Dajjal And His Stay On Earth, And The Descent Of 'Eisa Who Will Kill Him. The Death Of The People Of Goodness And Faith, And The Survival Of The Worst Of People, And Their Idol-Worship. The Trumpet Blast, And The Resurrection Of Those Who Are In Their Graves","بَاب فِي خُرُوجِ الدَّجَّالِ وَمُكْثِهِ فِي الْأَرْضِ وَنُزُولِ عِيسَى وَقَتْلِهِ إِيَّاهُ","23"],[147,"Chapter: Al-Jassasah","باب { قِصَّةِ الْجَسَّاسَةِ }","24"],[153,"Chapter: The Rest Of The Ahadith About Ad-Dajjal","باب فِي بَقِيَّةٍ مِنْ أَحَادِيثِ الدَّجَّالِ","25"],[161,"Chapter: The Virtue Of Worship At Times Of Turmoil","باب فَضْلِ الْعِبَادَةِ فِي الْهَرْجِ","26"],[163,"Chapter: The Approach Of The Hour","باب قُرْبِ السَّاعَةِ","27"],[175,"Chapter: Between The Blasts (Of The Trumpet)","باب مَا بَيْنَ النَّفْخَتَيْنِ","28"]],"55":[[47,"Chapter: The Prohibition Of Entering Upon The People Of Al-Hijr (The Rocky Tract) Unless One Enters Weeping","باب لاَ تَدْخُلُوا مَسَاكِنَ الَّذِينَ ظَلَمُوا أَنْفُسَهُمْ إِلاَّ أَنْ تَكُونُوا بَاكِينَ .","1"],[51,"Chapter: The Virtue Of Treating Widows, The Poor And Orphans Kindly","باب الإِحْسَانِ إِلَى الأَرْمَلَةِ وَالْمِسْكِينِ وَالْيَتِيمِ","2"],[53,"Chapter: The Virtue Of Building Masajid","باب فَضْلِ بِنَاءِ الْمَسَاجِدِ","3"],[56,"Chapter: The Virtue Of Spending On The Poor And Wayfarers","باب الصَّدَقَةِ فِي الْمَسَاكِينِ","4"],[58,"Chapter: The Prohibition On Showing Off","باب مَنْ أَشْرَكَ فِي عَمَلِهِ غَيْرَ اللَّهِ","5"],[64,"Chapter: Guarding The Tongue","باب التَّكَلُّمِ بِالْكَلِمَةِ يَهْوِي بِهَا فِي النَّارِ","6"],[66,"Chapter: About The One Who Enjoins Good But Does Not Do It, And Forbids Evil But Does It","باب عُقُوبَةِ مَنْ يَأْمُرُ بِالْمَعْرُوفِ وَلاَ يَفْعَلُهُ وَيَنْهَى عَنِ الْمُنْكَرِ وَيَفْعَلُهُ","7"],[68,"Chapter: The Prohibition Against Disclosing One's Own Sins","باب النَّهْىِ عَنْ هَتْكِ الإِنْسَانِ، سِتْرَ نَفْسِهِ","8"],[69,"Chapter: Saying: \"May Allah Have Mercy On You\" To One Who Sneezes, And Yawning Is Disliked","باب تَشْمِيتِ الْعَاطِسِ وَكَرَاهَةِ التَّثَاؤُبِ","9"],[78,"Chapter: Miscellaneous Ahadith","باب فِي أَحَادِيثَ مُتَفَرِّقَةٍ","10"],[79,"Chapter: Mice Are A Transformed Race","باب فِي الْفَأْرِ وَأَنَّهُ مَسْخٌ","11"],[81,"Chapter: A Believer Should Not Be Stung Twice From The Same Hole","باب لاَ يُلْدَغُ الْمُؤْمِنُ مِنْ جُحْرٍ مَرَّتَيْنِ","12"],[82,"Chapter: The Believer's Affair Is All Good","باب الْمُؤْمِنُ أَمْرُهُ كُلُّهُ خَيْرٌ","13"],[83,"Chapter: The Prohibition Of Praising if It Involves Exaggeration And There Is The Fear That It May Be A Source Of Temptation (Fitnah) For The One Who Is Praised","باب النَّهْىِ عَنِ الْمَدْحِ، إِذَا كَانَ فِيهِ إِفْرَاطٌ وَخِيفَ مِنْهُ فِتْنَةٌ عَلَى الْمَمْدُوحِ","14"],[90,"Chapter: Showing Preference To The One Who Is Older","باب مُنَاوَلَةِ الأَكْبَرِ","15"],[91,"Chapter: Verification Of Hadith And The Ruling On Writing Down Knowledge","باب التَّثَبُّتِ فِي الْحَدِيثِ وَحُكْمِ كِتَابَةِ الْعِلْمِ","16"],[93,"Chapter: The Story Of The People Of The Ditch And The Magician, The Monk And The Boy","باب قِصَّةِ أَصْحَابِ الأُخْدُودِ وَالسَّاحِرِ وَالرَّاهِبِ وَالْغُلاَمِ","17"],[94,"Chapter: The Lengthy Hadith Of Jabir And The Story Of Abu Al-Yasar","باب حَدِيثِ جَابِرٍ الطَّوِيلِ وَقِصَّةِ أَبِي الْيَسَرِ","18"],[95,"Chapter: The Hadith Of The Hijrah","باب فِي حَدِيثِ الْهِجْرَةِ وَيُقَالُ لَهُ حَدِيثُ الرَّحْلِ","19"]],"56":[[28,"Chapter: Allah's Saying: \"Has Not The Time Come For The Hearts Of Those Who Believe To Be Affected By Allah's Reminder\"","باب فِي قَوْلِهِ تَعَالَى { أَلَمْ يَأْنِ لِلَّذِينَ آمَنُوا أَنْ تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ اللَّهِ}","1"],[29,"Chapter: Allah's Saying: \"O Children Of Adam! Take Your Adornment While Praying\"","باب فِي قَوْلِهِ تَعَالَى {خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ}","2"],[30,"Chapter: Allah's Saying: \"And Force Not Your Maids To Prostitution\"","باب فِي قَوْلِهِ تَعَالَى {وَلاَ تُكْرِهُوا فَتَيَاتِكُمْ عَلَى الْبِغَاءِ}","3"],[32,"Chapter: Allah's Saving: \"Those Whom They Call Upon Desire Means Of Access To Their Lord (Allah)\"","باب فِي قَوْلِهِ تَعَالَى { أُولَئِكَ الَّذِينَ يَدْعُونَ يَبْتَغُونَ إِلَى رَبِّهِمْ الْوَسِيلَةَ}","4"],[35,"Chapter: Sural Baraah (Ar-Tawbah), Al-Anfal And Al-Hashr","باب فِي سُورَةِ بَرَاءَةَ وَالأَنْفَالِ وَالْحَشْرِ","5"],[36,"Chapter: Revelation Of The Prohibition On Khamr","باب فِي نُزُولِ تَحْرِيمِ الْخَمْرِ","6"],[39,"Chapter: Allah's Saying: \"These Two Opponents Dispute With Each Other About Their Lord\"","باب فِي قَوْلِهِ تَعَالَى {هَذَانِ خَصْمَانِ اخْتَصَمُوا فِي رَبِّهِمْ}","7"]]};
